package com.patchpilot;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(PatchPilotConfig.GROUP)
public interface PatchPilotConfig extends Config
{
	String GROUP = "patchpilot";

	@ConfigItem(
		keyName = "useShortestPath",
		name = "Use Shortest Path",
		description = "When installed Shortest Path is used to navigate you to your next patch.",
		position = 1
	)
	default boolean useShortestPath()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPatchStatus",
		name = "Show patch status",
		description = "Show what's growing in each patch and when it will be ready. Requires Time Tracking plugin"
			+ " to be enabled.",
		position = 2
	)
	default boolean showPatchStatus()
	{
		return true;
	}

	@ConfigItem(
		keyName = "filterBank",
		name = "Filter bank during run",
		description = "Opening a bank during a bank stop during a run automatically filters the bank. You can"
			+ " manually toggle with the icon in the top right of the bank interface. Requires 'Bank Tags' plugin"
			+ " to be enabled.",
		position = 4
	)
	default boolean filterBank()
	{
		return false;
	}

	@ConfigItem(
		keyName = "guideColour",
		name = "Guide colour",
		description = "The colour of the arrow on the mini map and the outline around your next patch.",
		position = 3
	)
	default Color guideColour()
	{
		return new Color(0x6EE16E);
	}
}

package com.patchpilot;

import com.google.inject.Provides;
import com.patchpilot.guide.BankFilter;
import com.patchpilot.guide.FactsWatcher;
import com.patchpilot.guide.Gardeners;
import com.patchpilot.guide.GuideOverlay;
import com.patchpilot.guide.Guidance;
import com.patchpilot.guide.MinimapArrowOverlay;
import com.patchpilot.guide.NeededItemsOverlay;
import com.patchpilot.guide.PatchObjects;
import com.patchpilot.guide.ProgressWatcher;
import com.patchpilot.guide.RunGuide;
import com.patchpilot.guide.StatusOverlay;
import com.patchpilot.setup.RunProgress;
import com.patchpilot.setup.SetupStore;
import com.patchpilot.status.TimeTrackingStatus;
import com.patchpilot.ui.PatchPilotPanel;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Patch Pilot",
	description = "Plan your farm runs with a fully customisable list of patches, in any order you choose"
		+ " including bank stops to re-stock along the way for long runs.",
	tags = {"farming", "tree", "run"}
)
@PluginDependency(BankTagsPlugin.class)
public class PatchPilotPlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SetupStore setupStore;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Guidance guidance;

	@Inject
	private GuideOverlay guideOverlay;

	@Inject
	private MinimapArrowOverlay minimapArrowOverlay;

	@Inject
	private NeededItemsOverlay neededItemsOverlay;

	@Inject
	private PatchObjects patchObjects;

	@Inject
	private Gardeners gardeners;

	@Inject
	private StatusOverlay statusOverlay;

	@Inject
	private TimeTrackingStatus timeTrackingStatus;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ProgressWatcher progressWatcher;

	@Inject
	private FactsWatcher factsWatcher;

	@Inject
	private BankFilter bankFilter;

	private RunGuide guide;
	private volatile boolean progressUnsaved;
	@Nullable
	private PatchPilotPanel panel;
	@Nullable
	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		guide = new RunGuide(setupStore::loadRuns, setupStore::loadCropSetup, this::saveProgress);
		guide.restore(setupStore.loadProgress());
		eventBus.register(patchObjects);
		eventBus.register(gardeners);
		clientThread.invoke(patchObjects::scan);
		clientThread.invoke(gardeners::scan);
		guidance.start(guide);
		eventBus.register(guidance);
		progressWatcher.start(guide);
		eventBus.register(progressWatcher);
		clientThread.invoke(progressWatcher::readHeld);
		eventBus.register(factsWatcher);
		clientThread.invoke(factsWatcher::readVarbits);
		eventBus.register(bankFilter);
		bankFilter.start(guide);
		overlayManager.add(guideOverlay);
		overlayManager.add(minimapArrowOverlay);
		overlayManager.add(statusOverlay);
		overlayManager.add(neededItemsOverlay);

		RunGuide panelGuide = guide;
		SwingUtilities.invokeLater(() ->
		{
			panel = new PatchPilotPanel(setupStore, panelGuide, timeTrackingStatus, itemManager, spriteManager,
				clientThread);
			navigationButton = NavigationButton.builder()
				.tooltip("Patch Pilot")
				.icon(ImageUtil.loadImageResource(PatchPilotPlugin.class, "icon.png"))
				.priority(6)
				.panel(panel)
				.build();
			clientToolbar.addNavigation(navigationButton);
		});
		log.debug("Patch Pilot started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(guideOverlay);
		overlayManager.remove(minimapArrowOverlay);
		overlayManager.remove(statusOverlay);
		overlayManager.remove(neededItemsOverlay);
		eventBus.unregister(guidance);
		guidance.stop();
		eventBus.unregister(progressWatcher);
		progressWatcher.stop();
		eventBus.unregister(factsWatcher);
		eventBus.unregister(bankFilter);
		bankFilter.stop();
		eventBus.unregister(patchObjects);
		patchObjects.clear();
		eventBus.unregister(gardeners);
		gardeners.clear();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.stop();
			}
			if (navigationButton != null)
			{
				clientToolbar.removeNavigation(navigationButton);
			}
			navigationButton = null;
			panel = null;
		});
		log.debug("Patch Pilot stopped");
	}

	private void saveProgress(@Nullable RunProgress progress)
	{
		if (setupStore.hasCharacter())
		{
			setupStore.saveProgress(progress);
			progressUnsaved = false;
		}
		else
		{
			progressUnsaved = true;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		RunProgress saved = setupStore.loadProgress();
		if (saved == null && progressUnsaved)
		{
			setupStore.saveProgress(guide.progress());
		}
		else
		{
			guide.restore(saved);
		}
		progressUnsaved = false;
		characterChanged();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (TimeTrackingStatus.GROUP.equals(event.getGroup()))
		{
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.patchesSeen();
				}
			});
		}
		else if (PatchPilotConfig.GROUP.equals(event.getGroup()) && SetupStore.FACTS_KEY.equals(event.getKey()))
		{
			characterChanged();
		}
	}

	private void characterChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.characterChanged();
			}
		});
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		guide.restore(setupStore.loadProgress());
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.reload();
			}
		});
	}

	@Provides
	PatchPilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PatchPilotConfig.class);
	}
}

package com.patchpilot.data;

import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
public class Bank
{
	String key;
	String name;
	WorldPoint location;
	@Nullable
	String quest;

	public String getLabel()
	{
		int side = name.indexOf(" (");
		return side < 0 ? name + " bank" : name.substring(0, side) + " bank" + name.substring(side);
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.patchpilot.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

public final class BankCatalog
{
	private static final String FILE = "banks.tsv";
	private static final List<Bank> BANKS = load();

	private BankCatalog()
	{
	}

	public static List<Bank> all()
	{
		return BANKS;
	}

	@Nullable
	public static Bank find(@Nullable String key)
	{
		for (Bank bank : BANKS)
		{
			if (bank.getKey().equals(key))
			{
				return bank;
			}
		}
		return null;
	}

	private static List<Bank> load()
	{
		InputStream in = BankCatalog.class.getResourceAsStream(FILE);
		if (in == null)
		{
			throw new IllegalStateException(FILE + " is missing from the plugin");
		}
		List<Bank> banks = new ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				banks.add(parse(line));
			}
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Couldn't read " + FILE, e);
		}
		return Collections.unmodifiableList(banks);
	}

	static Bank parse(String line)
	{
		String[] cells = line.split("\t", -1);
		if (cells.length != 6)
		{
			throw new IllegalArgumentException("Expected 6 columns in " + FILE + ": " + line);
		}
		WorldPoint location = new WorldPoint(
			Integer.parseInt(cells[2]), Integer.parseInt(cells[3]), Integer.parseInt(cells[4]));
		String quest = cells[5].isEmpty() ? null : cells[5];
		return new Bank(cells[0], cells[1], location, quest);
	}
}

