public final class CropCatalog
{
	private static final Map<PatchType, List<Crop>> CROPS = build();

	private CropCatalog()
	{
	}

	public static List<Crop> crops(PatchType type)
	{
		return CROPS.getOrDefault(type, Collections.emptyList());
	}

	@Nullable
	public static Crop find(PatchType type, @Nullable String key)
	{
		if (key == null)
		{
			return null;
		}
		for (Crop crop : crops(type))
		{
			if (crop.getKey().equals(key))
			{
				return crop;
			}
		}
		return null;
	}

	public static boolean protectable(PatchType type)
	{
		for (Crop crop : crops(type))
		{
			if (crop.getPayment() != null)
			{
				return true;
			}
		}
		return false;
	}

