		piece("Farmer's boots", ItemID.TITHE_REWARD_FEET_MALE, "feet", 0.002, ItemID.TITHE_REWARD_FEET_FEMALE)),
	FARMING_CAPE("Farming cape", true,
		piece("Farming cape", ItemID.SKILLCAPE_FARMING, "cape", 0)),
	GRACEFUL("Graceful outfit", true,
		piece("Graceful hood", ItemID.GRACEFUL_HOOD, "head", 0),
		piece("Graceful cape", ItemID.GRACEFUL_CAPE, "cape", 0),
		piece("Graceful top", ItemID.GRACEFUL_TOP, "body", 0),
		piece("Graceful legs", ItemID.GRACEFUL_LEGS, "legs", 0),
		piece("Graceful gloves", ItemID.GRACEFUL_GLOVES, "hands", 0),
		piece("Graceful boots", ItemID.GRACEFUL_BOOTS, "feet", 0)),
	MAGIC_SECATEURS("Magic secateurs", false,
		piece("Magic secateurs", ItemID.FAIRY_ENCHANTED_SECATEURS, "weapon", 0)),
	HERB_SACK("Herb sack", false,
		piece("Herb sack", ItemID.SLAYER_HERB_SACK, null, 0, ItemID.SLAYER_HERB_SACK_SILK));

	public static final double FARMERS_SET_BONUS = 0.005;

	private final String displayName;
	private final boolean wornOnly;
	private final List<Piece> pieces;

	Gear(String displayName, boolean wornOnly, Piece... pieces)
	{
		this.displayName = displayName;
		this.wornOnly = wornOnly;
		this.pieces = Collections.unmodifiableList(Arrays.asList(pieces));
	}

	@Value
	public static class Piece
	{
		String name;
		int itemId;
		@Nullable
		String slot;
		double xpBonus;
		Set<Integer> alsoCounts;
	}

	private static Piece piece(String name, int itemId, @Nullable String slot, double xpBonus, int... others)
	{
		Set<Integer> also = new HashSet<>(ItemVariationMapping.getVariations(ItemVariationMapping.map(itemId)));
		for (int other : others)
		{
			also.addAll(ItemVariationMapping.getVariations(ItemVariationMapping.map(other)));
		}
		also.remove(itemId);
		return new Piece(name, itemId, slot, xpBonus, Collections.unmodifiableSet(also));
	}
}

