	}

	private static void add(List<PatchLocation> list, PatchType type, String name, int x, int y,
		int objectId, int varbit, int gardenerNpcId, int timeTrackingRegion)
	{
		list.add(new PatchLocation(key(type, name), type, name, new WorldPoint(x, y, 0),
			objectId, varbit, gardenerNpcId, timeTrackingRegion));
	}

	static String key(PatchType type, String name)
	{
		String place = name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_").replaceAll("^_|_$", "");
		return type.name().toLowerCase(Locale.ROOT) + "_" + place;
	}
