package com.patchpilot.data;

import java.util.Locale;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
public class PatchLocation
{
	String key;
	PatchType type;
	String name;
	WorldPoint location;
	int objectId;
	int varbit;
	int gardenerNpcId;
	int timeTrackingRegion;

	public String getLabel()
	{
		String kind = type.getDisplayName().toLowerCase(Locale.ROOT);
		int side = name.indexOf(" (");
		return side < 0 ? name + " " + kind : name.substring(0, side) + " " + kind + name.substring(side);
	}

	@Override
	public String toString()
	{
		return getLabel();
	}
}

