				ItemID.STEAM_BATTLESTAFF, ItemID.LAVA_BATTLESTAFF, ItemID.MYSTIC_SMOKE_BATTLESTAFF,
				ItemID.MYSTIC_STEAM_BATTLESTAFF, ItemID.MYSTIC_LAVA_STAFF, ItemID.TWINFLAME_STAFF,
				ItemID.SHADOWFLAME_QUADRANT, ItemID.TOME_OF_FIRE));
