		rune(ItemID.SOULRUNE, ids(ItemID.AETHERRUNE), ids());
		rune(ItemID.COSMICRUNE, ids(ItemID.AETHERRUNE), ids());
	}

	private Runes()
	{
	}

	static Set<Integer> alsoCounts(int rune)
	{
		return ALSO_COUNTS.getOrDefault(rune, Collections.emptySet());
	}

	static Set<Integer> suppliedBy(int rune)
	{
		return SUPPLIED_BY.getOrDefault(rune, Collections.emptySet());
	}

	private static void rune(int rune, Set<Integer> alsoCounts, Set<Integer> suppliedBy)
	{
		ALSO_COUNTS.put(rune, alsoCounts);
		SUPPLIED_BY.put(rune, suppliedBy);
	}

	private static Set<Integer> ids(int... ids)
	{
		Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return Collections.unmodifiableSet(set);
	}
}

