package com.patchpilot.data;

import java.util.List;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

@Value
public class Teleport
{
	public enum Kind
	{
		TABLET,
		ITEM,
		WORN,
		SPELL,
		NONE
	}

	String key;
	String name;
	WorldPoint destination;
	Kind kind;
	List<Need> needs;
	@Nullable
	String wornSlot;

	@Value
	public static class Need
	{
		int itemId;
		String name;
		int quantity;
		Set<Integer> alsoCounts;
		Set<Integer> suppliedBy;
	}

	public String shortName()
	{
		int colon = name.indexOf(':');
		if (colon < 0)
		{
			return name;
		}
		String before = name.substring(0, colon);
		if (isFairyRing())
		{
			String after = name.substring(colon + 1).trim();
			int space = after.indexOf(' ');
			return before + " " + (space < 0 ? after : after.substring(0, space));
		}
		return before;
	}

	public boolean isFairyRing()
	{
		return name.startsWith("Fairy ring:");
	}

	public String spokenName()
	{
		int colon = name.indexOf(':');
		return colon < 0 ? name : name.substring(0, colon) + " to " + name.substring(colon + 1).trim();
	}

	public int pictureItemId()
	{
		if (needs.isEmpty())
		{
			return -1;
		}
		return kind == Kind.SPELL ? needs.get(needs.size() - 1).getItemId() : needs.get(0).getItemId();
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.patchpilot.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

public final class TeleportCatalog
{
	public static final int REACH = 100;
	private static final String FILE = "teleports.tsv";
	private static final List<Teleport> TELEPORTS = load();

	private TeleportCatalog()
	{
	}

	public static List<Teleport> all()
	{
		return TELEPORTS;
	}

	@Nullable
	public static Teleport find(@Nullable String key)
	{
		for (Teleport teleport : TELEPORTS)
		{
			if (teleport.getKey().equals(key))
			{
				return teleport;
			}
		}
		return null;
	}

	public static List<Teleport> near(WorldPoint place)
	{
		List<Teleport> near = new ArrayList<>();
		for (Teleport teleport : TELEPORTS)
		{
			if (distance(teleport, place) <= REACH)
			{
				near.add(teleport);
			}
		}
		near.sort(Comparator.comparingInt(teleport -> distance(teleport, place)));
		return near;
	}

	public static int distance(Teleport teleport, WorldPoint place)
	{
		WorldPoint lands = teleport.getDestination();
		return Math.max(Math.abs(lands.getX() - place.getX()), Math.abs(lands.getY() - place.getY()));
	}

	private static List<Teleport> load()
	{
		InputStream in = TeleportCatalog.class.getResourceAsStream(FILE);
		if (in == null)
		{
			throw new IllegalStateException(FILE + " is missing from the plugin");
		}
		List<Teleport> teleports = new ArrayList<>();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				teleports.add(parse(line));
			}
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Couldn't read " + FILE, e);
		}
		return Collections.unmodifiableList(teleports);
	}

	static Teleport parse(String line)
	{
		String[] cells = line.split("\t", -1);
		if (cells.length != 9)
		{
			throw new IllegalArgumentException("Expected 9 columns in " + FILE + ": " + line);
		}
		WorldPoint destination = new WorldPoint(
			Integer.parseInt(cells[2]), Integer.parseInt(cells[3]), Integer.parseInt(cells[4]));
		Teleport.Kind kind = Teleport.Kind.valueOf(cells[5].toUpperCase(Locale.ROOT));
		List<Teleport.Need> needs = new ArrayList<>();
		if (!cells[7].isEmpty())
		{
			String[] names = cells[6].split("&&");
			String[] alternatives = cells[7].split("\\|\\|");
			String[] first = alternatives[0].split("&&");
			for (int i = 0; i < first.length; i++)
			{
				int itemId = itemId(first[i]);
				Set<Integer> alsoCounts = new HashSet<>();
				for (int a = 1; a < alternatives.length; a++)
				{
					String[] other = alternatives[a].split("&&");
					if (i < other.length)
					{
						alsoCounts.add(itemId(other[i]));
					}
				}
				Set<Integer> suppliedBy = Collections.emptySet();
				if (kind == Teleport.Kind.SPELL)
				{
					alsoCounts.addAll(Runes.alsoCounts(itemId));
					suppliedBy = Runes.suppliedBy(itemId);
				}
				needs.add(new Teleport.Need(itemId, names[Math.min(i, names.length - 1)], quantity(first[i]),
					Collections.unmodifiableSet(alsoCounts), suppliedBy));
			}
		}
		return new Teleport(cells[0], cells[1], destination, kind, Collections.unmodifiableList(needs),
			cells[8].isEmpty() ? null : cells[8]);
	}

	private static int itemId(String item)
	{
		return Integer.parseInt(item.substring(0, item.indexOf('=')));
	}

	private static int quantity(String item)
	{
		return Integer.parseInt(item.substring(item.indexOf('=') + 1));
	}
}

