package com.patchpilot.guide;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;

final class Arrows
{
	private Arrows()
	{
	}

	static void draw(Graphics2D g, double fromX, double fromY, double toX, double toY, Color colour, float width)
	{
		double angle = Math.atan2(toY - fromY, toX - fromX);
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		double headLength = width * 2 + 2;
		double headHalfWidth = width * 1.5 + 1;
		double baseX = toX - cos * headLength;
		double baseY = toY - sin * headLength;

		Path2D head = new Path2D.Double();
		head.moveTo(toX, toY);
		head.lineTo(baseX + sin * headHalfWidth, baseY - cos * headHalfWidth);
		head.lineTo(baseX - sin * headHalfWidth, baseY + cos * headHalfWidth);
		head.closePath();
		Line2D shaft = new Line2D.Double(fromX, fromY, baseX + cos, baseY + sin);

		Graphics2D arrow = (Graphics2D) g.create();
		arrow.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		arrow.setColor(Color.BLACK);
		arrow.setStroke(new BasicStroke(width + 2, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		arrow.draw(shaft);
		arrow.setStroke(new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		arrow.draw(head);
		arrow.fill(head);

		arrow.setColor(colour);
		arrow.setStroke(new BasicStroke(width, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		arrow.draw(shaft);
		arrow.fill(head);
		arrow.dispose();
	}
}

