@Singleton
public class BankFilter
{
	private static final String TAG = "patch pilot";
	private static final String PLUGINS_GROUP = "runelite";
	private static final String BANK_TAGS_PLUGIN = "banktagsplugin";
	private static final int BUTTON_X = 380;
	private static final int BUTTON_Y = 5;
	private static final int BUTTON_SIZE = 25;
	private static final int ICON_INSET = 3;
	private static final String NAME = "<col=ff9040>Patch Pilot</col>";

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private TagManager tagManager;
	@Inject
	private BankTagsService bankTags;
	@Inject
	private LayoutManager layoutManager;
	@Inject
	private PatchPilotConfig config;
	@Inject
	private ConfigManager configManager;

	@Nullable
	private volatile RunGuide guide;
	private volatile Set<Integer> items = Collections.emptySet();
	private final Runnable guideListener = this::guideChanged;
	@Nullable
	private String seenStep;
	@Nullable
	private Widget button;
	@Nullable
	private Widget icon;

	public void start(RunGuide runGuide)
	{
		guide = runGuide;
		tagManager.registerTag(TAG, id -> items.contains(id));
		runGuide.onChange(guideListener);
	}

	public void stop()
	{
		RunGuide was = guide;
		guide = null;
		if (was != null)
		{
			was.removeListener(guideListener);
		}
		clientThread.invoke(() ->
		{
			hide();
			removeButton();
			tagManager.unregisterTag(TAG);
		});
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.BANKMAIN || !bankTagsOn())
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			seenStep = step();
			if (loadout() != null && config.filterBank())
			{
				show();
			}
			else if (filtered())
			{
				hide();
			}
			updateButton();
		});
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			button = null;
			icon = null;
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING && bankTagsOn())
		{
			updateButton();
		}
	}

	private void guideChanged()
	{
		clientThread.invokeLater(() ->
		{
			String step = step();
			if (Objects.equals(step, seenStep) || !bankOpen() || !bankTagsOn())
			{
				seenStep = step;
				return;
			}
			seenStep = step;
			if (loadout() != null && config.filterBank())
			{
				show();
			}
			updateButton();
		});
	}

	private void toggle()
	{
		if (filtered())
		{
			hide();
		}
		else
		{
			show();
		}
		client.playSoundEffect(SoundEffectID.INTERFACE_SELECT1);
		updateButton();
	}

	private void show()
	{
		Leg leg = loadout();
		if (leg == null)
		{
			return;
		}
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		List<Integer> layout = layout(leg, id -> bank != null && bank.count(id) > 0);
		items = Collections.unmodifiableSet(new LinkedHashSet<>(layout));
		int[] slots = new int[layout.size()];
		for (int i = 0; i < slots.length; i++)
		{
			slots[i] = layout.get(i);
		}
		layoutManager.saveLayout(new Layout(TAG, slots));
		bankTags.closeBankTag();
		bankTags.openBankTag(TAG, 0);
	}

	private void hide()
	{
		if (bankTagsOn() && filtered())
		{
			bankTags.closeBankTag();
		}
		layoutManager.removeLayout(TAG);
	}

	private boolean filtered()
	{
		return TAG.equals(bankTags.getActiveTag());
	}

	private void updateButton()
	{
		Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (universe == null)
		{
			return;
		}
		boolean wanted = loadout() != null || filtered();
		if (wanted)
		{
			addButton(universe);
		}
		if (button == null || icon == null)
		{
			return;
		}
		button.setHidden(!wanted);
		icon.setHidden(!wanted);
		style();
	}

	private void addButton(Widget universe)
	{
		Widget[] children = universe.getDynamicChildren();
		if (button != null && children != null && Arrays.asList(children).contains(button))
		{
			return;
		}
		button = universe.createChild(-1, WidgetType.GRAPHIC);
		icon = universe.createChild(-1, WidgetType.GRAPHIC);
		place(button, 0);
		place(icon, ICON_INSET);
		icon.setSpriteId(SpriteID.Staticons2.FARMING);
		button.setName(NAME);
		button.setHasListener(true);
		button.setNoClickThrough(true);
		button.setOnMouseOverListener((JavaScriptCallback) ev ->
			button.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED));
		button.setOnMouseLeaveListener((JavaScriptCallback) ev -> style());
		button.setOnOpListener((JavaScriptCallback) ev -> toggle());
		style();
		button.revalidate();
		icon.revalidate();
	}

	private static void place(Widget widget, int inset)
	{
		widget.setOriginalX(BUTTON_X + inset);
		widget.setOriginalY(BUTTON_Y + inset);
		widget.setOriginalWidth(BUTTON_SIZE - 2 * inset);
		widget.setOriginalHeight(BUTTON_SIZE - 2 * inset);
	}

	private void style()
	{
		if (button == null)
		{
			return;
		}
		boolean loadoutShowing = filtered();
		button.setSpriteId(loadoutShowing ? SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED
			: SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
		button.setAction(0, loadoutShowing ? "Show the whole bank" : "Show the run's loadout");
	}

	private void removeButton()
	{
		Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (button != null)
		{
			button.setHidden(true);
		}
		if (icon != null)
		{
			icon.setHidden(true);
		}
		if (universe != null)
		{
			universe.revalidate();
		}
		button = null;
		icon = null;
	}

	static List<Integer> layout(Leg leg, IntPredicate inBank)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		for (LoadoutItem item : leg.getLoadout())
		{
			ids.add(bankId(item, inBank));
		}
		return new ArrayList<>(ids);
	}

	private static int bankId(LoadoutItem item, IntPredicate inBank)
	{
		List<Integer> candidates = new ArrayList<>();
		if (!item.isNoted())
		{
			candidates.add(item.getItemId());
		}
		candidates.addAll(item.getAlsoCounts());
		for (int candidate : candidates)
		{
			if (inBank.test(candidate))
			{
				return candidate;
			}
		}
		return candidates.isEmpty() ? item.getItemId() : candidates.get(0);
	}

	@Nullable
	private Leg loadout()
	{
		RunGuide current = guide;
		RunProgress progress = current == null ? null : current.progress();
		return progress == null ? null : current.loadoutFor(progress.getStop());
	}

	@Nullable
	private String step()
	{
		RunGuide current = guide;
		RunProgress progress = current == null ? null : current.progress();
		return progress == null ? null : progress.getRunId() + ":" + progress.getStop();
	}

	private boolean bankOpen()
	{
		return client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null;
	}

	private boolean bankTagsOn()
	{
		return !"false".equals(configManager.getConfiguration(PLUGINS_GROUP, BANK_TAGS_PLUGIN));
	}
}

package com.patchpilot.guide;

import com.patchpilot.data.Gear;
import com.patchpilot.setup.PlayerFacts;
import com.patchpilot.setup.SetupStore;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.eventbus.Subscribe;

@Singleton
public class FactsWatcher
{
	private static final int PLANTING_LEARNT = 3;
	private static final Map<Integer, Integer> WATCHED = watched();
	private static final Map<Integer, Integer> LEPRECHAUN = leprechaun();
	private static final Set<Integer> TOOL_VARBITS = new HashSet<>(LEPRECHAUN.keySet());

	static
	{
		TOOL_VARBITS.add(VarbitID.FARMING_TOOLS_FAIRYSECATEURS);
	}

	@Inject
	private Client client;
	@Inject
	private SetupStore setupStore;

	private boolean loggedIn;

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loggedIn = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (loggedIn)
		{
			loggedIn = false;
			readVarbits();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varbit = event.getVarbitId();
		if (varbit == VarbitID.BRUT_FARMING_PLANTING || TOOL_VARBITS.contains(varbit))
		{
			readVarbits();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			Set<Integer> owned = new HashSet<>();
			find(event.getItemContainer(), owned);
			find(client.getItemContainer(InventoryID.INV), owned);
			find(client.getItemContainer(InventoryID.WORN), owned);
			learn(facts ->
			{
				if (facts.getWithLeprechaun().contains(ItemID.FAIRY_ENCHANTED_SECATEURS))
				{
					owned.add(ItemID.FAIRY_ENCHANTED_SECATEURS);
				}
				facts.setOwned(owned);
				facts.setBankSeen(true);
			});
		}
		else if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			Set<Integer> seen = new HashSet<>();
			find(event.getItemContainer(), seen);
			learn(facts ->
			{
				Set<Integer> owned = new HashSet<>(facts.getOwned());
				owned.addAll(seen);
				facts.setOwned(owned);
			});
		}
	}

	public void readVarbits()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Set<Integer> tools = new HashSet<>();
		for (Map.Entry<Integer, Integer> tool : LEPRECHAUN.entrySet())
		{
			if (client.getVarbitValue(tool.getKey()) > 0)
			{
				tools.add(tool.getValue());
			}
		}
		boolean magic = tools.remove(ItemID.SECATEURS) && client.getVarbitValue(VarbitID.FARMING_TOOLS_FAIRYSECATEURS) == 1;
		if (magic)
		{
			tools.add(ItemID.FAIRY_ENCHANTED_SECATEURS);
		}
		boolean barehanded = client.getVarbitValue(VarbitID.BRUT_FARMING_PLANTING) >= PLANTING_LEARNT;
		learn(facts ->
		{
			facts.setWithLeprechaun(tools);
			facts.setPlantsBarehanded(barehanded);
			if (magic)
			{
				Set<Integer> owned = new HashSet<>(facts.getOwned());
				owned.add(ItemID.FAIRY_ENCHANTED_SECATEURS);
				facts.setOwned(owned);
			}
		});
	}

	private void learn(Consumer<PlayerFacts> change)
	{
		PlayerFacts facts = setupStore.loadFacts();
		PlayerFacts changed = setupStore.loadFacts();
		change.accept(changed);
		if (!changed.equals(facts))
		{
			setupStore.saveFacts(changed);
		}
	}

	private static void find(@Nullable ItemContainer container, Set<Integer> found)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			Integer counts = WATCHED.get(item.getId());
			if (counts != null)
			{
				found.add(counts);
			}
		}
	}

	private static Map<Integer, Integer> watched()
	{
		Map<Integer, Integer> map = new HashMap<>();
		for (Gear gear : Gear.values())
		{
			for (Gear.Piece piece : gear.getPieces())
			{
				map.put(piece.getItemId(), piece.getItemId());
				for (int other : piece.getAlsoCounts())
				{
					map.put(other, piece.getItemId());
				}
			}
		}
		for (int pouch : ItemVariationMapping.getVariations(ItemID.BH_RUNE_POUCH))
		{
			map.put(pouch, ItemID.BH_RUNE_POUCH);
		}
		map.put(ItemID.BH_RUNE_POUCH_TROUVER, ItemID.BH_RUNE_POUCH);
		map.put(ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH);
		map.put(ItemID.DIVINE_RUNE_POUCH_TROUVER, ItemID.DIVINE_RUNE_POUCH);
		return Collections.unmodifiableMap(map);
	}

	private static Map<Integer, Integer> leprechaun()
	{
		Map<Integer, Integer> map = new HashMap<>();
		map.put(VarbitID.FARMING_TOOLS_SPADE, ItemID.SPADE);
		map.put(VarbitID.FARMING_TOOLS_RAKE, ItemID.RAKE);
		map.put(VarbitID.FARMING_TOOLS_DIBBER, ItemID.DIBBER);
		map.put(VarbitID.FARMING_TOOLS_SECATEURS, ItemID.SECATEURS);
		return Collections.unmodifiableMap(map);
	}
}

package com.patchpilot.guide;

import com.patchpilot.data.PatchCatalog;
import com.patchpilot.data.PatchLocation;
import java.util.Collections;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.eventbus.Subscribe;

@Singleton
public class Gardeners
{
	private static final int REACH = 20;
	private static final Map<Integer, Integer> ALSO = Collections.singletonMap(
		NpcID.FROG_QUEST_MARCELLUS, NpcID.FROG_QUEST_MARCELLUS_FARMER);
	private static final Set<Integer> IDS = allIds();

	@Inject
	private Client client;

	private final Set<NPC> npcs = ConcurrentHashMap.newKeySet();

	@Nullable
	public NPC find(PatchLocation patch)
	{
		Set<Integer> ids = ids(patch);
		NPC best = null;
		int bestDistance = REACH + 1;
		for (NPC npc : npcs)
		{
			if (!matches(npc, ids))
			{
				continue;
			}
			int distance = npc.getWorldLocation().distanceTo2D(patch.getLocation());
			if (distance < bestDistance)
			{
				best = npc;
				bestDistance = distance;
			}
		}
		return best;
	}

	public void scan()
	{
		npcs.clear();
		WorldView view = client.getTopLevelWorldView();
		if (view == null)
		{
			return;
		}
		for (NPC npc : view.npcs())
		{
			remember(npc);
		}
	}

	public void clear()
	{
		npcs.clear();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		remember(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		npcs.remove(event.getNpc());
		remember(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		npcs.remove(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			npcs.clear();
		}
	}

	private void remember(@Nullable NPC npc)
	{
		if (npc != null && matches(npc, IDS))
		{
			npcs.add(npc);
		}
	}

	private static boolean matches(NPC npc, Set<Integer> ids)
	{
		if (ids.contains(npc.getId()))
		{
			return true;
		}
		NPCComposition shown = npc.getTransformedComposition();
		return shown != null && ids.contains(shown.getId());
	}

	private static Set<Integer> ids(PatchLocation patch)
	{
		Set<Integer> ids = new HashSet<>();
		if (patch.getGardenerNpcId() >= 0)
		{
			ids.add(patch.getGardenerNpcId());
			Integer also = ALSO.get(patch.getGardenerNpcId());
			if (also != null)
			{
				ids.add(also);
			}
		}
		return ids;
	}

	private static Set<Integer> allIds()
	{
		Set<Integer> ids = new HashSet<>();
		for (PatchLocation patch : PatchCatalog.all())
		{
			ids.addAll(ids(patch));
		}
		return Collections.unmodifiableSet(ids);
	}
}

package com.patchpilot.guide;

import com.patchpilot.PatchPilotConfig;
import com.patchpilot.data.PatchCatalog;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.plan.StopTasks;
import com.patchpilot.plan.Task;
import com.patchpilot.status.PatchStatus;
import com.patchpilot.status.TimeTrackingStatus;
import java.awt.image.BufferedImage;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

@Singleton
public class Guidance
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private EventBus eventBus;
	@Inject
	private ItemManager itemManager;
	@Inject
	private WorldMapPointManager worldMapPointManager;
	@Inject
	private PatchObjects patchObjects;
	@Inject
	private PatchPilotConfig config;
	@Inject
	private Gardeners gardeners;
	@Inject
	private TimeTrackingStatus statuses;

	@Nullable
	private RunGuide guide;
	@Nullable
	private WorldMapPoint mapPoint;
	@Nullable
	private Target shownTarget;
	@Nullable
	private WorldPoint pathTarget;
	@Nullable
	private volatile Task gardenerTask;
	private volatile Set<Integer> neededItems = Collections.emptySet();

	private final Runnable onChange = () -> clientThread.invoke(this::update);

	public void start(RunGuide guide)
	{
		this.guide = guide;
		guide.onChange(onChange);
		clientThread.invoke(this::update);
	}

	public void stop()
	{
		RunGuide stopping = guide;
		if (stopping != null)
		{
			stopping.removeListener(onChange);
		}
		guide = null;
		clientThread.invoke(() ->
		{
			shownTarget = null;
			gardenerTask = null;
			neededItems = Collections.emptySet();
			showOnMap(null);
			askForPath(null);
		});
	}

	@Nullable
	public Target target()
	{
		RunGuide current = guide;
		return current == null ? null : current.target();
	}

	public Collection<GameObject> targetPieces()
	{
		Target target = target();
		return target == null || target.getPatchKey() == null ? Collections.emptySet()
			: patchObjects.pieces(target.getPatchKey());
	}

	@Nullable
	public NPC gardener()
	{
		Target target = target();
		PatchLocation patch = target == null ? null : PatchCatalog.find(target.getPatchKey());
		return gardenerTask == null || patch == null ? null : gardeners.find(patch);
	}

	@Nullable
	public Task gardenerTask()
	{
		return gardenerTask;
	}

	public Set<Integer> neededItems()
	{
		return neededItems;
	}

	@Nullable
	public GameObject targetObject()
	{
		Target target = target();
		return target == null || target.getPatchKey() == null ? null : patchObjects.find(target.getPatchKey());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		askForPath(target());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (PatchPilotConfig.GROUP.equals(event.getGroup()) && "useShortestPath".equals(event.getKey()))
		{
			clientThread.invoke(() -> askForPath(target()));
		}
	}

	private void update()
	{
		Target target = target();
		if (!Objects.equals(target, shownTarget))
		{
			shownTarget = target;
			showOnMap(target);
		}
		askForPath(target);
		checkPatch();
	}

	private void checkPatch()
	{
		RunGuide current = guide;
		Target target = target();
		PatchLocation patch = target == null ? null : PatchCatalog.find(target.getPatchKey());
		if (current == null || patch == null)
		{
			gardenerTask = null;
			neededItems = Collections.emptySet();
			return;
		}
		PatchStatus status = statuses.status(patch);
		Set<Task> done = current.done(patch.getKey());
		List<StopTasks.Line> lines = StopTasks.lines(patch, current.crops(), status.getReading(), done);
		gardenerTask = StopTasks.gardenerNext(patch.getType(), lines);
		neededItems = StopTasks.notReady(status, done) ? Collections.emptySet()
			: StopTasks.itemsNext(patch.getType(), current.crops(), lines);
	}

	private void showOnMap(@Nullable Target target)
	{
		if (mapPoint != null)
		{
			worldMapPointManager.remove(mapPoint);
			mapPoint = null;
		}
		if (target == null)
		{
			return;
		}
		BufferedImage picture = itemManager.getImage(target.getPictureItemId());
		mapPoint = WorldMapPoint.builder()
			.worldPoint(target.getLocation())
			.image(picture)
			.name(target.getLabel())
			.tooltip(target.getLabel())
			.snapToEdge(true)
			.jumpOnClick(true)
			.build();
		worldMapPointManager.add(mapPoint);
	}

	private void askForPath(@Nullable Target target)
	{
		boolean inGame = client.getGameState().getState() >= GameState.LOADING.getState();
		WorldPoint wanted = target != null && inGame && config.useShortestPath() ? target.getLocation() : null;
		if (Objects.equals(wanted, pathTarget))
		{
			return;
		}
		if (wanted == null)
		{
			eventBus.post(new PluginMessage("shortestpath", "clear"));
		}
		else
		{
			Map<String, Object> data = new HashMap<>();
			data.put("target", wanted);
			eventBus.post(new PluginMessage("shortestpath", "path", data));
		}
		pathTarget = wanted;
	}
}

package com.patchpilot.guide;

import com.patchpilot.PatchPilotConfig;
import com.patchpilot.plan.Task;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.BasicStroke;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.util.Collection;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class GuideOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 4;

	private final Client client;
	private final Guidance guidance;
	private final ModelOutlineRenderer outlines;
	private final PatchPilotConfig config;

	@Inject
	GuideOverlay(Client client, Guidance guidance, ModelOutlineRenderer outlines, PatchPilotConfig config)
	{
		this.client = client;
		this.guidance = guidance;
		this.outlines = outlines;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Target target = guidance.target();
		WorldView view = client.getTopLevelWorldView();
		if (target == null || view == null || target.getLocation().getPlane() != view.getPlane())
		{
			return null;
		}
		Color colour = config.guideColour();

		NPC gardener = guidance.gardener();
		if (gardener != null)
		{
			outlines.drawOutline(gardener, OUTLINE_WIDTH, colour, OUTLINE_FEATHER);
			String what = guidance.gardenerTask() == Task.REMOVE ? "Pay to remove the tree" : "Pay to protect";
			OverlayUtil.renderActorOverlay(graphics, gardener, what, colour);
			return null;
		}

		Collection<GameObject> pieces = guidance.targetPieces();
		if (pieces.size() > 1)
		{
			outlineTiles(graphics, view, pieces, colour);
			return null;
		}
		GameObject object = guidance.targetObject();
		if (object != null)
		{
			outlines.drawOutline(object, OUTLINE_WIDTH, colour, OUTLINE_FEATHER);
			return null;
		}
		LocalPoint spot = LocalPoint.fromWorld(view, target.getLocation());
		Polygon tile = spot == null ? null : Perspective.getCanvasTilePoly(client, spot);
		if (tile != null)
		{
			OverlayUtil.renderPolygon(graphics, tile, colour);
		}
		return null;
	}

	private void outlineTiles(Graphics2D graphics, WorldView view, Collection<GameObject> pieces, Color colour)
	{
		Set<WorldPoint> tiles = new HashSet<>();
		for (GameObject piece : pieces)
		{
			tiles.add(piece.getWorldLocation());
		}
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(colour);
		g.setStroke(new BasicStroke(OUTLINE_WIDTH));
		int half = Perspective.LOCAL_HALF_TILE_SIZE;
		for (WorldPoint tile : tiles)
		{
			LocalPoint centre = LocalPoint.fromWorld(view, tile);
			if (centre == null)
			{
				continue;
			}
			if (!tiles.contains(tile.dx(0).dy(1)))
			{
				edge(g, view, centre, -half, half, half, half);
			}
			if (!tiles.contains(tile.dy(-1)))
			{
				edge(g, view, centre, -half, -half, half, -half);
			}
			if (!tiles.contains(tile.dx(1)))
			{
				edge(g, view, centre, half, -half, half, half);
			}
			if (!tiles.contains(tile.dx(-1)))
			{
				edge(g, view, centre, -half, -half, -half, half);
			}
		}
		g.dispose();
	}

	private void edge(Graphics2D g, WorldView view, LocalPoint centre, int x1, int y1, int x2, int y2)
	{
		Point from = Perspective.localToCanvas(client,
			new LocalPoint(centre.getX() + x1, centre.getY() + y1, view.getId()), view.getPlane());
		Point to = Perspective.localToCanvas(client,
			new LocalPoint(centre.getX() + x2, centre.getY() + y2, view.getId()), view.getPlane());
		if (from != null && to != null)
		{
			g.drawLine(from.getX(), from.getY(), to.getX(), to.getY());
		}
	}
}

package com.patchpilot.guide;

import com.patchpilot.PatchPilotConfig;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class MinimapArrowOverlay extends Overlay
{
	private static final float WIDTH = 3;
	private static final int NEAR_LENGTH = 12;
	private static final int NEAR_GAP = 2;
	private static final int EDGE_FROM = 50;
	private static final int EDGE_TO = 64;
	private static final int DIRECTION_TILES = 8;

	private final Client client;
	private final Guidance guidance;
	private final PatchPilotConfig config;

	@Inject
	MinimapArrowOverlay(Client client, Guidance guidance, PatchPilotConfig config)
	{
		this.client = client;
		this.guidance = guidance;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Target target = guidance.target();
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (target == null || player == null || view == null)
		{
			return null;
		}
		Color colour = config.guideColour();
		WorldPoint here = player.getWorldLocation();
		WorldPoint there = target.getLocation();

		double zoom = client.getMinimapZoom();
		double minimapTiles = zoom > 0 ? 64 / zoom : 16;
		LocalPoint local = LocalPoint.fromWorld(view, there);
		if (local != null && here.distanceTo2D(there) < minimapTiles)
		{
			Point spot = Perspective.localToMinimap(client, local);
			if (spot != null)
			{
				Arrows.draw(graphics, spot.getX(), spot.getY() - NEAR_GAP - NEAR_LENGTH,
					spot.getX(), spot.getY() - NEAR_GAP, colour, WIDTH);
				return null;
			}
		}

		Point centre = player.getMinimapLocation();
		LocalPoint from = player.getLocalLocation();
		double dx = there.getX() - here.getX();
		double dy = there.getY() - here.getY();
		double tiles = Math.hypot(dx, dy);
		if (centre == null || tiles == 0)
		{
			return null;
		}
		int step = DIRECTION_TILES * Perspective.LOCAL_TILE_SIZE;
		LocalPoint toward = new LocalPoint(from.getX() + (int) (dx / tiles * step), from.getY() + (int) (dy / tiles * step),
			from.getWorldView());
		Point way = Perspective.localToMinimap(client, toward);
		if (way == null)
		{
			return null;
		}
		double ux = way.getX() - centre.getX();
		double uy = way.getY() - centre.getY();
		double length = Math.hypot(ux, uy);
		if (length == 0)
		{
			return null;
		}
		ux /= length;
		uy /= length;
		Arrows.draw(graphics, centre.getX() + ux * EDGE_FROM, centre.getY() + uy * EDGE_FROM,
			centre.getX() + ux * EDGE_TO, centre.getY() + uy * EDGE_TO, colour, WIDTH);
		return null;
	}
}

