package com.patchpilot.guide;

import com.patchpilot.data.PatchCatalog;
import com.patchpilot.data.PatchLocation;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;

@Singleton
public class PatchObjects
{
	private static final int SEARCH_RADIUS = 3;

	private static final Map<Integer, List<PatchLocation>> BY_OBJECT = byObject();

	@Inject
	private Client client;

	private final Map<String, Set<GameObject>> pieces = new ConcurrentHashMap<>();

	@Nullable
	public GameObject find(String patchKey)
	{
		Set<GameObject> found = pieces.get(patchKey);
		PatchLocation patch = PatchCatalog.find(patchKey);
		if (found == null || patch == null)
		{
			return null;
		}
		GameObject best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (GameObject piece : found)
		{
			int distance = piece.getWorldLocation().distanceTo2D(patch.getLocation());
			if (distance < bestDistance)
			{
				best = piece;
				bestDistance = distance;
			}
		}
		return best;
	}

	public Collection<GameObject> pieces(String patchKey)
	{
		Set<GameObject> found = pieces.get(patchKey);
		return found == null ? Collections.emptySet() : Collections.unmodifiableSet(found);
	}

	public Map<String, GameObject> all()
	{
		Map<String, GameObject> all = new HashMap<>();
		for (String key : pieces.keySet())
		{
			GameObject object = find(key);
			if (object != null)
			{
				all.put(key, object);
			}
		}
		return all;
	}

	public void scan()
	{
		pieces.clear();
		WorldView view = client.getTopLevelWorldView();
		Scene scene = view == null ? null : view.getScene();
		if (scene == null)
		{
			return;
		}
		for (Tile[][] plane : scene.getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					if (tile == null)
					{
						continue;
					}
					for (GameObject object : tile.getGameObjects())
					{
						if (object != null)
						{
							remember(object);
						}
					}
				}
			}
		}
	}

	public void clear()
	{
		pieces.clear();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		remember(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject gone = event.getGameObject();
		List<PatchLocation> patches = BY_OBJECT.get(gone.getId());
		if (patches == null)
		{
			return;
		}
		for (PatchLocation patch : patches)
		{
			Set<GameObject> found = pieces.get(patch.getKey());
			if (found != null)
			{
				found.remove(gone);
				if (found.isEmpty())
				{
					pieces.remove(patch.getKey());
				}
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			pieces.clear();
		}
	}

	private void remember(GameObject object)
	{
		List<PatchLocation> patches = BY_OBJECT.get(object.getId());
		if (patches == null)
		{
			return;
		}
		for (PatchLocation patch : patches)
		{
			if (patches.size() == 1 || object.getWorldLocation().distanceTo(patch.getLocation()) <= SEARCH_RADIUS)
			{
				pieces.computeIfAbsent(patch.getKey(), key -> ConcurrentHashMap.newKeySet()).add(object);
			}
		}
	}

	private static Map<Integer, List<PatchLocation>> byObject()
	{
		Map<Integer, List<PatchLocation>> map = new HashMap<>();
		for (PatchLocation patch : PatchCatalog.all())
		{
			if (patch.getObjectId() >= 0)
			{
				map.computeIfAbsent(patch.getObjectId(), id -> new ArrayList<>()).add(patch);
			}
		}
		return map;
	}
}

package com.patchpilot.guide;

import com.patchpilot.plan.Task;
import java.util.EnumSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

final class PendingTasks
{
	static final int MIN_TICKS = 1;
	static final int MAX_TICKS = 5;

	private static final class Change
	{
		private final Set<Task> tasks = EnumSet.noneOf(Task.class);
		private int tick;
	}

	private final Map<String, Change> held = new LinkedHashMap<>();

	void add(String patchKey, Set<Task> tasks, int tick)
	{
		Change change = held.computeIfAbsent(patchKey, k -> new Change());
		change.tasks.addAll(tasks);
		change.tick = tick;
	}

	Map<String, Set<Task>> release(int tick, boolean animating)
	{
		Map<String, Set<Task>> released = new LinkedHashMap<>();
		Iterator<Map.Entry<String, Change>> changes = held.entrySet().iterator();
		while (changes.hasNext())
		{
			Map.Entry<String, Change> change = changes.next();
			int waited = tick - change.getValue().tick;
			if (waited >= MIN_TICKS && (!animating || waited >= MAX_TICKS))
			{
				released.put(change.getKey(), change.getValue().tasks);
				changes.remove();
			}
		}
		return released;
	}

	void clear()
	{
		held.clear();
	}
}

