@Singleton
public class ProgressWatcher
{
	private static final String COMPOST_SUFFIX = ".compost";
	private static final String PROTECTED_SUFFIX = ".protected";
	private static final int IDLE_ANIMATION = -1;
	private static final int[] POUCH_RUNES = {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6};
	private static final int[] POUCH_AMOUNTS = {VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6};

	@Inject
	private Client client;
	@Inject
	private ConfigManager configManager;
	@Inject
	private ClientThread clientThread;

	@Nullable
	private volatile RunGuide guide;
	private final PendingTasks pending = new PendingTasks();

	public void start(RunGuide runGuide)
	{
		guide = runGuide;
	}

	public void stop()
	{
		guide = null;
		clientThread.invoke(pending::clear);
	}

	public void readHeld()
	{
		RunGuide current = guide;
		if (current == null)
		{
			return;
		}
		Map<Integer, Integer> held = new HashMap<>();
		count(client.getItemContainer(InventoryID.INV), held);
		count(client.getItemContainer(InventoryID.WORN), held);
		if (holds(held, Tool.RUNE_POUCH))
		{
			countPouch(held);
		}
		current.setHeld(held);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		for (int i = 0; i < POUCH_RUNES.length; i++)
		{
			if (event.getVarbitId() == POUCH_RUNES[i] || event.getVarbitId() == POUCH_AMOUNTS[i])
			{
				readHeld();
				return;
			}
		}
	}

	private static boolean holds(Map<Integer, Integer> held, Tool tool)
	{
		if (held.containsKey(tool.getItemId()))
		{
			return true;
		}
		for (int other : tool.getAlternatives())
		{
			if (held.containsKey(other))
			{
				return true;
			}
		}
		return false;
	}

	private void countPouch(Map<Integer, Integer> held)
	{
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null)
		{
			return;
		}
		for (int i = 0; i < POUCH_RUNES.length; i++)
		{
			int rune = client.getVarbitValue(POUCH_RUNES[i]);
			int amount = client.getVarbitValue(POUCH_AMOUNTS[i]);
			int itemId = rune > 0 ? runes.getIntValue(rune) : 0;
			if (itemId > 0 && amount > 0)
			{
				held.merge(itemId, amount, Integer::sum);
			}
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
		{
			readHeld();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		RunGuide current = guide;
		if (current != null && event.getGroupId() == InterfaceID.BANKMAIN)
		{
			current.setBankOpen(true);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		RunGuide current = guide;
		if (current != null && event.getGroupId() == InterfaceID.BANKMAIN)
		{
			current.setBankOpen(false);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		RunGuide current = guide;
		if (current == null || !TimeTrackingStatus.GROUP.equals(event.getGroup()) || event.getProfile() == null
			|| !event.getProfile().equals(configManager.getRSProfileKey()))
		{
			return;
		}
		String key = event.getKey();
		Set<Task> tasks = EnumSet.noneOf(Task.class);
		PatchLocation patch;
		if (key.endsWith(COMPOST_SUFFIX))
		{
			patch = patchFor(key.substring(0, key.length() - COMPOST_SUFFIX.length()));
			if (event.getNewValue() != null)
			{
				tasks.add(Task.COMPOST);
			}
		}
		else if (key.endsWith(PROTECTED_SUFFIX))
		{
			patch = patchFor(key.substring(0, key.length() - PROTECTED_SUFFIX.length()));
			if ("true".equals(event.getNewValue()))
			{
				tasks.add(Task.PROTECT);
			}
		}
		else
		{
			patch = patchFor(key);
			if (patch != null)
			{
				tasks.addAll(StopTasks.doneBetween(patch.getType(), current.crops(),
					Growth.read(patch.getType(), event.getOldValue()),
					Growth.read(patch.getType(), event.getNewValue())));
			}
		}
		if (patch != null)
		{
			String patchKey = patch.getKey();
			clientThread.invoke(() ->
			{
				pending.add(patchKey, tasks, client.getTickCount());
			});
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tickOff(pending.release(client.getTickCount(), animating()));
	}

	private boolean animating()
	{
		Player player = client.getLocalPlayer();
		return player != null && player.getAnimation() != IDLE_ANIMATION;
	}

	private void tickOff(Map<String, Set<Task>> released)
	{
		RunGuide current = guide;
		if (current == null || released.isEmpty())
		{
			return;
		}
		for (Map.Entry<String, Set<Task>> patch : released.entrySet())
		{
			current.tasksDone(patch.getKey(), patch.getValue());
		}
		current.patchesChanged();
	}

	@Nullable
	private static PatchLocation patchFor(String key)
	{
		for (PatchLocation patch : PatchCatalog.all())
		{
			if (Growth.key(patch).equals(key))
			{
				return patch;
			}
		}
		return null;
	}

	private static void count(@Nullable ItemContainer container, Map<Integer, Integer> held)
	{
		if (container == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() > 0)
			{
				held.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
	}
}

package com.patchpilot.guide;

