import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import net.runelite.api.gameval.ItemID;

public class RunGuide
{
	private final Supplier<SavedRuns> loadRuns;
	private final Supplier<CropSetup> loadCrops;
	private final Consumer<RunProgress> saveProgress;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	@Nullable
	private volatile RunProgress progress;
	@Nullable
	private volatile RunProfile run;
	@Nullable
	private volatile Target target;
	private volatile Map<Integer, Integer> held = Collections.emptyMap();
	private volatile boolean bankOpen;
	private boolean bankVisited;

	public RunGuide(Supplier<SavedRuns> loadRuns, Supplier<CropSetup> loadCrops, Consumer<RunProgress> saveProgress)
	{
		this.loadRuns = loadRuns;
		this.loadCrops = loadCrops;
		this.saveProgress = saveProgress;
	}

	public void onChange(Runnable listener)
	{
		listeners.add(listener);
	}

	public void removeListener(Runnable listener)
	{
		listeners.remove(listener);
	}

	public synchronized void start(String runId)
	{
		RunProfile found = loadRuns.get().find(runId);
		if (found == null)
		{
			return;
		}
		RunProgress started = new RunProgress(runId, firstStep(found));
		started.setStartedAt(Instant.now().getEpochSecond());
		set(started, true);
		checkLoadout();
	}

	public synchronized void next()
	{
		RunProgress now = progress;
		RunProfile current = run;
		if (now == null || current == null)
		{
			return;
		}
		int step = now.getStop() + 1;
		while (step < current.getStops().size() && isStopDone(current, step, now))
		{
			step++;
		}
		set(step < current.getStops().size() ? now.atStop(step) : null, true);
		checkLoadout();
	}

	public synchronized void back()
	{
		RunProgress now = progress;
		RunProfile current = run;
		if (now != null && current != null && now.getStop() > firstStep(current))
		{
			set(now.atStop(now.getStop() - 1), true);
		}
	}

	public synchronized void goTo(int step)
	{
		RunProgress now = progress;
		RunProfile current = run;
		if (now != null && current != null && step >= firstStep(current) && step < current.getStops().size())
		{
			set(now.atStop(step), true);
		}
	}

	public synchronized void end()
	{
		set(null, true);
	}

	public synchronized void restore(@Nullable RunProgress saved)
	{
		set(saved, false);
	}

	public synchronized void refresh()
	{
		RunProgress now = progress;
		set(now, false);
		if (now != null && (progress == null || progress.getStop() != now.getStop()))
		{
			saveProgress.accept(progress);
		}
	}

	public synchronized void tasksDone(String patchKey, Set<Task> tasks)
	{
		RunProgress now = progress;
		RunProfile current = run;
		if (now == null || current == null || tasks.isEmpty() || stepOf(current, patchKey) < 0)
		{
			return;
		}
		RunProgress updated = now.atStop(now.getStop());
		List<String> names = updated.done().computeIfAbsent(patchKey, k -> new ArrayList<>());
		boolean added = false;
		for (Task task : tasks)
		{
			if (!names.contains(task.name()))
			{
				names.add(task.name());
				added = true;
			}
		}
		if (!added)
		{
			return;
		}
		set(updated, true);
		if (isStopDone(current, updated.getStop(), updated))
		{
			next();
		}
	}

	public void patchesChanged()
	{
		announce();
	}

	public synchronized void setHeld(Map<Integer, Integer> nowHeld)
	{
		held = Collections.unmodifiableMap(new HashMap<>(nowHeld));
		if (atLoadoutStep())
		{
			announce();
		}
		checkLoadout();
	}

	private boolean atLoadoutStep()
	{
		RunProgress now = progress;
		RunProfile current = run;
		if (now == null || current == null)
		{
			return false;
		}
		int step = now.getStop();
		return step == RunProgress.START
			|| step >= 0 && step < current.getStops().size() && current.getStops().get(step).isBank();
	}

	public synchronized void setBankOpen(boolean open)
	{
		bankOpen = open;
		if (open)
		{
			bankVisited = true;
		}
		announce();
		checkLoadout();
	}

	@Nullable
	public RunProgress progress()
	{
		RunProgress now = progress;
		return now == null ? null : now.atStop(now.getStop());
	}

	@Nullable
	public RunProfile run()
	{
		return run;
	}

	public boolean isDoing(String runId)
	{
		RunProgress now = progress;
		return now != null && now.getRunId().equals(runId);
	}

	@Nullable
	public Target target()
	{
		return target;
	}

	public CropSetup crops()
	{
		return loadCrops.get();
	}

	public Map<Integer, Integer> held()
	{
		return held;
	}

	public Map<Integer, Integer> heldForLoadout()
	{
		Map<Integer, Integer> all = new HashMap<>(held);
		for (int tool : loadCrops.get().facts().getWithLeprechaun())
		{
			all.merge(tool, 1, Math::max);
		}
		return all;
	}

	public boolean isBankOpen()
	{
		return bankOpen;
	}

	public Set<Task> done(String patchKey)
	{
		RunProgress now = progress;
		return now == null ? EnumSet.noneOf(Task.class) : done(now, patchKey);
	}

	public boolean isStepDone(int step)
	{
		RunProgress now = progress;
		RunProfile current = run;
		if (now == null || current == null)
		{
			return false;
		}
		if (step < now.getStop() && (step == RunProgress.START || current.getStops().get(step).isBank()))
		{
			return true;
		}
		return step >= 0 && isStopDone(current, step, now);
	}

	@Nullable
	public Leg loadoutFor(int step)
	{
		RunProfile current = run;
		if (current == null)
		{
			return null;
		}
		for (Leg leg : LoadoutPlanner.plan(current, loadCrops.get()))
		{
			if (leg.getStopIndex() == step && !leg.getPatches().isEmpty())
			{
				return leg;
			}
		}
		return null;
	}

	public int firstStep(RunProfile someRun)
	{
		List<Leg> legs = LoadoutPlanner.plan(someRun, loadCrops.get());
		return !legs.isEmpty() && !legs.get(0).getPatches().isEmpty() ? RunProgress.START : 0;
	}

	private void checkLoadout()
	{
		RunProgress now = progress;
		RunProfile current = run;
		if (now == null || current == null)
		{
			return;
		}
		int step = now.getStop();
		boolean bank = step >= 0 && current.getStops().get(step).isBank();
		if (step != RunProgress.START && !(bank && bankVisited && !bankOpen))
		{
			return;
		}
		Leg leg = loadoutFor(step);
		if (leg == null ? bank : LoadoutCheck.missing(leg.getLoadout(), heldForLoadout()).isEmpty())
		{
			next();
		}
	}

	private boolean isStopDone(RunProfile someRun, int step, RunProgress someProgress)
	{
		PatchLocation patch = someRun.getStops().get(step).patch();
		return patch != null && StopTasks.isDone(patch, loadCrops.get(), done(someProgress, patch.getKey()));
	}

	private static Set<Task> done(RunProgress someProgress, String patchKey)
	{
		Set<Task> tasks = EnumSet.noneOf(Task.class);
		for (String name : someProgress.done().getOrDefault(patchKey, Collections.emptyList()))
		{
			for (Task task : Task.values())
			{
				if (task.name().equals(name))
				{
					tasks.add(task);
				}
			}
		}
		return tasks;
	}

	private static int stepOf(RunProfile someRun, String patchKey)
	{
		List<RunStop> stops = someRun.getStops();
		for (int i = 0; i < stops.size(); i++)
		{
			if (stops.get(i).isPatch() && stops.get(i).getKey().equals(patchKey))
			{
				return i;
			}
		}
		return -1;
	}

	private void set(@Nullable RunProgress wanted, boolean save)
	{
		RunProfile found = wanted == null ? null : loadRuns.get().find(wanted.getRunId());
		if (found == null || found.getStops().isEmpty())
		{
			wanted = null;
			found = null;
		}
		else
		{
			int first = firstStep(found);
			int last = found.getStops().size() - 1;
			if (wanted.getStop() < first || wanted.getStop() > last)
			{
				wanted = wanted.atStop(Math.max(first, Math.min(wanted.getStop(), last)));
			}
		}
		Target newTarget = wanted == null || wanted.getStop() < 0 ? null : target(found.getStops().get(wanted.getStop()));
		boolean stepChanged = wanted == null || progress == null || wanted.getStop() != progress.getStop();
		boolean changed = !Objects.equals(wanted, progress) || !Objects.equals(newTarget, target);
		progress = wanted;
		run = found;
		target = newTarget;
		if (stepChanged)
		{
			bankVisited = bankOpen;
		}
		if (save)
		{
			saveProgress.accept(wanted);
		}
		if (changed)
		{
			announce();
		}
	}

	private void announce()
	{
		for (Runnable listener : listeners)
		{
			listener.run();
		}
	}

	@Nullable
	private Target target(RunStop stop)
	{
		PatchLocation patch = stop.patch();
		if (patch != null)
		{
			Crop crop = loadCrops.get().crop(patch.getType());
			if (crop == null)
			{
				crop = CropCatalog.crops(patch.getType()).get(0);
			}
			return new Target(patch.getLocation(), patch.getObjectId(), patch.getLabel(), patch.getType(),
				patch.getKey(), crop.getProduceItemId());
		}
		Bank bank = stop.bank();
		if (bank != null)
		{
			return new Target(bank.getLocation(), -1, bank.getLabel(), null, null, ItemID.COINS_10000);
		}
		return null;
	}
}

package com.patchpilot.guide;

import com.patchpilot.PatchPilotConfig;
import com.patchpilot.data.PatchCatalog;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.status.PatchStatus;
import com.patchpilot.status.TimeTrackingStatus;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class StatusOverlay extends Overlay
{
	private static final long REFRESH_MILLIS = 2000;
	private static final int LABEL_HEIGHT = 40;

	private static final Color GROWING = Color.WHITE;
	private static final Color READY = new Color(0x6EE16E);
	private static final Color DISEASED = new Color(0xE6961E);
	private static final Color DEAD = new Color(0xE61E1E);
	private static final Color EMPTY = new Color(0xA5A5A5);

	private final Client client;
	private final PatchObjects patchObjects;
	private final TimeTrackingStatus statuses;
	private final PatchPilotConfig config;
	private final Map<String, PatchStatus> cache = new HashMap<>();
	private long cachedAt;

	@Inject
	StatusOverlay(Client client, PatchObjects patchObjects, TimeTrackingStatus statuses, PatchPilotConfig config)
	{
		this.client = client;
		this.patchObjects = patchObjects;
		this.statuses = statuses;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<String, GameObject> objects = patchObjects.all();
		WorldView view = client.getTopLevelWorldView();
		if (!config.showPatchStatus() || objects.isEmpty() || view == null)
		{
			return null;
		}
		long millis = System.currentTimeMillis();
		if (millis - cachedAt > REFRESH_MILLIS)
		{
			cache.clear();
			cachedAt = millis;
		}
		long now = millis / 1000;
		for (Map.Entry<String, GameObject> entry : objects.entrySet())
		{
			GameObject object = entry.getValue();
			PatchLocation patch = PatchCatalog.find(entry.getKey());
			if (patch == null || object.getPlane() != view.getPlane())
			{
				continue;
			}
			PatchStatus status = cache.computeIfAbsent(entry.getKey(), key -> statuses.status(patch));
			if (status.getKind() == PatchStatus.Kind.UNKNOWN)
			{
				continue;
			}
			String text = label(status, now);
			Point at = Perspective.getCanvasTextLocation(client, graphics, object.getLocalLocation(), text, LABEL_HEIGHT);
			if (at != null)
			{
				OverlayUtil.renderTextLocation(graphics, at, text, colour(status));
			}
		}
		return null;
	}

	private static String label(PatchStatus status, long now)
	{
		if (status.getPlant() == null)
		{
			return status.describe(now);
		}
		String name = status.getPlant().getDisplayName();
		String state = status.describe(now);
		return name + " " + (status.getKind() == PatchStatus.Kind.GROWING ? state : state.toLowerCase());
	}

	private static Color colour(PatchStatus status)
	{
		switch (status.getKind())
		{
			case READY:
				return READY;
			case DISEASED:
				return DISEASED;
			case DEAD:
				return DEAD;
			case EMPTY:
				return EMPTY;
			default:
				return GROWING;
		}
	}
}

