package com.patchpilot.plan;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public final class LoadoutCheck
{
	private LoadoutCheck()
	{
	}

	public static int held(LoadoutItem item, Map<Integer, Integer> held)
	{
		for (int supplier : item.getSuppliedBy())
		{
			if (held.getOrDefault(supplier, 0) > 0)
			{
				return item.getQuantity();
			}
		}
		int count = held.getOrDefault(item.getItemId(), 0);
		for (int other : item.getAlsoCounts())
		{
			count += held.getOrDefault(other, 0);
		}
		return count;
	}

	public static List<LoadoutItem> missing(List<LoadoutItem> loadout, Map<Integer, Integer> held)
	{
		List<LoadoutItem> missing = new ArrayList<>();
		for (LoadoutItem item : loadout)
		{
			int short_ = item.getQuantity() - held(item, held);
			if (short_ > 0)
			{
				missing.add(item.withQuantity(short_));
			}
		}
		return missing;
	}
}

package com.patchpilot.plan;

