	{
		INVENTORY,
		WORN,
		RUNE_POUCH
	}

	int itemId;
	String name;
	int quantity;
	boolean stacks;
	boolean noted;
	Set<Integer> alsoCounts;
	Set<Integer> suppliedBy;
	Place place;

	public int slots()
	{
		if (place != Place.INVENTORY)
		{
