	}
}

package com.patchpilot.plan;

import com.patchpilot.data.Bank;
import com.patchpilot.data.Compost;
import com.patchpilot.data.Crop;
import com.patchpilot.data.Gear;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import com.patchpilot.data.Payment;
import com.patchpilot.data.Teleport;
import com.patchpilot.data.Tool;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunStop;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.gameval.ItemID;

public final class LoadoutPlanner
{
	public static final int INVENTORY_SLOTS = 28;
	private static final Set<Integer> NONE = Collections.emptySet();
	static final int FRUIT_PER_TREE = 6;
	private static final int BASE_LIVES = 3;
	private static final int SAVE_CHANCE_AT_99 = 80;
	private static final int ALLOTMENT_SAVE_CHANCE_AT_99 = 180;
	private static final double SECATEURS_BOOST = 0.10;
	private static final double FARMING_CAPE_BOOST = 0.05;
	private static final int WOAD_LEAVES = 3;
	private static final double LIMPWURT_ROOTS_AVERAGE = 7.45;

	private LoadoutPlanner()
	{
	}

	public static List<Leg> plan(RunProfile run, CropSetup setup)
	{
		List<Leg> legs = new ArrayList<>();
		int startIndex = -1;
		Bank bank = null;
		List<PatchLocation> patches = new ArrayList<>();
		List<Teleport> teleports = new ArrayList<>();
		List<RunStop> stops = run.getStops();
		for (int i = 0; i < stops.size(); i++)
		{
			RunStop stop = stops.get(i);
			if (stop.isBank())
			{
				legs.add(leg(startIndex, bank, patches, teleports, stop.teleport(), setup));
				startIndex = i;
				bank = stop.bank();
				patches = new ArrayList<>();
				teleports = new ArrayList<>();
			}
			else if (stop.patch() != null)
			{
				patches.add(stop.patch());
				teleports.add(stop.teleport());
			}
		}
		legs.add(leg(startIndex, bank, patches, teleports, null, setup));
		return legs;
	}

	private static Leg leg(int stopIndex, @Nullable Bank bank, List<PatchLocation> patches, List<Teleport> teleports,
		@Nullable Teleport toBank, CropSetup setup)
	{
		Map<Integer, LoadoutItem> loadout = new LinkedHashMap<>();
		Set<PatchType> missing = EnumSet.noneOf(PatchType.class);
		List<PatchLocation> planted = new ArrayList<>();
		for (PatchLocation patch : patches)
		{
			if (setup.crop(patch.getType()) == null)
			{
				missing.add(patch.getType());
			}
			else
			{
				planted.add(patch);
			}
		}

		if (!patches.isEmpty())
		{
			tool(loadout, setup, Tool.SPADE);
			tool(loadout, setup, Tool.RAKE);
		}
		if (sows(patches))
		{
			tool(loadout, setup, Tool.SEED_DIBBER);
		}
		if (visits(patches, PatchType.CELASTRUS))
		{
			tool(loadout, setup, Tool.AXE);
		}

		int composted = 0;
		int fees = 0;
		for (PatchLocation patch : planted)
		{
			PatchType type = patch.getType();
			Crop crop = setup.crop(type);
			add(loadout, crop.getItemId(), crop.getItemName(), planted(type), !type.isTree(), false, NONE);
			if (setup.composts(type))
			{
				composted++;
			}
			fees += type.getRemovalFee();
		}
		if (composted > 0)
		{
			Compost compost = setup.compost();
			add(loadout, compost.getItemId(), compost.getDisplayName(), compost.isReusable() ? 1 : composted,
				false, false, NONE);
		}
		for (PatchLocation patch : planted)
		{
			PatchType type = patch.getType();
			if (setup.protects(type))
			{
				Payment payment = setup.crop(type).getPayment();
				add(loadout, payment.getNotedItemId(), payment.getItemName(), payment.getQuantity(), true, true,
					Collections.singleton(payment.getItemId()));
			}
		}
		if (fees > 0)
		{
			add(loadout, ItemID.COINS, "Coins", fees, true, false, NONE);
		}
		Set<String> worn = new HashSet<>();
		Set<Integer> pouched = new HashSet<>();
		for (Teleport teleport : teleports)
		{
			teleport(loadout, setup, teleport, worn, pouched);
		}
		teleport(loadout, setup, toBank, worn, pouched);

		double xpBonus = 0;
		boolean capeWorn = false;
		for (Gear gear : Gear.values())
		{
			if (!setup.uses(gear) || !helps(gear, patches, setup))
			{
				continue;
			}
			int wornPieces = 0;
			for (Gear.Piece piece : gear.getPieces())
			{
				if (!setup.facts().owns(piece.getItemId()))
				{
					continue;
				}
				LoadoutItem had = already(loadout, piece);
				boolean wears;
				if (had != null)
				{
					wears = had.getPlace() == LoadoutItem.Place.WORN;
				}
				else
				{
					wears = piece.getSlot() != null && worn.add(piece.getSlot());
					if (!wears && gear.isWornOnly())
					{
						continue;
					}
					add(loadout, piece.getItemId(), piece.getName(), 1, false, false, piece.getAlsoCounts(), NONE,
						wears ? LoadoutItem.Place.WORN : LoadoutItem.Place.INVENTORY);
				}
				if (wears)
				{
					wornPieces++;
					xpBonus += piece.getXpBonus();
					capeWorn |= gear == Gear.FARMING_CAPE;
				}
			}
			if (gear == Gear.FARMERS_OUTFIT && wornPieces == gear.getPieces().size())
			{
				xpBonus += Gear.FARMERS_SET_BONUS;
			}
		}

		return new Leg(stopIndex, bank, Collections.unmodifiableList(new ArrayList<>(patches)),
			Collections.unmodifiableList(new ArrayList<>(loadout.values())), Collections.unmodifiableSet(missing),
			xpBonus, capeWorn);
	}

	public static double expectedHarvest(PatchType type, CropSetup setup, boolean capeWorn)
	{
		boolean secateurs = setup.uses(Gear.MAGIC_SECATEURS);
		switch (type)
		{
			case HERB:
			case ALLOTMENT:
			case CELASTRUS:
				int lives = BASE_LIVES + (setup.composts(type) ? setup.compost().getExtraLives() : 0);
				double boost = (secateurs ? SECATEURS_BOOST : 0)
					+ (type == PatchType.HERB && capeWorn ? FARMING_CAPE_BOOST : 0);
				int base = type == PatchType.ALLOTMENT ? ALLOTMENT_SAVE_CHANCE_AT_99 : SAVE_CHANCE_AT_99;
				double save = ((int) Math.floor(base * (1 + boost)) + 1) / 256.0;
				return lives / (1 - save);
			case FLOWER:
				return isCrop(setup, type, "limpwurt") ? LIMPWURT_ROOTS_AVERAGE
					: isCrop(setup, type, "woad") ? WOAD_LEAVES : 1;
			case FRUIT_TREE:
			case CALQUAT:
				return FRUIT_PER_TREE;
			default:
				return 0;
		}
	}

	private static boolean isCrop(CropSetup setup, PatchType type, String key)
	{
		Crop crop = setup.crop(type);
		return crop != null && crop.getKey().equals(key);
	}

	private static boolean helps(Gear gear, List<PatchLocation> patches, CropSetup setup)
	{
		if (patches.isEmpty())
		{
			return false;
		}
		switch (gear)
		{
			case FARMING_CAPE:
			case HERB_SACK:
				return visits(patches, PatchType.HERB);
			case MAGIC_SECATEURS:
				return visits(patches, PatchType.HERB) || visits(patches, PatchType.ALLOTMENT)
					|| visits(patches, PatchType.CELASTRUS) && setup.harvests(PatchType.CELASTRUS)
					|| visits(patches, PatchType.FLOWER) && isCrop(setup, PatchType.FLOWER, "limpwurt");
			default:
				return true;
		}
	}

	@Nullable
	private static LoadoutItem already(Map<Integer, LoadoutItem> loadout, Gear.Piece piece)
	{
		LoadoutItem item = loadout.get(piece.getItemId());
		for (int other : piece.getAlsoCounts())
		{
			if (item == null)
			{
				item = loadout.get(other);
			}
		}
		return item;
	}

	private static boolean visits(List<PatchLocation> patches, PatchType type)
	{
		for (PatchLocation patch : patches)
		{
			if (patch.getType() == type)
			{
				return true;
			}
		}
		return false;
	}

	private static boolean sows(List<PatchLocation> patches)
	{
		for (PatchLocation patch : patches)
		{
			if (!patch.getType().isTree())
			{
				return true;
			}
		}
		return false;
	}

	static int planted(PatchType type)
	{
		return type.isTree() ? 1 : type.getSeeds();
	}

	private static void tool(Map<Integer, LoadoutItem> loadout, CropSetup setup, Tool tool)
	{
		if (!setup.brings(tool))
		{
			return;
		}
		if (tool == Tool.RUNE_POUCH && setup.facts().owns(ItemID.DIVINE_RUNE_POUCH))
		{
			Set<Integer> others = new HashSet<>(tool.getAlternatives());
			others.remove(ItemID.DIVINE_RUNE_POUCH);
			others.add(tool.getItemId());
			add(loadout, ItemID.DIVINE_RUNE_POUCH, "Divine rune pouch", 1, false, false, others);
			return;
		}
		add(loadout, tool.getItemId(), tool.getDisplayName(), 1, false, false, tool.getAlternatives());
	}

	private static void teleport(Map<Integer, LoadoutItem> loadout, CropSetup setup, @Nullable Teleport teleport,
		Set<String> worn, Set<Integer> pouched)
	{
		if (teleport == null)
		{
			return;
		}
		boolean pouch = teleport.getKind() == Teleport.Kind.SPELL && setup.brings(Tool.RUNE_POUCH);
		if (pouch && !loadout.containsKey(Tool.RUNE_POUCH.getItemId()) && !loadout.containsKey(ItemID.DIVINE_RUNE_POUCH))
		{
			tool(loadout, setup, Tool.RUNE_POUCH);
		}
		for (Teleport.Need need : teleport.getNeeds())
		{
			switch (teleport.getKind())
			{
				case TABLET:
					add(loadout, need, need.getQuantity(), LoadoutItem.Place.INVENTORY);
					break;
				case SPELL:
					boolean fits = pouch && (pouched.contains(need.getItemId())
						|| pouched.size() < setup.facts().pouchRuneKinds());
					if (fits)
					{
						pouched.add(need.getItemId());
					}
					add(loadout, need, need.getQuantity(), fits ? LoadoutItem.Place.RUNE_POUCH : LoadoutItem.Place.INVENTORY);
					break;
				case ITEM:
				case WORN:
					if (!loadout.containsKey(need.getItemId()))
					{
						String slot = teleport.getWornSlot();
						boolean wears = teleport.getKind() == Teleport.Kind.WORN && (slot == null || worn.add(slot));
						add(loadout, need, need.getQuantity(), wears ? LoadoutItem.Place.WORN : LoadoutItem.Place.INVENTORY);
					}
					break;
				default:
					break;
			}
		}
	}

	private static void add(Map<Integer, LoadoutItem> loadout, Teleport.Need need, int quantity, LoadoutItem.Place place)
	{
		add(loadout, need.getItemId(), need.getName(), quantity, true, false, need.getAlsoCounts(), need.getSuppliedBy(),
			place);
	}

	private static void add(Map<Integer, LoadoutItem> loadout, int itemId, String name, int quantity, boolean stacks,
		boolean noted, Set<Integer> alsoCounts)
	{
		add(loadout, itemId, name, quantity, stacks, noted, alsoCounts, NONE, LoadoutItem.Place.INVENTORY);
	}

	private static void add(Map<Integer, LoadoutItem> loadout, int itemId, String name, int quantity, boolean stacks,
		boolean noted, Set<Integer> alsoCounts, Set<Integer> suppliedBy, LoadoutItem.Place place)
	{
		LoadoutItem had = loadout.get(itemId);
		if (had != null)
		{
			quantity += had.getQuantity();
		}
		loadout.put(itemId, new LoadoutItem(itemId, name, quantity, stacks, noted, alsoCounts, suppliedBy, place));
	}
}

package com.patchpilot.plan;

import com.patchpilot.data.Compost;
import com.patchpilot.data.Crop;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import com.patchpilot.data.Teleport;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunStop;
import java.util.function.IntToLongFunction;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

@Value
public class RunEstimate
{
	double xp;
	long cost;
	long harvestValue;
	int patches;
	boolean pricesMissing;

	public long profit()
	{
		return harvestValue - cost;
	}

	public static RunEstimate of(RunProfile run, CropSetup setup, IntToLongFunction price)
	{
		Prices prices = new Prices(price);
		double xp = 0;
		double value = 0;
		int counted = 0;
		for (Leg leg : LoadoutPlanner.plan(run, setup))
		{
			for (PatchLocation patch : leg.getPatches())
			{
				PatchType type = patch.getType();
				Crop crop = setup.crop(type);
				if (crop == null)
				{
					continue;
				}
				counted++;
				double picked = setup.harvests(type)
					? LoadoutPlanner.expectedHarvest(type, setup, leg.isFarmingCapeWorn()) : 0;
				double harvestXp = type == PatchType.FLOWER ? crop.getHarvestXp() : crop.getHarvestXp() * picked;
				xp += (crop.getPlantXp() + crop.getCheckXp() + harvestXp) * (1 + leg.getXpBonus());

				prices.spend(crop.getItemId(), LoadoutPlanner.planted(type));
				if (setup.protects(type))
				{
					prices.spend(crop.getPayment().getItemId(), crop.getPayment().getQuantity());
				}
				if (setup.composts(type))
				{
					compost(prices, setup.compost());
				}
				prices.spend(ItemID.COINS, type.getRemovalFee());
				if (picked > 0 && crop.getHarvestItemId() > 0)
				{
					value += prices.worth(crop.getHarvestItemId(), picked);
				}
			}
		}
		for (RunStop stop : run.getStops())
		{
			Teleport teleport = stop.teleport();
			if (teleport != null && (teleport.getKind() == Teleport.Kind.TABLET
				|| teleport.getKind() == Teleport.Kind.SPELL))
			{
				for (Teleport.Need need : teleport.getNeeds())
				{
					prices.spend(need.getItemId(), need.getQuantity());
				}
			}
		}
		return new RunEstimate(xp, Math.round(prices.spent), Math.round(value), counted, prices.missing);
	}

	private static void compost(Prices prices, Compost compost)
	{
		if (compost == Compost.BOTTOMLESS)
		{
			prices.spend(ItemID.BUCKET_ULTRACOMPOST, 0.5);
		}
		else if (compost.getItemId() > 0)
		{
			prices.spend(compost.getItemId(), 1);
		}
	}

	private static final class Prices
	{
		private final IntToLongFunction price;
		private double spent;
		private boolean missing;

		Prices(IntToLongFunction price)
		{
			this.price = price;
		}

		void spend(int itemId, double quantity)
		{
			if (quantity > 0)
			{
				spent += worth(itemId, quantity);
			}
		}

		double worth(int itemId, double quantity)
		{
			long each = itemId == ItemID.COINS ? 1 : price.applyAsLong(itemId);
			if (each <= 0)
			{
				missing = true;
			}
			return Math.max(0, each) * quantity;
		}
	}
}

package com.patchpilot.plan;

import com.patchpilot.data.Compost;
import com.patchpilot.data.Crop;
import com.patchpilot.data.CropCatalog;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import com.patchpilot.data.Payment;
import com.patchpilot.data.Tool;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.status.CropState;
import com.patchpilot.status.PatchReading;
import com.patchpilot.status.PatchStatus;
import com.patchpilot.status.Plant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Value;
import net.runelite.api.gameval.ItemID;

public final class StopTasks
{
	@Value
	public static class Line
	{
		Task task;
		String label;
		boolean done;
	}

	private StopTasks()
	{
	}

	public static List<Line> lines(PatchLocation patch, CropSetup setup, @Nullable PatchReading reading, Set<Task> done)
	{
		PatchType type = patch.getType();
		Set<Task> needed = EnumSet.noneOf(Task.class);
		if (!done.contains(Task.PLANT))
		{
			needed.addAll(beforePlanting(type, setup, reading));
		}
		if (setup.composts(type))
		{
			needed.add(Task.COMPOST);
		}
		needed.add(Task.PLANT);
		if (setup.protects(type))
		{
			needed.add(Task.PROTECT);
		}
		for (Task task : done)
		{
			if (applies(task, type, setup))
			{
				needed.add(task);
			}
		}

		List<Line> lines = new ArrayList<>();
		for (Task task : needed)
		{
			lines.add(new Line(task, label(task, patch, setup, reading), done.contains(task)));
		}
		return lines;
	}

	@Nullable
	public static Task gardenerNext(PatchType type, List<Line> lines)
	{
		boolean planted = false;
		for (Line line : lines)
		{
			planted |= line.getTask() == Task.PLANT && line.isDone();
		}
		for (Line line : lines)
		{
			if (line.isDone())
			{
				continue;
			}
			if (line.getTask() == Task.REMOVE)
			{
				return type.getRemovalFee() > 0 ? Task.REMOVE : null;
			}
			if (line.getTask() == Task.PROTECT)
			{
				return planted ? Task.PROTECT : null;
			}
			if (!planted)
			{
				return null;
			}
		}
		return null;
	}

	public static Set<Integer> itemsNext(PatchType type, CropSetup setup, List<Line> lines)
	{
		for (Line line : lines)
		{
			if (!line.isDone())
			{
				return itemsFor(line.getTask(), type, setup);
			}
		}
		return Collections.emptySet();
	}

	private static Set<Integer> itemsFor(Task task, PatchType type, CropSetup setup)
	{
		Set<Integer> items = new HashSet<>();
		Crop crop = setup.crop(type);
		switch (task)
		{
			case CLEAR:
				items.add(Tool.SPADE.getItemId());
				break;
			case REMOVE:
				if (type.getRemovalFee() > 0)
				{
					items.add(ItemID.COINS);
				}
				else
				{
					if (type == PatchType.CELASTRUS)
					{
						items.add(Tool.AXE.getItemId());
						items.addAll(Tool.AXE.getAlternatives());
					}
					items.add(Tool.SPADE.getItemId());
				}
				break;
			case RAKE:
				items.add(Tool.RAKE.getItemId());
				break;
			case COMPOST:
				Compost compost = setup.compost();
				if (compost.getItemId() > 0)
				{
					items.add(compost.getItemId());
				}
				break;
			case PLANT:
				if (crop != null)
				{
					items.add(crop.getItemId());
				}
				break;
			case PROTECT:
				Payment payment = crop == null ? null : crop.getPayment();
				if (payment != null)
				{
					items.add(payment.getItemId());
					items.add(payment.getNotedItemId());
				}
				break;
			default:
				break;
		}
		return items;
	}

	public static boolean isDone(PatchLocation patch, CropSetup setup, Set<Task> done)
	{
		return done.contains(Task.PLANT) && (done.contains(Task.PROTECT) || !setup.protects(patch.getType()));
	}

	public static boolean notReady(@Nullable PatchStatus status, Set<Task> done)
	{
		return status != null && status.getKind() == PatchStatus.Kind.GROWING && !done.contains(Task.PLANT);
	}

	public static Set<Task> doneBetween(PatchType type, CropSetup setup, @Nullable PatchReading before,
		@Nullable PatchReading after)
	{
		Set<Task> done = EnumSet.noneOf(Task.class);
		if (before == null || after == null || before.equals(after))
		{
			return done;
		}
		boolean wasWeeds = before.getPlant() == Plant.WEEDS;
		boolean isWeeds = after.getPlant() == Plant.WEEDS;
		if (isWeeds && !wasWeeds)
		{
			if (before.getState() == CropState.DEAD || before.getState() == CropState.DISEASED)
			{
				done.add(Task.CLEAR);
			}
			else
			{
				done.add(type.isTree() ? Task.REMOVE : Task.HARVEST);
			}
		}
		else if (isWeeds && wasWeeds && after.getStage() == 0 && before.getStage() > 0)
		{
			done.add(Task.RAKE);
		}
		else if (!isWeeds && after.getState() == CropState.GROWING && after.getStage() == 0)
		{
			done.add(Task.PLANT);
			done.addAll(beforePlanting(type, setup, before));
		}
		else if (!isWeeds && before.getPlant() == after.getPlant())
		{
			if (before.getState() == CropState.GROWING && isFullyGrown(before) && after.getState() == CropState.HARVESTABLE)
			{
				done.add(Task.CHECK);
			}
			if (before.getState() == CropState.HARVESTABLE && after.getState() == CropState.HARVESTABLE
				&& before.getStage() > 0 && after.getStage() == 0)
			{
				done.add(Task.HARVEST);
			}
		}
		return done;
	}

	private static Set<Task> beforePlanting(PatchType type, CropSetup setup, @Nullable PatchReading reading)
	{
		Set<Task> tasks = EnumSet.noneOf(Task.class);
		if (reading == null)
		{
			if (type.isTree())
			{
				tasks.add(Task.CHECK);
			}
			if (setup.harvests(type))
			{
				tasks.add(Task.HARVEST);
			}
			if (type.isTree())
			{
				tasks.add(Task.REMOVE);
			}
			return tasks;
		}
		if (reading.getPlant() == Plant.WEEDS)
		{
			if (reading.getStage() > 0)
			{
				tasks.add(Task.RAKE);
			}
			return tasks;
		}
		switch (reading.getState())
		{
			case DEAD:
			case DISEASED:
				tasks.add(Task.CLEAR);
				return tasks;
			case GROWING:
				if (type.isTree() && isFullyGrown(reading))
				{
					tasks.add(Task.CHECK);
				}
				break;
			default:
				break;
		}
		boolean grown = reading.getState() == CropState.HARVESTABLE || isFullyGrown(reading);
		if (setup.harvests(type) && (!type.isTree() || reading.getState() != CropState.HARVESTABLE
			|| reading.getStage() > 0))
		{
			tasks.add(Task.HARVEST);
		}
		if (type.isTree())
		{
			tasks.add(Task.REMOVE);
		}
		if (!grown)
		{
			tasks.remove(Task.CHECK);
		}
		return tasks;
	}

	private static boolean applies(Task task, PatchType type, CropSetup setup)
	{
		switch (task)
		{
			case CHECK:
			case REMOVE:
				return type.isTree();
			case PROTECT:
				return CropCatalog.protectable(type);
			case HARVEST:
				return !type.isTree() || type.getHarvestRule() != PatchType.HarvestRule.NONE;
			default:
				return true;
		}
	}

	private static boolean isFullyGrown(PatchReading reading)
	{
		return reading.getStage() >= reading.getPlant().getStages() - 1;
	}

	private static String label(Task task, PatchLocation patch, CropSetup setup, @Nullable PatchReading reading)
	{
		PatchType type = patch.getType();
		switch (task)
		{
			case CHECK:
				return "Check the tree's health";
			case HARVEST:
				return harvestLabel(type);
			case CLEAR:
				boolean dead = reading != null && reading.getState() == CropState.DEAD;
				return type.isTree()
					? "Dig up the " + (dead ? "dead" : "diseased") + " tree"
					: "Clear the " + (dead ? "dead" : "diseased") + " " + cropNoun(type);
			case REMOVE:
				if (type.getRemovalFee() > 0)
				{
					return "Pay the gardener to remove the tree";
				}
				return type == PatchType.CELASTRUS ? "Chop the tree down and dig it up" : "Dig up the tree";
			case RAKE:
				return "Rake the weeds";
			case COMPOST:
				return "Compost the patch";
			case PLANT:
				Crop crop = setup.crop(type);
				if (crop == null)
				{
					return "Plant it";
				}
				String item = crop.getItemName().toLowerCase(Locale.ROOT);
				return type.getSeeds() > 1 ? "Plant " + type.getSeeds() + " " + item + "s" : "Plant the " + item;
			default:
				return "Pay the gardener to protect it";
		}
	}

	private static String harvestLabel(PatchType type)
	{
		switch (type)
		{
			case HERB:
				return "Pick the herbs";
			case ALLOTMENT:
				return "Harvest the crop";
			case FLOWER:
				return "Pick the flowers";
			case CELASTRUS:
				return "Harvest the bark";
			default:
				return "Pick the fruit";
		}
	}

	private static String cropNoun(PatchType type)
	{
		switch (type)
		{
			case ALLOTMENT:
				return "crop";
			case FLOWER:
				return "flowers";
			default:
				return "herbs";
		}
	}
}

package com.patchpilot.setup;

import lombok.Data;

@Data
public class CropChoice
{
	private String crop;
	private boolean protect = true;
	private boolean harvest = true;
}

package com.patchpilot.setup;

import com.patchpilot.data.Compost;
import com.patchpilot.data.Crop;
import com.patchpilot.data.CropCatalog;
import com.patchpilot.data.Gear;
import com.patchpilot.data.PatchType;
import com.patchpilot.data.Tool;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.annotation.Nullable;

public class CropSetup
{
	private static final Compost DEFAULT_COMPOST = Compost.ULTRACOMPOST;

	private Map<String, CropChoice> choices = new LinkedHashMap<>();
	@Nullable
	private Compost compost = DEFAULT_COMPOST;
	@Nullable
	private transient PlayerFacts facts;

	public CropChoice choice(PatchType type)
	{
		if (choices == null)
		{
			choices = new LinkedHashMap<>();
		}
		return choices.computeIfAbsent(type.name(), k -> new CropChoice());
	}

	@Nullable
	public Crop crop(PatchType type)
	{
		return CropCatalog.find(type, choice(type).getCrop());
	}

	public boolean protects(PatchType type)
	{
		Crop crop = crop(type);
		return crop != null && crop.getPayment() != null && choice(type).isProtect();
	}

	public boolean harvests(PatchType type)
	{
		switch (type.getHarvestRule())
		{
			case ALWAYS:
				return true;
			case OPTIONAL:
				return choice(type).isHarvest();
			default:
				return false;
		}
	}

	public Compost compost()
	{
		return compost != null ? compost : DEFAULT_COMPOST;
	}

	public void setCompost(Compost compost)
	{
		this.compost = compost;
	}

	public boolean composts(PatchType type)
	{
		if (compost() == Compost.NONE)
		{
			return false;
		}
		if (type == PatchType.HERB || type == PatchType.ALLOTMENT || type == PatchType.CELASTRUS && harvests(type))
		{
			return true;
		}
		return !protects(type);
	}

	public boolean brings(Tool tool)
	{
		switch (tool)
		{
			case RUNE_POUCH:
				return facts().ownsRunePouch();
			case SEED_DIBBER:
				return !facts().isPlantsBarehanded();
			default:
				return true;
		}
	}

	public boolean uses(Gear gear)
	{
		return facts().owns(gear);
	}

	public PlayerFacts facts()
	{
		return facts != null ? facts : new PlayerFacts();
	}

	public void setFacts(@Nullable PlayerFacts facts)
	{
		this.facts = facts;
	}
}

package com.patchpilot.setup;

import com.patchpilot.data.Gear;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import lombok.Data;
import net.runelite.api.gameval.ItemID;

@Data
public class PlayerFacts
{
	private static final int POUCH_RUNE_KINDS = 3;
	private static final int DIVINE_POUCH_RUNE_KINDS = 4;

	private Set<Integer> owned = new HashSet<>();
	private Set<Integer> withLeprechaun = new HashSet<>();
	private boolean bankSeen;
	private boolean plantsBarehanded;

	public Set<Integer> getOwned()
	{
		return owned != null ? owned : Collections.emptySet();
	}

	public Set<Integer> getWithLeprechaun()
	{
		return withLeprechaun != null ? withLeprechaun : Collections.emptySet();
	}

	public boolean owns(int itemId)
	{
		return getOwned().contains(itemId);
	}

	public boolean owns(Gear gear)
	{
		for (Gear.Piece piece : gear.getPieces())
		{
			if (owns(piece.getItemId()))
			{
				return true;
			}
		}
		return false;
	}

	public boolean ownsRunePouch()
	{
		return owns(ItemID.BH_RUNE_POUCH) || owns(ItemID.DIVINE_RUNE_POUCH);
	}

	public int pouchRuneKinds()
	{
		return owns(ItemID.DIVINE_RUNE_POUCH) ? DIVINE_POUCH_RUNE_KINDS : POUCH_RUNE_KINDS;
	}
}

package com.patchpilot.setup;

import com.patchpilot.data.PatchCatalog;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import javax.annotation.Nullable;

public class RunProfile
{
	private String id;
	private String name;
	private List<RunStop> stops = new ArrayList<>();

	RunProfile()
	{
	}

	RunProfile(String name)
	{
		this.id = UUID.randomUUID().toString();
		this.name = name;
	}

	public String getId()
	{
		return id;
	}

	public String getName()
	{
		return name;
	}

	public void setName(String name)
	{
		this.name = name;
	}

	public List<RunStop> getStops()
	{
		return Collections.unmodifiableList(stops());
	}

	public void add(RunStop stop)
	{
		stops().add(stop);
	}

	public void remove(int index)
	{
		stops().remove(index);
	}

	public boolean remove(RunStop stop)
	{
		return stops().remove(stop);
	}

	public void setTeleport(int index, @Nullable String choice)
	{
		stops().set(index, stops().get(index).withTeleport(choice));
	}

	public void move(int from, int to)
	{
		RunStop stop = stops().remove(from);
		stops().add(Math.max(0, Math.min(to, stops().size())), stop);
	}

	public boolean contains(RunStop stop)
	{
		return stops().contains(stop);
	}

	public List<PatchLocation> patchesToAdd(PatchType type)
	{
		List<PatchLocation> missing = new ArrayList<>();
		for (PatchLocation patch : PatchCatalog.ofType(type))
		{
			if (!contains(RunStop.patch(patch.getKey())))
			{
				missing.add(patch);
			}
		}
		return missing;
	}

	public int patchCount()
	{
		int count = 0;
		for (RunStop stop : stops())
		{
			if (stop.isPatch())
			{
				count++;
			}
		}
		return count;
	}

	public int bankCount()
	{
		return stops().size() - patchCount();
	}

	RunProfile copy(String newName)
	{
		RunProfile copy = new RunProfile(newName);
		copy.stops.addAll(stops());
		return copy;
	}

	private List<RunStop> stops()
	{
		if (stops == null)
		{
			stops = new ArrayList<>();
		}
		return stops;
	}
}

package com.patchpilot.setup;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
public class RunProgress
{
	public static final int START = -1;

	private String runId;
	private int stop;
	private long startedAt;
	private Map<String, List<String>> done = new LinkedHashMap<>();

	public RunProgress(String runId, int stop)
	{
		this.runId = runId;
		this.stop = stop;
	}

	public RunProgress atStop(int newStop)
	{
		RunProgress copy = new RunProgress(runId, newStop);
		copy.startedAt = startedAt;
		copy.done = new LinkedHashMap<>();
		for (Map.Entry<String, List<String>> entry : done().entrySet())
		{
			copy.done.put(entry.getKey(), new ArrayList<>(entry.getValue()));
		}
		return copy;
	}

	public Map<String, List<String>> done()
	{
		if (done == null)
		{
			done = new LinkedHashMap<>();
		}
		return done;
	}
}

package com.patchpilot.setup;

import com.patchpilot.data.Bank;
import com.patchpilot.data.BankCatalog;
import com.patchpilot.data.PatchCatalog;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.Teleport;
import com.patchpilot.data.TeleportCatalog;
import java.util.Objects;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

public class RunStop
{
	public enum Kind
	{
		PATCH,
		BANK
	}

	private Kind kind;
	private String key;
	@Nullable
	private String teleport;

	RunStop()
	{
	}

	private RunStop(Kind kind, String key)
	{
		this.kind = kind;
		this.key = key;
	}

	public static RunStop patch(String patchKey)
	{
		return new RunStop(Kind.PATCH, patchKey);
	}

	public static RunStop bank(String bankKey)
	{
		return new RunStop(Kind.BANK, bankKey);
	}

	public Kind getKind()
	{
		return kind;
	}

	public String getKey()
	{
		return key;
	}

	@Nullable
	public String getTeleportChoice()
	{
		return teleport;
	}

	public RunStop withTeleport(@Nullable String choice)
	{
		RunStop copy = new RunStop(kind, key);
		copy.teleport = choice;
		return copy;
	}

	@Nullable
	public Teleport teleport()
	{
		return teleport == null ? null : TeleportCatalog.find(teleport);
	}

	@Nullable
	public WorldPoint location()
	{
		PatchLocation patch = patch();
		if (patch != null)
		{
			return patch.getLocation();
		}
		Bank bank = bank();
		return bank == null ? null : bank.getLocation();
	}

	public boolean isPatch()
	{
		return kind == Kind.PATCH;
	}

	public boolean isBank()
	{
		return kind == Kind.BANK;
	}

	@Nullable
	public PatchLocation patch()
	{
		return isPatch() ? PatchCatalog.find(key) : null;
	}

	@Nullable
	public Bank bank()
	{
		return isBank() ? BankCatalog.find(key) : null;
	}

	public boolean isKnown()
	{
		return patch() != null || bank() != null;
	}

	@Override
	public boolean equals(Object other)
	{
		if (!(other instanceof RunStop))
		{
			return false;
		}
		RunStop stop = (RunStop) other;
		return kind == stop.kind && Objects.equals(key, stop.key);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(kind, key);
	}

	@Override
	public String toString()
	{
		return kind + ":" + key;
	}
}

package com.patchpilot.setup;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;

public class SavedRuns
{
	private int version = 1;
	private List<RunProfile> runs = new ArrayList<>();

	public int getVersion()
	{
		return version;
	}

	public List<RunProfile> getRuns()
	{
		return Collections.unmodifiableList(runs());
	}

	@Nullable
	public RunProfile find(String id)
	{
		for (RunProfile run : runs())
		{
			if (run.getId().equals(id))
			{
				return run;
			}
		}
		return null;
	}

	public RunProfile create(String name)
	{
		RunProfile run = new RunProfile(uniqueName(name, null));
		runs().add(run);
		return run;
	}

	public RunProfile duplicate(RunProfile original)
	{
		RunProfile copy = original.copy(uniqueName(original.getName() + " copy", null));
		int at = runs().indexOf(original);
		runs().add(at < 0 ? runs().size() : at + 1, copy);
		return copy;
	}

	public void delete(String id)
	{
		runs().removeIf(run -> run.getId().equals(id));
	}

	public void rename(RunProfile run, String name)
	{
		String trimmed = name == null ? "" : name.trim();
		if (trimmed.isEmpty() || trimmed.equals(run.getName()))
		{
			return;
		}
		run.setName(uniqueName(trimmed, run));
	}

	String uniqueName(String name, @Nullable RunProfile ignore)
	{
		if (!taken(name, ignore))
		{
			return name;
		}
		for (int n = 2; ; n++)
		{
			String numbered = name + " " + n;
			if (!taken(numbered, ignore))
			{
				return numbered;
			}
		}
	}

	private boolean taken(String name, @Nullable RunProfile ignore)
	{
		for (RunProfile run : runs())
		{
			if (run != ignore && run.getName().equalsIgnoreCase(name))
			{
				return true;
			}
		}
		return false;
	}

	private List<RunProfile> runs()
	{
		if (runs == null)
		{
			runs = new ArrayList<>();
		}
		return runs;
	}
}

package com.patchpilot.setup;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.patchpilot.PatchPilotConfig;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
public class SetupStore
{
	static final String CROP_SETUP_KEY = "cropSetup";
	static final String RUNS_KEY = "runs";
	static final String PROGRESS_KEY = "progress";
	public static final String FACTS_KEY = "facts";
	static final String CLOSED_STATUS_KEY = "statusClosed";
	static final String UNREADABLE_SUFFIX = "Unreadable";

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	SetupStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public CropSetup loadCropSetup()
	{
		CropSetup setup = load(CROP_SETUP_KEY, CropSetup.class, CropSetup::new);
		setup.setFacts(loadFacts());
		return setup;
	}

	public void saveCropSetup(CropSetup setup)
	{
		save(CROP_SETUP_KEY, setup);
	}

	public SavedRuns loadRuns()
	{
		return load(RUNS_KEY, SavedRuns.class, SavedRuns::new);
	}

	public void saveRuns(SavedRuns runs)
	{
		save(RUNS_KEY, runs);
	}

	public boolean hasCharacter()
	{
		return configManager.getRSProfileKey() != null;
	}

	@Nullable
	public RunProgress loadProgress()
	{
		if (!hasCharacter())
		{
			return null;
		}
		String json = configManager.getRSProfileConfiguration(PatchPilotConfig.GROUP, PROGRESS_KEY);
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			RunProgress progress = gson.fromJson(json, RunProgress.class);
			return progress != null && progress.getRunId() != null ? progress : null;
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read the saved run progress; starting without it", e);
			return null;
		}
	}

	public Set<String> loadClosedStatus()
	{
		String saved = configManager.getConfiguration(PatchPilotConfig.GROUP, CLOSED_STATUS_KEY);
		Set<String> closed = new HashSet<>();
		if (saved != null && !saved.isEmpty())
		{
			closed.addAll(Arrays.asList(saved.split(",")));
		}
		return closed;
	}

	public void saveClosedStatus(Set<String> closed)
	{
		configManager.setConfiguration(PatchPilotConfig.GROUP, CLOSED_STATUS_KEY, String.join(",", closed));
	}

	public PlayerFacts loadFacts()
	{
		String json = hasCharacter() ? configManager.getRSProfileConfiguration(PatchPilotConfig.GROUP, FACTS_KEY) : null;
		if (json == null || json.isEmpty())
		{
			return new PlayerFacts();
		}
		try
		{
			PlayerFacts facts = gson.fromJson(json, PlayerFacts.class);
			return facts != null ? facts : new PlayerFacts();
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read what's known about the character; starting afresh", e);
			return new PlayerFacts();
		}
	}

	public void saveFacts(PlayerFacts facts)
	{
		if (hasCharacter())
		{
			configManager.setRSProfileConfiguration(PatchPilotConfig.GROUP, FACTS_KEY, gson.toJson(facts));
		}
	}

	public void saveProgress(@Nullable RunProgress progress)
	{
		if (!hasCharacter())
		{
			return;
		}
		if (progress == null)
		{
			configManager.unsetRSProfileConfiguration(PatchPilotConfig.GROUP, PROGRESS_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(PatchPilotConfig.GROUP, PROGRESS_KEY, gson.toJson(progress));
		}
	}

	private <T> T load(String key, Class<T> type, Supplier<T> fresh)
	{
		String json = configManager.getConfiguration(PatchPilotConfig.GROUP, key);
		if (json == null || json.isEmpty())
		{
			return fresh.get();
		}
		try
		{
			T value = gson.fromJson(json, type);
			return value != null ? value : fresh.get();
		}
		catch (JsonParseException e)
		{
			configManager.setConfiguration(PatchPilotConfig.GROUP, key + UNREADABLE_SUFFIX, json);
			log.warn("Couldn't read the saved {}; kept it as {}{} and started afresh",
				key, key, UNREADABLE_SUFFIX, e);
			return fresh.get();
		}
	}

	private void save(String key, Object value)
	{
		configManager.setConfiguration(PatchPilotConfig.GROUP, key, gson.toJson(value));
	}
}

