package com.patchpilot.status;

import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import javax.annotation.Nullable;

public final class Growth
{
	public interface Saved
	{
		@Nullable
		String patchState(String key);

		@Nullable
		Integer tickOffsetMinutes();

		@Nullable
		Integer tickOffsetPrecisionMinutes();
	}

	private static final int TRUSTED_PRECISION_MINUTES = 40;

	private Growth()
	{
	}

	public static String key(PatchLocation patch)
	{
		return patch.getTimeTrackingRegion() + "." + patch.getVarbit();
	}

	public static PatchStatus status(PatchLocation patch, Saved saved, long now)
	{
		String stored = saved.patchState(key(patch));
		PatchReading reading = read(patch.getType(), stored);
		long seenAt = seenAt(stored);
		if (reading == null || seenAt <= 0)
		{
			return PatchStatus.unknown();
		}
		return predict(patch.getType(), reading, seenAt, now, saved);
	}

	@Nullable
	public static PatchReading read(PatchType type, @Nullable String stored)
	{
		if (stored == null)
		{
			return null;
		}
		try
		{
			return GrowthTable.read(type, Integer.parseInt(stored.split(":")[0]));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private static long seenAt(@Nullable String stored)
	{
		String[] parts = stored == null ? new String[0] : stored.split(":");
		try
		{
			return parts.length == 2 ? Long.parseLong(parts[1]) : 0;
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	static PatchStatus predict(PatchType type, PatchReading reading, long seenAt, long now, Saved saved)
	{
		Plant plant = reading.getPlant();
		if (plant == Plant.WEEDS)
		{
			return new PatchStatus(PatchStatus.Kind.EMPTY, null, 0, reading);
		}
		switch (reading.getState())
		{
			case DISEASED:
				return new PatchStatus(PatchStatus.Kind.DISEASED, plant, 0, reading);
			case DEAD:
				return new PatchStatus(PatchStatus.Kind.DEAD, plant, 0, reading);
			case HARVESTABLE:
				return new PatchStatus(PatchStatus.Kind.READY, plant, 0, reading);
			default:
				break;
		}
		int tickMinutes = plant.getGrowthMinutes();
		int stagesLeft = plant.getStages() - 1 - reading.getStage();
		long seenTick = tickTime(tickMinutes, 0, seenAt, saved);
		long readyAt = tickTime(tickMinutes, stagesLeft, seenTick, saved);
		if (now < readyAt)
		{
			return new PatchStatus(PatchStatus.Kind.GROWING, plant, readyAt, reading);
		}
		PatchReading grown = !type.isTree()
			? new PatchReading(plant, CropState.HARVESTABLE, plant.getHarvestStages() - 1)
			: new PatchReading(plant, CropState.GROWING, plant.getStages() - 1);
		return new PatchStatus(PatchStatus.Kind.READY, plant, 0, grown);
	}

	static long tickTime(int tickMinutes, int ticks, long time, Saved saved)
	{
		Integer offsetMinutes = saved.tickOffsetMinutes();
		Integer precisionMinutes = saved.tickOffsetPrecisionMinutes();
		long offset = 0;
		if (offsetMinutes != null && precisionMinutes != null
			&& (precisionMinutes >= tickMinutes || precisionMinutes >= TRUSTED_PRECISION_MINUTES))
		{
			offset = (offsetMinutes % tickMinutes) * 60L;
		}
		long shifted = time + offset;
		long tickLength = tickMinutes * 60L;
		long thisTick = shifted - shifted % tickLength;
		return thisTick + ticks * tickLength - offset;
	}
}

