		row(PatchType.CELASTRUS, 29, 255, Plant.WEEDS, CropState.GROWING, 0, 3);
	}

	private GrowthTable()
	{
	}

	@Nullable
	static PatchReading read(PatchType type, int value)
	{
		for (Range range : RANGES.getOrDefault(type, Collections.emptyList()))
		{
			if (value >= range.from && value <= range.to)
			{
				return new PatchReading(range.plant, range.state, range.sign * value + range.base);
			}
		}
		return null;
	}

	private static void row(PatchType type, int from, int to, Plant plant, CropState state, int sign, int base)
	{
		RANGES.computeIfAbsent(type, t -> new ArrayList<>()).add(new Range(from, to, plant, state, sign, base));
	}
}

