package com.patchpilot.status;

import javax.annotation.Nullable;
import lombok.Value;

@Value
public class PatchStatus
{
	public enum Kind
	{
		UNKNOWN,
		EMPTY,
		GROWING,
		READY,
		DISEASED,
		DEAD
	}

	private static final PatchStatus UNKNOWN_STATUS = new PatchStatus(Kind.UNKNOWN, null, 0, null);

	Kind kind;
	@Nullable
	Plant plant;
	long readyAt;
	@Nullable
	PatchReading reading;

	public static PatchStatus of(Kind kind, @Nullable Plant plant, long readyAt)
	{
		return new PatchStatus(kind, plant, readyAt, null);
	}

	public static PatchStatus unknown()
	{
		return UNKNOWN_STATUS;
	}

	public String describe(long now)
	{
		switch (kind)
		{
			case EMPTY:
				return "Empty";
			case GROWING:
				return timeLeft(readyAt - now);
			case READY:
				return "Ready";
			case DISEASED:
				return "Diseased";
			case DEAD:
				return "Dead";
			default:
				return "Not seen yet";
		}
	}

	static String timeLeft(long seconds)
	{
		long minutes = Math.max(1, (seconds + 59) / 60);
		long days = minutes / (24 * 60);
		long hours = minutes / 60 % 24;
		if (days > 0)
		{
			return days + "d " + hours + "h";
		}
		if (hours > 0)
		{
			return hours + "h " + minutes % 60 + "m";
		}
		return minutes + "m";
	}
}

