package com.patchpilot.status;

import com.patchpilot.data.PatchLocation;
import java.time.Instant;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class TimeTrackingStatus implements StatusSource
{
	public static final String GROUP = "timetracking";
	private static final String TICK_OFFSET = "farmTickOffset";
	private static final String TICK_OFFSET_PRECISION = "farmTickOffsetPrecision";
	private static final String PLUGINS_GROUP = "runelite";
	private static final String TIME_TRACKING_PLUGIN = "timetrackingplugin";

	private final ConfigManager configManager;
	private final Growth.Saved saved;

	@Inject
	TimeTrackingStatus(ConfigManager configManager)
	{
		this.configManager = configManager;
		saved = new Growth.Saved()
		{
			@Override
			public String patchState(String key)
			{
				return configManager.getRSProfileConfiguration(GROUP, key);
			}

			@Override
			public Integer tickOffsetMinutes()
			{
				return configManager.getRSProfileConfiguration(GROUP, TICK_OFFSET, int.class);
			}

			@Override
			public Integer tickOffsetPrecisionMinutes()
			{
				return configManager.getRSProfileConfiguration(GROUP, TICK_OFFSET_PRECISION, int.class);
			}
		};
	}

	@Override
	public boolean hasCharacter()
	{
		return configManager.getRSProfileKey() != null;
	}

	@Override
	public PatchStatus status(PatchLocation patch)
	{
		if (!hasCharacter())
		{
			return PatchStatus.unknown();
		}
		return Growth.status(patch, saved, Instant.now().getEpochSecond());
	}

	@Override
	@Nullable
	public String problem()
	{
		if (!hasCharacter())
		{
			return "Log in to see your patches.";
		}
		if ("false".equals(configManager.getConfiguration(PLUGINS_GROUP, TIME_TRACKING_PLUGIN)))
		{
			return "Turn on RuneLite's Time Tracking plugin to keep your patches up to date.";
		}
		return null;
	}
}

