		setOpaque(false);

		add(Kit.viewHeader(() -> tab.showEditor(run.getId()), "Add"));
		add(Box.createVerticalStrut(Kit.GAP_SMALL));

		for (PatchType type : PatchType.values())
		{
			boolean any = !run.patchesToAdd(type).isEmpty();
			ListRow row = Kit.row(tab.patchPicture(type), type.getDisplayName(), "", chevron(any));
			row.pinActions();
