class AddPatches extends JPanel
{
	private static final Icon PLUS = KitIcons.plus(Kit.TEXT_DIM);
	private static final Icon PLUS_HOVER = KitIcons.plus(Kit.ACCENT_HOVER);

	AddPatches(RunsTab tab, RunProfile run, PatchType type)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		String what = type.getDisplayName().toLowerCase(Locale.ROOT);
		add(Kit.viewHeader(() -> tab.showAddMenu(run.getId()), "Add " + what));
		add(Box.createVerticalStrut(Kit.GAP_SMALL));

		List<PatchLocation> left = run.patchesToAdd(type);
		if (left.isEmpty())
		{
			add(Kit.note("All of them are in the run."));
			return;
		}

		if (left.size() > 1)
		{
			JButton all = Kit.withIcon(Kit.secondaryButton("Add all"), KitIcons.plus(Kit.TEXT));
			all.setMaximumSize(new Dimension(Integer.MAX_VALUE, Kit.CONTROL_HEIGHT));
			all.addActionListener(e ->
			{
				for (PatchLocation patch : left)
				{
					run.add(RunStop.patch(patch.getKey()));
				}
				tab.save();
				tab.showEditor(run.getId());
			});
			add(all);
			add(Box.createVerticalStrut(Kit.GAP));
		}

		for (PatchLocation patch : left)
		{
			Runnable addIt = () ->
			{
				run.add(RunStop.patch(patch.getKey()));
				tab.save();
				tab.showEditor(run.getId());
			};
			JButton plus = Kit.addButton();
			plus.addActionListener(e -> addIt.run());
			ListRow row = Kit.row(tab.patchPicture(type), patch.getName(), "", plus);
			row.pinActions();
			row.onClick(addIt);
			row.onHoverChange(hovered -> plus.setIcon(hovered ? PLUS_HOVER : PLUS));
			add(row);
			add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}
	}
}

