class BankPicker extends JPanel
{
	private static final int QUEST_ICON = SpriteID.SideiconsInterface.QUESTS;
	private static final int QUEST_ICON_SIZE = 11;

	private final RunsTab tab;
	private final RunProfile run;
	private final JPanel results = new JPanel();

	BankPicker(RunsTab tab, RunProfile run)
	{
		this.tab = tab;
		this.run = run;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		add(Kit.viewHeader(() -> tab.showAddMenu(run.getId()), "Add bank"));
		add(Box.createVerticalStrut(Kit.GAP_SMALL));

		JTextField search = Kit.textField("Search banks");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				show(search.getText());
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				show(search.getText());
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				show(search.getText());
			}
		});
		add(search);
		add(Box.createVerticalStrut(Kit.GAP));

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setOpaque(false);
		results.setAlignmentX(LEFT_ALIGNMENT);
		add(results);
		show("");
		SwingUtilities.invokeLater(search::requestFocusInWindow);
	}

	private void show(String query)
	{
		String wanted = query.trim().toLowerCase(Locale.ROOT);
		results.removeAll();
		int shown = 0;
		for (Bank bank : BankCatalog.all())
		{
			if (!bank.getName().toLowerCase(Locale.ROOT).contains(wanted))
			{
				continue;
			}
			ListRow row = Kit.row(null, bank.getName(), bank.getQuest() == null ? "" : bank.getQuest());
			if (bank.getQuest() != null)
			{
				row.setDetailIcon(Kit.raised(tab.icons().sprite(QUEST_ICON, QUEST_ICON_SIZE, QUEST_ICON_SIZE), 1));
			}
			row.onClick(() ->
			{
				run.add(RunStop.bank(bank.getKey()));
				tab.save();
				tab.showEditor(run.getId());
			});
			results.add(row);
			results.add(Box.createVerticalStrut(Kit.GAP_SMALL));
			shown++;
		}
		if (shown == 0)
		{
			results.add(Kit.note("No bank matches \"" + query.trim() + "\"."));
		}
		results.revalidate();
		results.repaint();
	}
}

