class CropsTab extends JPanel
{
	private final Supplier<CropSetup> load;
	private final Consumer<CropSetup> save;
	private final IconSource icons;
	private CropSetup setup;

	CropsTab(Supplier<CropSetup> load, Consumer<CropSetup> save, IconSource icons)
	{
		this.load = load;
		this.save = save;
		this.icons = icons;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		reload();
	}

	void reload()
	{
		setup = load.get();
		removeAll();
		for (PatchType type : PatchType.values())
		{
			add(card(type));
			add(Box.createVerticalStrut(Kit.GAP));
		}
		add(compostCard());
		add(Box.createVerticalStrut(Kit.GAP));
		add(gearCard());
		add(Box.createVerticalStrut(Kit.GAP));
		revalidate();
		repaint();
	}

	private JPanel card(PatchType type)
	{
		CropChoice choice = setup.choice(type);
		JPanel card = Kit.card(type.getDisplayName());

		List<Crop> crops = CropCatalog.crops(type);
		JComboBox<Crop> combo = Kit.dropdown(crops.toArray(new Crop[0]),
			new RowRenderer<>(icons, Crop::getProduceItemId, Crop::getName,
				crop -> "Level " + crop.getLevel(), "Choose a crop…"));
		Crop chosen = setup.crop(type);
		if (chosen != null)
		{
			combo.setSelectedItem(chosen);
		}
		else if (crops.size() == 1)
		{
			combo.setSelectedIndex(0);
			choice.setCrop(crops.get(0).getKey());
		}
		else
		{
			combo.setSelectedIndex(-1);
		}
		card.add(combo);

		boolean protectable = CropCatalog.protectable(type);
		boolean optionalHarvest = type.getHarvestRule() == PatchType.HarvestRule.OPTIONAL;
		if (protectable || optionalHarvest)
		{
			card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}

		JCheckBox protect = null;
		if (protectable)
		{
			protect = Kit.checkBox("Pay to protect", choice.isProtect());
			JCheckBox box = protect;
			protect.addActionListener(e ->
			{
				choice.setProtect(box.isSelected());
				save();
			});
			card.add(protect);
		}

		if (optionalHarvest)
		{
			JCheckBox harvest = Kit.checkBox(type.getHarvestLabel(), choice.isHarvest());
			harvest.addActionListener(e ->
			{
				choice.setHarvest(harvest.isSelected());
				save();
			});
			card.add(harvest);
		}

		JCheckBox protectBox = protect;
		combo.addActionListener(e ->
		{
			Crop crop = (Crop) combo.getSelectedItem();
			choice.setCrop(crop != null ? crop.getKey() : null);
			if (protectBox != null)
			{
				protectBox.setEnabled(crop == null || crop.getPayment() != null);
			}
			save();
		});
		return card;
	}

	private JPanel compostCard()
	{
		JPanel card = Kit.card("Compost");
		JComboBox<Compost> combo = Kit.dropdown(Compost.values(),
			new RowRenderer<>(icons, Compost::getItemId, Compost::getDisplayName, compost -> "", "Choose compost…"));
		combo.setSelectedItem(setup.compost());
		combo.addActionListener(e ->
		{
			Compost compost = (Compost) combo.getSelectedItem();
			if (compost != null)
			{
				setup.setCompost(compost);
				save();
			}
		});
		card.add(combo);
		return card;
	}

	private JPanel gearCard()
	{
		PlayerFacts facts = setup.facts();
		JPanel card = Kit.card("Your gear");
		if (!facts.isBankSeen())
		{
			card.add(Kit.note("Open your bank so Patch Pilot can see what you have."));
			card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}
		boolean any = false;
		for (Gear gear : Gear.values())
		{
			int owned = 0;
			int picture = -1;
			for (Gear.Piece piece : gear.getPieces())
			{
				if (facts.owns(piece.getItemId()))
				{
					owned++;
					picture = picture < 0 ? piece.getItemId() : picture;
				}
			}
			if (owned == 0)
			{
				continue;
			}
			any = true;
			card.add(ownedRow(picture, gear.getDisplayName(), gearDetail(gear, owned, facts)));
		}
		if (facts.ownsRunePouch())
		{
			any = true;
			boolean divine = facts.owns(ItemID.DIVINE_RUNE_POUCH);
			card.add(ownedRow(divine ? ItemID.DIVINE_RUNE_POUCH : ItemID.BH_RUNE_POUCH,
				divine ? "Divine rune pouch" : "Rune pouch", ""));
		}
		if (!any && facts.isBankSeen())
		{
			card.add(Kit.note("You do not have any gear that helps with your farm runs."));
		}
		List<String> stored = new ArrayList<>();
		for (Tool tool : new Tool[]{Tool.SPADE, Tool.RAKE, Tool.SEED_DIBBER})
		{
			if (facts.getWithLeprechaun().contains(tool.getItemId()))
			{
				stored.add(tool.getDisplayName().toLowerCase(Locale.ROOT));
			}
		}
		if (!stored.isEmpty())
		{
			card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
			card.add(Kit.note("With the tool leprechaun: " + String.join(", ", stored) + "."));
		}
		return card;
	}

	private static String gearDetail(Gear gear, int owned, PlayerFacts facts)
	{
		int all = gear.getPieces().size();
		switch (gear)
		{
			case FARMERS_OUTFIT:
				return owned == all ? "All " + all + " pieces" : owned + " of " + all + " pieces";
			case GRACEFUL:
				return owned + (owned == 1 ? " piece" : " pieces");
			case MAGIC_SECATEURS:
				return facts.getWithLeprechaun().contains(ItemID.FAIRY_ENCHANTED_SECATEURS)
					? "With the tool leprechaun" : "";
			default:
				return "";
		}
	}

	private JComponent ownedRow(int itemId, String name, String detail)
	{
		ListRow row = Kit.row(icons.get(itemId, RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT), name, detail);
		JPanel spaced = new JPanel(new BorderLayout());
		spaced.setOpaque(false);
		spaced.setAlignmentX(LEFT_ALIGNMENT);
		spaced.setBorder(new EmptyBorder(0, 0, Kit.GAP_SMALL, 0));
		spaced.add(row);
		spaced.setMaximumSize(new Dimension(Integer.MAX_VALUE, spaced.getPreferredSize().height));
		return spaced;
	}

	private void save()
	{
		save.accept(setup);
	}
}

package com.patchpilot.ui;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.IntToLongFunction;
import javax.swing.ImageIcon;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

final class GameIcons implements IconSource
{
	private static final int FULL_WIDTH = 36;
	private static final int FULL_HEIGHT = 32;

	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final ClientThread clientThread;
	private final Component repaintTarget;
	private final Map<String, ImageIcon> cache = new HashMap<>();

	GameIcons(ItemManager itemManager, SpriteManager spriteManager, ClientThread clientThread,
		Component repaintTarget)
	{
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		this.clientThread = clientThread;
		this.repaintTarget = repaintTarget;
	}

	@Override
	public ImageIcon get(int itemId, int width, int height)
	{
		return cache.computeIfAbsent("item:" + itemId + ":" + width + "x" + height, k ->
		{
			ImageIcon icon = blank(width, height);
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(() -> fill(icon, image, width, height,
				width == FULL_WIDTH && height == FULL_HEIGHT));
			return icon;
		});
	}

	@Override
	public <T> void withPrices(Function<IntToLongFunction, T> work, Consumer<T> then)
	{
		clientThread.invoke(() ->
		{
			T result = work.apply(itemManager::getItemPrice);
			SwingUtilities.invokeLater(() -> then.accept(result));
		});
	}

	@Override
	public ImageIcon sprite(int spriteId, int width, int height)
	{
		return cache.computeIfAbsent("sprite:" + spriteId + ":" + width + "x" + height, k ->
		{
			ImageIcon icon = blank(width, height);
			spriteManager.getSpriteAsync(spriteId, 0, image -> fill(icon, image, width, height, false));
			return icon;
		});
	}

	private static ImageIcon blank(int width, int height)
	{
		return new ImageIcon(new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB));
	}

	private void fill(ImageIcon icon, BufferedImage image, int width, int height, boolean asIs)
	{
		if (image == null)
		{
			return;
		}
		BufferedImage picture = asIs
			? image
			: ImageUtil.resizeCanvas(ImageUtil.resizeImage(image, width, height, true), width, height);
		SwingUtilities.invokeLater(() ->
		{
			icon.setImage(picture);
			repaintTarget.repaint();
		});
	}
}

