package com.patchpilot.ui;

import com.patchpilot.data.Tool;
import com.patchpilot.plan.LoadoutCheck;
import com.patchpilot.plan.LoadoutItem;
import com.patchpilot.plan.LoadoutPlanner;
import com.patchpilot.plan.Leg;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.Icon;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.api.gameval.ItemID;

final class InventoryGrid extends JPanel
{
	private static final int COLUMNS = 4;
	private static final int SLOT = 44;
	private static final int GAP = 3;
	private static final int PICTURE_WIDTH = 36;
	private static final int PICTURE_HEIGHT = 32;
	private static final int AMOUNT_INSET = 3;
	private static final Color AMOUNT = new Color(0xFFFF00);
	private static final Color AMOUNT_THOUSANDS = Color.WHITE;
	private static final Color AMOUNT_MILLIONS = new Color(0x00FF80);
	private static final int RUNE_WIDTH = 15;
	private static final int RUNE_HEIGHT = 13;
	private static final int RUNE_GAP = 2;
	private static final int RUNE_INSET = 2;
	private static final float MISSING_OPACITY = 0.3f;

	InventoryGrid(Leg leg, IconSource icons)
	{
		this(leg, icons, null);
	}

	InventoryGrid(Leg leg, IconSource icons, @Nullable Map<Integer, Integer> held)
	{
		super(new FlowLayout(FlowLayout.CENTER, 0, 0));
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
		JPanel grid = new JPanel(new GridLayout(0, COLUMNS, GAP, GAP));
		grid.setOpaque(false);
		add(grid);

		List<Slot> slots = new ArrayList<>();
		for (LoadoutItem item : leg.getLoadout())
		{
			if (item.slots() == 0)
			{
				continue;
			}
			Icon picture = icons.get(pictureId(item), PICTURE_WIDTH, PICTURE_HEIGHT);
			Icon missing = Kit.faded(picture, MISSING_OPACITY);
			int have = held == null ? item.getQuantity() : LoadoutCheck.held(item, held);
			if (isRunePouch(item))
			{
				slots.add(runePouch(leg, icons, held, have >= item.getQuantity() ? picture : missing));
			}
			else if (item.isStacks())
			{
				slots.add(new Slot(have >= item.getQuantity() ? picture : missing,
					item.getQuantity() > 1 ? item.getQuantity() : 0, describe(item)));
			}
			else
			{
				for (int i = 0; i < item.getQuantity(); i++)
				{
					slots.add(new Slot(i < have ? picture : missing, 0, item.getName()));
				}
			}
		}
		while (slots.size() < LoadoutPlanner.INVENTORY_SLOTS)
		{
			slots.add(new Slot(null, 0, null));
		}
		for (int i = 0; i < slots.size(); i++)
		{
			Slot slot = slots.get(i);
			slot.over = i >= LoadoutPlanner.INVENTORY_SLOTS;
			grid.add(slot);
		}
		int rows = (slots.size() + COLUMNS - 1) / COLUMNS;
		Dimension size = new Dimension(COLUMNS * SLOT + (COLUMNS - 1) * GAP, rows * SLOT + (rows - 1) * GAP);
		grid.setPreferredSize(size);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, size.height));
	}

	private static boolean isRunePouch(LoadoutItem item)
	{
		return item.getItemId() == Tool.RUNE_POUCH.getItemId() || Tool.RUNE_POUCH.getAlternatives().contains(item.getItemId());
	}

	private static Slot runePouch(Leg leg, IconSource icons, @Nullable Map<Integer, Integer> held, Icon picture)
	{
		List<Icon> runes = new ArrayList<>();
		List<String> names = new ArrayList<>();
		for (LoadoutItem rune : leg.getLoadout())
		{
			if (rune.getPlace() != LoadoutItem.Place.RUNE_POUCH)
			{
				continue;
			}
			Icon icon = icons.get(rune.getItemId(), RUNE_WIDTH, RUNE_HEIGHT);
			boolean have = held == null || LoadoutCheck.held(rune, held) >= rune.getQuantity();
			runes.add(have ? icon : Kit.faded(icon, MISSING_OPACITY));
			names.add(describe(rune));
		}
		String tooltip = names.isEmpty() ? "Rune pouch" : "Rune pouch: " + String.join(", ", names);
		Slot slot = new Slot(picture, 0, tooltip);
		slot.runes = runes;
		return slot;
	}

	private static int pictureId(LoadoutItem item)
	{
		if (item.getItemId() != ItemID.COINS)
		{
			return item.getItemId();
		}
		int amount = item.getQuantity();
		return amount >= 10_000 ? ItemID.COINS_10000
			: amount >= 1000 ? ItemID.COINS_1000
			: amount >= 250 ? ItemID.COINS_250
			: amount >= 100 ? ItemID.COINS_100
			: amount >= 25 ? ItemID.COINS_25
			: ItemID.COINS_5;
	}

	static String describe(LoadoutItem item)
	{
		String text = item.getName();
		if (item.getQuantity() > 1)
		{
			text = String.format(Locale.ROOT, "%,d", item.getQuantity()) + "x " + text;
		}
		return item.isNoted() ? text + " (noted)" : text;
	}

	private static final class Slot extends JComponent
	{
		@Nullable
		private final Icon picture;
		private final int amount;
		private boolean over;
		private List<Icon> runes = new ArrayList<>();

		Slot(@Nullable Icon picture, int amount, @Nullable String tooltip)
		{
			this.picture = picture;
			this.amount = amount;
			setToolTipText(tooltip);
			setPreferredSize(new Dimension(SLOT, SLOT));
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(Kit.FIELD);
			g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, Kit.CHECK_ARC, Kit.CHECK_ARC);
			g.setColor(over ? Kit.BAD : Kit.OUTLINE);
			g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, Kit.CHECK_ARC, Kit.CHECK_ARC);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

			int x = (getWidth() - PICTURE_WIDTH) / 2;
			int y = (getHeight() - PICTURE_HEIGHT) / 2;
			if (picture != null)
			{
				picture.paintIcon(this, g, x, y);
			}
			int runeLeft = RUNE_INSET;
			int runeRight = runeLeft + RUNE_WIDTH + RUNE_GAP;
			int runeBottom = getHeight() - RUNE_INSET - RUNE_HEIGHT;
			int runeTop = runeBottom - RUNE_GAP - RUNE_HEIGHT;
			int[][] spots = {{runeLeft, runeBottom}, {runeRight, runeBottom}, {runeLeft, runeTop}, {runeRight, runeTop}};
			for (int i = 0; i < runes.size() && i < spots.length; i++)
			{
				runes.get(i).paintIcon(this, g, spots[i][0], spots[i][1]);
			}
			if (amount > 0)
			{
				g.setFont(Kit.SMALL);
				String text = amountText(amount);
				Rectangle2D digits = Kit.SMALL.createGlyphVector(g.getFontRenderContext(), text).getVisualBounds();
				int left = AMOUNT_INSET;
				int baseline = AMOUNT_INSET - (int) Math.floor(digits.getY());
				g.setColor(Color.BLACK);
				g.drawString(text, left + 1, baseline + 1);
				g.setColor(amountColour(amount));
				g.drawString(text, left, baseline);
			}
			g.dispose();
		}

		private static String amountText(int amount)
		{
			if (amount < 100_000)
			{
				return Integer.toString(amount);
			}
			return amount < 10_000_000 ? amount / 1000 + "K" : amount / 1_000_000 + "M";
		}

		private static Color amountColour(int amount)
		{
			return amount < 100_000 ? AMOUNT : amount < 10_000_000 ? AMOUNT_THOUSANDS : AMOUNT_MILLIONS;
		}
	}
}

