	static ListRow row(@Nullable Icon picture, String name, String detail, JComponent... buttons)
	{
		return new ListRow(picture, name, detail, buttons);
	}

	static MouseAdapter click(Runnable action)
	{
		return new MouseAdapter()
		{
			private boolean pressed;

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = SwingUtilities.isLeftMouseButton(e);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean clicked = pressed && SwingUtilities.isLeftMouseButton(e)
					&& e.getComponent().contains(e.getPoint());
				pressed = false;
				if (clicked)
				{
					action.run();
				}
			}
		};
	}

	static JPanel viewHeader(Runnable back, String title, JComponent... buttons)
	{
		Icon arrow = raised(KitIcons.back(TEXT), TEXT_ICON_RAISE);
		Icon arrowHover = raised(KitIcons.back(TEXT_BRIGHT), TEXT_ICON_RAISE);
		JLabel link = new JLabel(title, arrow, JLabel.LEFT);
		link.setFont(HEADING);
		link.setForeground(TEXT);
		link.setIconTextGap(6);
		link.setBorder(new EmptyBorder(0, 5, 0, 0));
		link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		link.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				link.setForeground(TEXT_BRIGHT);
				link.setIcon(arrowHover);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				link.setForeground(TEXT);
				link.setIcon(arrow);
			}
		});
		link.addMouseListener(click(back));
		Dimension size = link.getPreferredSize();
		link.setMinimumSize(new Dimension(0, size.height));
		link.setMaximumSize(size);

		JPanel left = new JPanel();
		left.setLayout(new BoxLayout(left, BoxLayout.X_AXIS));
