	private static JPanel header(JComponent main, JComponent... buttons)
	{
		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(main, BorderLayout.CENTER);

		JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
		right.setOpaque(false);
		for (JComponent button : buttons)
		{
			right.add(button);
		}
		header.add(right, BorderLayout.EAST);
		header.setPreferredSize(new Dimension(header.getPreferredSize().width, CONTROL_HEIGHT));
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, CONTROL_HEIGHT));
		return header;
	}

	static JTextField renameField(String current, String placeholder, Consumer<String> keep, Runnable cancel)
	{
		JTextField field = textField(placeholder);
		field.setText(current);

		boolean[] finished = {false};
		Runnable onKeep = () ->
		{
			if (!finished[0])
			{
				finished[0] = true;
				keep.accept(field.getText());
			}
		};
		Runnable onCancel = () ->
		{
			if (!finished[0])
			{
				finished[0] = true;
				cancel.run();
			}
		};

		field.addActionListener(e -> onKeep.run());
		field.getInputMap().put(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "cancel");
		field.getActionMap().put("cancel", new AbstractAction()
		{
			@Override
			public void actionPerformed(ActionEvent e)
			{
				onCancel.run();
			}
		});
		field.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				SwingUtilities.invokeLater(onKeep);
			}
		});
		SwingUtilities.invokeLater(() ->
		{
			field.requestFocusInWindow();
			field.selectAll();
		});
		return field;
	}

	static <T> JComboBox<T> dropdown(T[] items, RowRenderer<T> renderer)
	{
		JComboBox<T> combo = new JComboBox<>(items);
		combo.setRenderer(renderer);
		combo.setBackground(FIELD);
		style(combo, "arc: " + CONTROL_ARC
			+ "; borderColor: " + hex(OUTLINE)
			+ "; buttonBackground: " + hex(FIELD)
			+ "; buttonSeparatorWidth: 0"
			+ "; buttonArrowColor: " + hex(TEXT_DIM)
			+ "; buttonHoverArrowColor: " + hex(TEXT_BRIGHT)
			+ "; buttonPressedArrowColor: " + hex(TEXT_BRIGHT)
			+ "; popupBackground: " + hex(LIST));
		combo.setFocusable(false);
		combo.setAlignmentX(Component.LEFT_ALIGNMENT);
		combo.setMaximumSize(new Dimension(Integer.MAX_VALUE, combo.getPreferredSize().height));
		return combo;
	}

	static JCheckBox checkBox(String text, boolean selected)
	{
		JCheckBox box = new JCheckBox(text, selected);
		box.setFont(SMALL);
		box.setForeground(TEXT_DIM);
		box.setOpaque(false);
		box.setFocusable(false);
		box.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		box.setAlignmentX(Component.LEFT_ALIGNMENT);
		style(box, "icon.arc: " + CHECK_ARC
			+ "; icon.background: " + hex(FIELD)
			+ "; icon.selectedBackground: " + hex(FIELD)
			+ "; icon.borderColor: " + hex(OUTLINE)
			+ "; icon.selectedBorderColor: " + hex(OUTLINE)
			+ "; icon.hoverBorderColor: " + hex(OUTLINE_HOVER)
			+ "; icon.hoverSelectedBorderColor: " + hex(OUTLINE_HOVER)
			+ "; icon.checkmarkColor: " + hex(TEXT_BRIGHT));
		return box;
	}

	static JButton primaryButton(String text)
	{
		JButton button = button(text);
		style(button, "arc: " + CONTROL_ARC
			+ "; background: " + hex(ACCENT)
			+ "; hoverBackground: " + hex(ACCENT_HOVER)
			+ "; pressedBackground: " + hex(ACCENT_PRESSED)
			+ "; foreground: " + hex(TEXT_BRIGHT)
			+ "; borderColor: " + hex(ACCENT)
			+ "; hoverBorderColor: " + hex(ACCENT_HOVER)
			+ "; focusWidth: 0");
		return button;
	}

	static JButton secondaryButton(String text)
	{
		JButton button = button(text);
		style(button, "arc: " + CONTROL_ARC
			+ "; background: " + hex(FIELD)
			+ "; hoverBackground: " + hex(LIST)
			+ "; pressedBackground: " + hex(CARD)
			+ "; foreground: " + hex(TEXT)
			+ "; borderColor: " + hex(OUTLINE)
			+ "; hoverBorderColor: " + hex(OUTLINE_HOVER)
			+ "; focusWidth: 0");
		return button;
	}

	static JButton iconButton(Function<Color, ? extends Icon> icon, @Nullable String tooltip)
	{
		JButton button = new JButton(icon.apply(TEXT_DIM));
		button.setRolloverEnabled(true);
		button.setRolloverIcon(icon.apply(TEXT_BRIGHT));
		button.setToolTipText(tooltip);
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setFocusable(false);
		button.setPreferredSize(new Dimension(22, 22));
		style(button, "arc: " + CONTROL_ARC
			+ "; buttonType: borderless"
			+ "; hoverBackground: " + hex(LIST)
			+ "; pressedBackground: " + hex(LIST_HOVER)
			+ "; margin: 0,0,0,0");
		return button;
	}

	static <B extends AbstractButton> B withIcon(B button, Icon icon)
	{
		button.setIcon(raised(icon, TEXT_ICON_RAISE));
		return button;
	}

	static Icon faded(Icon icon, float opacity)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				Graphics2D g2 = (Graphics2D) g.create();
				g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
				icon.paintIcon(c, g2, x, y);
				g2.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return icon.getIconWidth();
			}

			@Override
			public int getIconHeight()
			{
				return icon.getIconHeight();
			}
		};
	}

	static Icon raised(Icon icon, int pixels)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
				icon.paintIcon(c, g, x, y);
			}

			@Override
			public int getIconWidth()
			{
				return icon.getIconWidth();
			}

			@Override
			public int getIconHeight()
			{
				return icon.getIconHeight() + 2 * pixels;
			}
		};
	}

	static JButton addButton()
	{
		JButton button = iconButton(KitIcons::plus, null);
		button.setRolloverIcon(KitIcons.plus(ACCENT_HOVER));
		return button;
	}

	static JButton removeButton()
	{
		JButton button = iconButton(KitIcons::cross, null);
		button.setRolloverIcon(KitIcons.cross(BAD));
		return button;
	}

	static JTextField textField(String placeholder)
	{
		JTextField field = new JTextField();
		field.setFont(SMALL);
		field.setForeground(TEXT_BRIGHT);
		field.putClientProperty("JTextField.placeholderText", placeholder);
		style(field, "arc: " + CONTROL_ARC
			+ "; background: " + hex(FIELD)
			+ "; borderColor: " + hex(OUTLINE)
			+ "; focusedBorderColor: " + hex(ACCENT)
			+ "; placeholderForeground: " + hex(TEXT_DIM)
			+ "; focusWidth: 0"
			+ "; margin: 2,6,2,6");
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, CONTROL_HEIGHT));
		field.setPreferredSize(new Dimension(0, CONTROL_HEIGHT));
		return field;
	}

	static String html(String text)
	{
		return "<html><body style='width:" + TEXT_WIDTH + "px'>" + escape(text) + "</body></html>";
	}

	private static JButton button(String text)
	{
		JButton button = new JButton(text);
		button.setFont(BODY);
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setFocusable(false);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		button.setPreferredSize(new Dimension(button.getPreferredSize().width, CONTROL_HEIGHT));
		return button;
	}

	private static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static Font own(Font font)
	{
		return font.deriveFont(font.getStyle(), font.getSize2D());
	}

	private static void style(JComponent component, String style)
	{
		component.putClientProperty("FlatLaf.style", style);
	}

	private static String hex(Color color)
	{
		return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.patchpilot.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;

final class KitIcons
{
	static final int SIZE = 11;
	static final int MID = SIZE / 2;

	private KitIcons()
	{
	}

	static ImageIcon back(Color color)
	{
		return draw(color, g -> g.drawPolyline(new int[]{MID + 2, MID - 2, MID + 2}, new int[]{2, MID, SIZE - 3}, 3));
	}

	static ImageIcon forward(Color color)
	{
		return draw(color, g -> g.drawPolyline(new int[]{MID - 2, MID + 2, MID - 2}, new int[]{2, MID, SIZE - 3}, 3));
	}

	static ImageIcon down(Color color)
	{
		return draw(color, g -> g.drawPolyline(new int[]{2, MID, SIZE - 3}, new int[]{MID - 2, MID + 2, MID - 2}, 3));
	}

	static ImageIcon cross(Color color)
	{
		return draw(color, g ->
		{
			g.drawLine(2, 2, SIZE - 3, SIZE - 3);
			g.drawLine(SIZE - 3, 2, 2, SIZE - 3);
		});
	}

	static ImageIcon plus(Color color)
	{
		return draw(color, g ->
		{
			g.drawLine(MID, 1, MID, SIZE - 2);
			g.drawLine(1, MID, SIZE - 2, MID);
		});
	}

	static ImageIcon grip(Color color)
	{
		return draw(color, g ->
		{
			for (int row = -1; row <= 1; row++)
			{
				for (int col = -1; col <= 1; col += 2)
				{
					g.fill(new Ellipse2D.Float(MID + col * 2 - 1, MID + row * 4 - 1, 2, 2));
				}
			}
		});
	}

	static ImageIcon tick(Color color)
	{
		return draw(color, g -> g.drawPolyline(new int[]{1, 4, SIZE - 2}, new int[]{MID, SIZE - 3, 2}, 3));
	}

	static ImageIcon box(Color color)
	{
		return draw(color, g -> g.drawRoundRect(1, 1, SIZE - 3, SIZE - 3, 3, 3));
	}

	static ImageIcon play(Color color)
	{
		return draw(color, g ->
		{
			Polygon triangle = new Polygon(new int[]{MID - 3, MID + 3, MID - 3}, new int[]{1, MID, SIZE - 2}, 3);
			g.fill(triangle);
			g.draw(triangle);
		});
	}

	static ImageIcon pencil(Color color)
	{
		return draw(color, g ->
		{
			g.drawLine(2, SIZE - 3, SIZE - 5, 4);
			g.drawLine(SIZE - 5, 4, SIZE - 3, 2);
			g.drawLine(SIZE - 3, 2, SIZE - 2, 3);
			g.drawLine(SIZE - 2, 3, SIZE - 4, 5);
			g.drawLine(1, SIZE - 2, 2, SIZE - 3);
		});
	}

	static ImageIcon copy(Color color)
	{
		return draw(color, g ->
		{
			int side = SIZE - 5;
			g.drawRoundRect(1, 3, side, side, 2, 2);
			g.drawPolyline(new int[]{3, 3, 3 + side, 3 + side, 2 + side}, new int[]{2, 1, 1, 1 + side, 1 + side}, 5);
		});
	}

	private interface Painter
	{
		void paint(Graphics2D g);
	}

	private static ImageIcon draw(Color color, Painter painter)
	{
		BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.translate(0.5, 0.5);
		g.setColor(color);
		g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		painter.paint(g);
		g.dispose();
		return new ImageIcon(image);
	}
}

package com.patchpilot.ui;

import com.patchpilot.data.PatchType;
import com.patchpilot.plan.LoadoutItem;
import com.patchpilot.plan.LoadoutPlanner;
import com.patchpilot.plan.Leg;
import com.patchpilot.setup.RunProfile;
import java.util.Locale;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;

class LegLoadout extends JPanel
{
	LegLoadout(RunsTab tab, RunProfile run, Leg leg)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		add(Kit.viewHeader(() -> tab.showEditor(run.getId()), name(leg)));
		add(Box.createVerticalStrut(Kit.GAP_SMALL));

		JPanel card = Kit.card("Inventory", slotCount(leg));
		card.add(new InventoryGrid(leg, tab.icons()));
		add(card);
		addOthers(tab, leg, LoadoutItem.Place.WORN, "Gear");
		addOthers(tab, leg, LoadoutItem.Place.RUNE_POUCH, "Rune pouch");

		if (!leg.fits())
		{
			add(Box.createVerticalStrut(Kit.GAP_SMALL));
			add(Kit.note(over(leg) + ". Add a bank stop to split this leg."));
		}
	}

	private void addOthers(RunsTab tab, Leg leg, LoadoutItem.Place place, String heading)
	{
		JPanel card = null;
		for (LoadoutItem item : leg.getLoadout())
		{
			if (item.getPlace() != place)
			{
				continue;
			}
			if (card == null)
			{
				add(Box.createVerticalStrut(Kit.GAP));
				card = Kit.card(heading);
				add(card);
			}
			else
			{
				card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
			}
			card.add(Kit.row(tab.icons().get(item.getItemId(), RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT),
				InventoryGrid.describe(item), ""));
		}
	}

	static String name(Leg leg)
	{
		if (leg.atStart())
		{
			return "Start";
		}
		return leg.getBank() != null ? leg.getBank().getName() : "Unknown bank";
	}

	static String summary(Leg leg)
	{
		if (!leg.getMissingCrops().isEmpty())
		{
			return "Choose a " + lower(leg.getMissingCrops().iterator().next()) + " crop";
		}
		if (!leg.fits())
		{
			return over(leg);
		}
		int patches = leg.getPatches().size();
		if (patches == 0)
		{
			return "Teleport to the bank";
		}
		return patches + (patches == 1 ? " patch" : " patches");
	}

	static JLabel slotCount(Leg leg)
	{
		JLabel count = new JLabel(leg.slots() + " / " + LoadoutPlanner.INVENTORY_SLOTS);
		count.setFont(Kit.SMALL);
		count.setForeground(leg.fits() ? Kit.TEXT_DIM : Kit.BAD);
		return count;
	}

	private static String over(Leg leg)
	{
		int over = leg.slots() - LoadoutPlanner.INVENTORY_SLOTS;
		return over + (over == 1 ? " slot over" : " slots over");
	}

	private static String lower(PatchType type)
	{
		return type.getDisplayName().toLowerCase(Locale.ROOT);
	}
}

package com.patchpilot.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.MouseInfo;
import java.awt.Point;
import java.awt.PointerInfo;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.AbstractButton;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

final class ListRow extends RoundedPanel
{
	private static final Icon GRIP = KitIcons.grip(Kit.TEXT_DIM);
	private static final Icon GRIP_ACTIVE = KitIcons.grip(Kit.TEXT_BRIGHT);
	private static final Icon NO_GRIP =
		new ImageIcon(new BufferedImage(KitIcons.SIZE, KitIcons.SIZE, BufferedImage.TYPE_INT_ARGB));

	private final JPanel actions;
	private final JPanel lead = new JPanel();
	private final MouseAdapter hover;
	@Nullable
	private JLabel grip;
	private boolean hovered;
	private boolean gripHovered;
	private boolean dragging;
	private boolean pinned;
	private BooleanSupplier hoverBlocked = () -> false;
	private final JLabel nameLabel;
	private final JPanel words;
	@Nullable
	private final JLabel detailLabel;
	private Color detailColor = Kit.TEXT_DIM;
	@Nullable
	private final JLabel pictureLabel;
	@Nullable
	private final Icon picture;
	private Consumer<Boolean> hoverListener = hovered -> { };
	private Cursor enabledCursor = Cursor.getDefaultCursor();

	ListRow(@Nullable Icon picture, String name, String detail, JComponent... buttons)
	{
		super(new BorderLayout(8, 0), Kit.FIELD, Kit.OUTLINE, Kit.CONTROL_ARC);
		setBorder(new EmptyBorder(Kit.ROW_PADDING_Y, Kit.ROW_PADDING_X, Kit.ROW_PADDING_Y, Kit.ROW_PADDING_X - 2));
		setAlignmentX(Component.LEFT_ALIGNMENT);

		words = new JPanel();
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.setOpaque(false);
		nameLabel = label(name, Kit.TEXT_BRIGHT);
		words.add(nameLabel);
		detailLabel = detail.isEmpty() ? null : label(detail, Kit.TEXT_DIM);
		if (detailLabel != null)
		{
			words.add(detailLabel);
		}

		actions = new JPanel(new GridBagLayout());
		actions.setOpaque(false);
		for (JComponent button : buttons)
		{
			actions.add(button);
		}

		lead.setLayout(new BoxLayout(lead, BoxLayout.X_AXIS));
		lead.setOpaque(false);
		this.picture = picture;
		pictureLabel = picture == null ? null : new JLabel(picture);
		if (pictureLabel != null)
		{
			lead.add(pictureLabel);
			add(lead, BorderLayout.WEST);
		}
		words.setMinimumSize(new Dimension(0, words.getPreferredSize().height));
		JPanel middle = new JPanel(new GridBagLayout());
		middle.setOpaque(false);
		GridBagConstraints fill = new GridBagConstraints();
		fill.weightx = 1;
		fill.fill = GridBagConstraints.HORIZONTAL;
		fill.anchor = GridBagConstraints.WEST;
		middle.add(words, fill);
		add(middle, BorderLayout.CENTER);
		add(actions, BorderLayout.EAST);

		int height = Math.max(getPreferredSize().height,
			actions.getPreferredSize().height + 2 * Kit.ROW_PADDING_Y);
		setPreferredSize(new Dimension(0, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setHovered(false);

		hover = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (isEnabled() && !hoverBlocked.getAsBoolean())
				{
					setHovered(true);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), ListRow.this)))
				{
					setHovered(false);
				}
			}
		};
		addMouseListener(hover);
		for (JComponent button : buttons)
		{
			button.addMouseListener(hover);
		}
	}

	void setHovered(boolean hovered)
	{
		this.hovered = hovered;
		refresh();
	}

	JComponent makeDraggable()
	{
		if (grip != null)
		{
			return grip;
		}
		grip = new JLabel(NO_GRIP);
		grip.setBorder(new EmptyBorder(8, 2, 8, 2));
		grip.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));
		grip.addMouseListener(hover);
		grip.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				gripHovered = !hoverBlocked.getAsBoolean();
				refresh();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				gripHovered = false;
				refresh();
			}
		});
		lead.add(grip, 0);
		lead.add(Box.createHorizontalStrut(2), 1);
		if (lead.getParent() == null)
		{
			add(lead, BorderLayout.WEST);
		}
		refresh();
		return grip;
	}

	void pinActions()
	{
		pinned = true;
		refresh();
	}

	void blockHoverWhile(BooleanSupplier blocked)
	{
		hoverBlocked = blocked;
	}

	void setNameFont(Font font)
	{
		nameLabel.setFont(font);
		words.invalidate();
		words.setMinimumSize(new Dimension(0, words.getPreferredSize().height));
		Dimension size = getPreferredSize();
		setPreferredSize(null);
		invalidate();
		int height = Math.max(getPreferredSize().height, size.height);
		setPreferredSize(new Dimension(0, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		revalidate();
	}

	void setDetailColor(Color color)
	{
		detailColor = color;
		if (detailLabel != null && isEnabled())
		{
			detailLabel.setForeground(color);
		}
	}

	void setDetailIcon(Icon icon)
	{
		if (detailLabel != null)
		{
			detailLabel.setIcon(icon);
			detailLabel.setIconTextGap(4);
		}
	}

	void onHoverChange(Consumer<Boolean> listener)
	{
		hoverListener = listener;
		listener.accept(hovered);
	}

	void clearHover()
	{
		hovered = false;
		gripHovered = false;
		refresh();
	}

	void setDragging(boolean dragging)
	{
		this.dragging = dragging;
		refresh();
	}

	private void refresh()
	{
		actions.setVisible(pinned || hovered && !dragging);
		if (grip != null)
		{
			grip.setIcon(gripHovered || dragging ? GRIP_ACTIVE : hovered || pinned ? GRIP : NO_GRIP);
		}
		setBackground(dragging ? Kit.LIST : Kit.FIELD);
		setOutline(dragging ? Kit.ACCENT : hovered ? Kit.OUTLINE_HOVER : Kit.OUTLINE);
		hoverListener.accept(hovered);
		revalidate();
		repaint();
	}

	@Override
	public void setEnabled(boolean enabled)
	{
		super.setEnabled(enabled);
		nameLabel.setForeground(enabled ? Kit.TEXT_BRIGHT : Kit.TEXT_DIM);
		if (detailLabel != null)
		{
			detailLabel.setForeground(enabled ? detailColor : Kit.OUTLINE_HOVER);
		}
		if (pictureLabel != null && picture != null)
		{
			pictureLabel.setIcon(enabled ? picture : Kit.faded(picture, 0.35f));
		}
		setCursor(enabled ? enabledCursor : Cursor.getDefaultCursor());
		if (!enabled)
		{
			hovered = false;
		}
		refresh();
	}

	void onClick(Runnable action)
	{
		enabledCursor = Cursor.getPredefinedCursor(Cursor.HAND_CURSOR);
		setCursor(isEnabled() ? enabledCursor : Cursor.getDefaultCursor());
		MouseAdapter click = Kit.click(() ->
		{
			if (isEnabled())
			{
				action.run();
			}
		});
		addMouseListener(click);
		for (Component part : actions.getComponents())
		{
			if (!(part instanceof AbstractButton))
			{
				part.addMouseListener(click);
			}
		}
	}

	static void hoverUnderMouse(Container list)
	{
		SwingUtilities.invokeLater(() ->
		{
			PointerInfo pointer = MouseInfo.getPointerInfo();
			if (pointer == null || !list.isShowing())
			{
				return;
			}
			for (Component child : list.getComponents())
			{
				if (child instanceof ListRow && child.isShowing())
				{
					Point mouse = new Point(pointer.getLocation());
					SwingUtilities.convertPointFromScreen(mouse, child);
					((ListRow) child).setHovered(child.contains(mouse));
				}
			}
		});
	}

	private static JLabel label(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(Kit.SMALL);
		label.setForeground(color);
		return label;
	}
}

