public class PatchPilotPanel extends PluginPanel
{
	private static final int STATUS_REFRESH_MILLIS = 30_000;

	private final CropsTab cropsTab;
	private final RunsTab runsTab;
	private final StatusTab statusTab;
	private final Timer statusTimer;

	public PatchPilotPanel(SetupStore store, RunGuide guide, StatusSource statuses, ItemManager itemManager,
		SpriteManager spriteManager, ClientThread clientThread)
	{
		setLayout(new BorderLayout());
		setBackground(Kit.PAGE);

		JPanel display = new JPanel(new BorderLayout());
		display.setOpaque(false);

		MaterialTabGroup tabs = tabGroup(display);

		GameIcons icons = new GameIcons(itemManager, spriteManager, clientThread, this);
		cropsTab = new CropsTab(store::loadCropSetup, store::saveCropSetup, icons);
		MaterialTab crops = new MaterialTab("Crops", tabs, cropsTab);
		runsTab = new RunsTab(store::loadRuns, store::saveRuns, store::loadCropSetup, icons, guide, statuses);
		MaterialTab runs = new MaterialTab("Runs", tabs, runsTab);
		runs.setOnSelectEvent(() ->
		{
			runsTab.refreshView();
			return true;
		});
		statusTab = new StatusTab(statuses, store::loadCropSetup, icons, store::loadClosedStatus,
			store::saveClosedStatus);
		MaterialTab patches = new MaterialTab("Status", tabs, statusTab);
		patches.setOnSelectEvent(() ->
		{
			statusTab.refresh();
			return true;
		});
		tabs.addTab(crops);
		tabs.addTab(runs);
		tabs.addTab(patches);
		tabs.select(guide.progress() != null ? runs : crops);

		add(header(tabs), BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);

		statusTimer = new Timer(STATUS_REFRESH_MILLIS, e -> refreshStatus());
		statusTimer.start();
	}

	static MaterialTabGroup tabGroup(JPanel display)
	{
		MaterialTabGroup tabs = new MaterialTabGroup(display);
		tabs.setLayout(new FlowLayout(FlowLayout.LEFT, 0, 0));
		tabs.setBorder(new EmptyBorder(0, 0, 8, 0));
		return tabs;
	}

	static JPanel header(MaterialTabGroup tabs)
	{
		JLabel title = Kit.heading("Patch Pilot");
		title.setForeground(Kit.TEXT_BRIGHT);
		title.setBorder(new EmptyBorder(0, 0, 8, 0));

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.add(title, BorderLayout.NORTH);
		header.add(tabs, BorderLayout.SOUTH);
		return header;
	}

	public void refreshStatus()
	{
		if (!isShowing())
		{
			return;
		}
		if (statusTab.isShowing())
		{
			statusTab.refresh();
		}
		runsTab.refreshStatus();
	}

	public void patchesSeen()
	{
		if (isShowing() && statusTab.isShowing())
		{
			statusTab.refresh();
		}
	}

	public void stop()
	{
		statusTimer.stop();
	}

	public void characterChanged()
	{
		cropsTab.reload();
		runsTab.refreshView();
		statusTab.refresh();
	}

	public void reload()
	{
		cropsTab.reload();
		runsTab.reload();
	}
}

package com.patchpilot.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;

final class ReorderList extends JPanel
{
	interface Mover
	{
		void move(int from, int to);
	}

	private static final int DRAG_THRESHOLD = 3;
	private static final float EASE = 0.35f;
	private static final int FRAME_MS = 16;

	private final Mover mover;
	private final List<ListRow> rows = new ArrayList<>();
	private float[] tops = new float[0];
	private final Timer animator = new Timer(FRAME_MS, e -> step());

	private int dragging = -1;
	private int dragTop;
	private int grabOffset;
	private int target;

	private int settlingIndex = -1;
	private float settlingTop;

	ReorderList(Mover mover)
	{
		this.mover = mover;
		setLayout(new RowLayout());
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
	}

	void setRows(List<ListRow> newRows)
	{
		removeAll();
		rows.clear();
		rows.addAll(newRows);
		for (ListRow row : rows)
		{
			JComponent grip = row.makeDraggable();
			row.blockHoverWhile(() -> dragging >= 0);
			DragHandler handler = new DragHandler(row);
			grip.addMouseListener(handler);
			grip.addMouseMotionListener(handler);
			grip.setAutoscrolls(true);
			add(row);
		}

		dragging = -1;
		int[] slots = slotTops(naturalOrder());
		tops = new float[rows.size()];
		for (int i = 0; i < rows.size(); i++)
		{
			tops[i] = slots[i];
		}
		if (settlingIndex >= 0 && settlingIndex < rows.size())
		{
			tops[settlingIndex] = settlingTop;
			animator.start();
		}
		settlingIndex = -1;
		revalidate();
		repaint();
	}

	static int nearestSlot(int[] otherHeights, int gap, int top)
	{
		int best = 0;
		int bestDistance = Math.abs(top);
		int slotTop = 0;
		for (int i = 0; i < otherHeights.length; i++)
		{
			slotTop += otherHeights[i] + gap;
			int distance = Math.abs(top - slotTop);
			if (distance < bestDistance)
			{
				best = i + 1;
				bestDistance = distance;
			}
		}
		return best;
	}

	void showDrag(int from, int top)
	{
		dragging = from;
		grabOffset = 0;
		dragTo(top);
		rows.get(from).setDragging(true);
		setComponentZOrder(rows.get(from), 0);
		int[] slots = targetTops();
		for (int i = 0; i < rows.size(); i++)
		{
			tops[i] = i == dragging ? dragTop : slots[i];
		}
		doLayout();
	}

	@Override
	public void removeNotify()
	{
		animator.stop();
		super.removeNotify();
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	private int gap()
	{
		return Kit.GAP_SMALL;
	}

	private int height(int row)
	{
		return rows.get(row).getPreferredSize().height;
	}

	private int totalHeight()
	{
		int total = 0;
		for (int i = 0; i < rows.size(); i++)
		{
			total += height(i) + (i > 0 ? gap() : 0);
		}
		return total;
	}

	private List<Integer> naturalOrder()
	{
		List<Integer> order = new ArrayList<>();
		for (int i = 0; i < rows.size(); i++)
		{
			order.add(i);
		}
		return order;
	}

	private int[] slotTops(List<Integer> order)
	{
		int[] slots = new int[rows.size()];
		int y = 0;
		for (int row : order)
		{
			slots[row] = y;
			y += height(row) + gap();
		}
		return slots;
	}

	private int[] targetTops()
	{
		List<Integer> order = naturalOrder();
		if (dragging >= 0)
		{
			order.remove(Integer.valueOf(dragging));
			order.add(target, dragging);
		}
		return slotTops(order);
	}

	private void dragTo(int top)
	{
		dragTop = Math.max(0, Math.min(top, totalHeight() - height(dragging)));
		int[] others = new int[rows.size() - 1];
		for (int i = 0, k = 0; i < rows.size(); i++)
		{
			if (i != dragging)
			{
				others[k++] = height(i);
			}
		}
		target = nearestSlot(others, gap(), dragTop);
	}

	private void step()
	{
		int[] targets = targetTops();
		boolean settled = true;
		for (int i = 0; i < rows.size(); i++)
		{
			if (i == dragging)
			{
				tops[i] = dragTop;
				continue;
			}
			float distance = targets[i] - tops[i];
			if (Math.abs(distance) < 0.5f)
			{
				tops[i] = targets[i];
			}
			else
			{
				tops[i] += distance * EASE;
				settled = false;
			}
		}
		doLayout();
		repaint();
		if (settled && dragging < 0)
		{
			animator.stop();
		}
	}

	private final class RowLayout implements LayoutManager
	{
		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets insets = parent.getInsets();
			return new Dimension(0, insets.top + totalHeight() + insets.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets insets = parent.getInsets();
			int width = parent.getWidth() - insets.left - insets.right;
			for (int i = 0; i < rows.size() && i < tops.length; i++)
			{
				rows.get(i).setBounds(insets.left, insets.top + Math.round(tops[i]), width, height(i));
			}
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}
	}

	private final class DragHandler extends MouseAdapter
	{
		private final ListRow row;
		private Point pressedOnScreen;

		DragHandler(ListRow row)
		{
			this.row = row;
		}

		@Override
		public void mousePressed(MouseEvent e)
		{
			pressedOnScreen = SwingUtilities.isLeftMouseButton(e) ? e.getLocationOnScreen() : null;
		}

		@Override
		public void mouseDragged(MouseEvent e)
		{
			if (pressedOnScreen == null)
			{
				return;
			}
			Point mouse = e.getLocationOnScreen();
			SwingUtilities.convertPointFromScreen(mouse, ReorderList.this);
			if (dragging < 0)
			{
				if (pressedOnScreen.distance(e.getLocationOnScreen()) < DRAG_THRESHOLD)
				{
					return;
				}
				dragging = rows.indexOf(row);
				grabOffset = mouse.y - Math.round(tops[dragging]);
				for (ListRow other : rows)
				{
					other.clearHover();
				}
				row.setDragging(true);
				setComponentZOrder(row, 0);
				animator.start();
			}
			dragTo(mouse.y - grabOffset);
			scrollRectToVisible(new Rectangle(0, dragTop - 8, 1, height(dragging) + 16));
		}

		@Override
		public void mouseReleased(MouseEvent e)
		{
			pressedOnScreen = null;
			if (dragging < 0)
			{
				return;
			}
			int from = dragging;
			int to = target;
			dragging = -1;
			row.setDragging(false);
			if (to == from)
			{
				ListRow.hoverUnderMouse(ReorderList.this);
				return;
			}
			settlingIndex = to;
			settlingTop = dragTop;
			mover.move(from, to);
		}
	}
}

package com.patchpilot.ui;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.RenderingHints;
import javax.annotation.Nullable;
import javax.swing.JPanel;

class RoundedPanel extends JPanel
{
	private final int arc;
	@Nullable
	private Color outline;

	RoundedPanel(LayoutManager layout, Color background, @Nullable Color outline, int arc)
	{
		super(layout);
		this.arc = arc;
		this.outline = outline;
		setBackground(background);
		setOpaque(false);
	}

	void setOutline(@Nullable Color outline)
	{
		this.outline = outline;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(getBackground());
		g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
		if (outline != null)
		{
			g.setColor(outline);
			g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
		}
		g.dispose();
	}
}

package com.patchpilot.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.function.Function;
import java.util.function.ToIntFunction;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.ListCellRenderer;
import javax.swing.border.EmptyBorder;

final class RowRenderer<T> extends JPanel implements ListCellRenderer<T>
{
	static final int ICON_WIDTH = 27;
	static final int ICON_HEIGHT = 24;
	private static final ImageIcon BLANK =
		new ImageIcon(new BufferedImage(ICON_WIDTH, ICON_HEIGHT, BufferedImage.TYPE_INT_ARGB));

	private final IconSource icons;
	private final ToIntFunction<T> iconItemId;
	private final Function<T, String> name;
	private final Function<T, String> detail;
	private final String prompt;

	private final JLabel pictureLabel = new JLabel();
	private final JLabel nameLabel = new JLabel();
	private final JLabel detailLabel = new JLabel();

	RowRenderer(IconSource icons, ToIntFunction<T> iconItemId, Function<T, String> name,
		Function<T, String> detail, String prompt)
	{
		this.icons = icons;
		this.iconItemId = iconItemId;
		this.name = name;
		this.detail = detail;
		this.prompt = prompt;

		setLayout(new BorderLayout(8, 0));
		setBorder(new EmptyBorder(5, 6, 5, 8));
		nameLabel.setFont(Kit.SMALL);
		detailLabel.setFont(Kit.SMALL);
		detailLabel.setForeground(Kit.TEXT_DIM);
		add(pictureLabel, BorderLayout.WEST);
		add(nameLabel, BorderLayout.CENTER);
		add(detailLabel, BorderLayout.EAST);
	}

	@Override
	public Component getListCellRendererComponent(JList<? extends T> list, T value, int index,
		boolean isSelected, boolean cellHasFocus)
	{
		boolean inList = index >= 0;
		setOpaque(inList);
		setBackground(inList && isSelected ? Kit.LIST_HOVER : Kit.LIST);

		if (value != null)
		{
			int itemId = iconItemId.applyAsInt(value);
			pictureLabel.setIcon(itemId > 0 ? icons.get(itemId, ICON_WIDTH, ICON_HEIGHT) : BLANK);
			nameLabel.setText(name.apply(value));
			nameLabel.setForeground(Kit.TEXT_BRIGHT);
			detailLabel.setText(detail.apply(value));
		}
		else
		{
			pictureLabel.setIcon(BLANK);
			nameLabel.setText(prompt);
			nameLabel.setForeground(Kit.TEXT_DIM);
			detailLabel.setText("");
		}
		return this;
	}
}

package com.patchpilot.ui;

import com.patchpilot.plan.LoadoutPlanner;
import com.patchpilot.plan.Leg;
import com.patchpilot.plan.RunEstimate;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunStop;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

class RunEditor extends JPanel
{
	private final RunsTab tab;
	private final RunProfile run;
	private boolean renaming;
	private final JPanel stopArea = new JPanel();
	private final JPanel loadoutArea = new JPanel();
	private final ReorderList stopList;
	private JButton startButton;
	private int estimates;

	RunEditor(RunsTab tab, RunProfile run, boolean renaming)
	{
		this.tab = tab;
		this.run = run;
		this.renaming = renaming;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		stopArea.setLayout(new BoxLayout(stopArea, BoxLayout.Y_AXIS));
		stopArea.setOpaque(false);
		stopArea.setAlignmentX(LEFT_ALIGNMENT);
		loadoutArea.setLayout(new BoxLayout(loadoutArea, BoxLayout.Y_AXIS));
		loadoutArea.setOpaque(false);
		loadoutArea.setAlignmentX(LEFT_ALIGNMENT);
		stopList = new ReorderList((from, to) ->
		{
			run.move(from, to);
			changed(true);
		});
		rebuild();
	}

	private void rebuild()
	{
		removeAll();
		add(header());
		add(Box.createVerticalStrut(Kit.GAP_SMALL));
		add(buttons());
		add(Box.createVerticalStrut(Kit.GAP_SMALL));
		rebuildStops();
		add(stopArea);
		add(loadoutArea);
		revalidate();
		repaint();
	}

	private JComponent header()
	{
		if (renaming)
		{
			JComponent field = Kit.renameField(run.getName(), "Run name", name ->
			{
				tab.runs().rename(run, name);
				tab.save();
				renaming = false;
				rebuild();
			}, () ->
			{
				renaming = false;
				rebuild();
			});
			return Kit.viewHeader(tab::showList, field);
		}
		JButton rename = Kit.iconButton(KitIcons::pencil, "Rename");
		rename.addActionListener(e ->
		{
			renaming = true;
			rebuild();
		});
		return Kit.viewHeader(tab::showList, run.getName(), rename);
	}

	private JComponent buttons()
	{
		boolean doing = tab.guide().isDoing(run.getId());
		startButton = Kit.withIcon(Kit.primaryButton(doing ? "Resume" : "Start"), KitIcons.play(Kit.TEXT_BRIGHT));
		startButton.addActionListener(e -> tab.startRun(run));
		JButton add = Kit.withIcon(Kit.secondaryButton("Add"), KitIcons.plus(Kit.TEXT));
		add.addActionListener(e -> tab.showAddMenu(run.getId()));

		JPanel row = new JPanel(new GridLayout(1, 2, Kit.GAP_SMALL, 0));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.add(startButton);
		row.add(add);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Kit.CONTROL_HEIGHT));
		return row;
	}

	private void rebuildStops()
	{
		stopArea.removeAll();
		List<RunStop> stops = run.getStops();
		startButton.setEnabled(!stops.isEmpty());
		if (!stops.isEmpty())
		{
			List<ListRow> rows = new ArrayList<>();
			for (int i = 0; i < stops.size(); i++)
			{
				ListRow row = stopRow(stops.get(i), i);
				row.pinActions();
				rows.add(row);
			}
			stopList.setRows(rows);
			stopArea.add(stopList);
		}
		stopArea.revalidate();
		stopArea.repaint();
		rebuildLoadout();
	}

	private void rebuildLoadout()
	{
		loadoutArea.removeAll();
		List<Leg> legs = LoadoutPlanner.plan(run, tab.crops());
		boolean first = true;
		for (int i = 0; i < legs.size(); i++)
		{
			Leg leg = legs.get(i);
			if (leg.getPatches().isEmpty() && leg.getLoadout().isEmpty())
			{
				continue;
			}
			if (first)
			{
				loadoutArea.add(Box.createVerticalStrut(Kit.GAP));
				loadoutArea.add(Kit.heading("Loadout"));
				loadoutArea.add(Box.createVerticalStrut(Kit.GAP_SMALL));
				first = false;
			}
			int index = i;
			ListRow row = Kit.row(null, LegLoadout.name(leg), LegLoadout.summary(leg), LegLoadout.slotCount(leg), Kit.chevron());
			row.pinActions();
			row.onClick(() -> tab.showLeg(run.getId(), index));
			loadoutArea.add(row);
			loadoutArea.add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}
		loadoutArea.revalidate();
		loadoutArea.repaint();

		int asked = ++estimates;
		CropSetup crops = tab.crops();
		tab.icons().withPrices(price -> RunEstimate.of(run, crops, price), estimate ->
		{
			if (asked != estimates || estimate.getPatches() == 0)
			{
				return;
			}
			loadoutArea.add(Box.createVerticalStrut(Kit.GAP_SMALL));
			loadoutArea.add(estimateCard(estimate));
			loadoutArea.revalidate();
			loadoutArea.repaint();
		});
	}

	private static JPanel estimateCard(RunEstimate estimate)
	{
		JPanel card = Kit.card();
		card.add(figure("Farming XP", String.format(Locale.ROOT, "%,d", Math.round(estimate.getXp())), Kit.TEXT));
		card.add(figure("Costs", coins(estimate.getCost()), Kit.TEXT));
		card.add(figure("Harvest sells for", coins(estimate.getHarvestValue()), Kit.TEXT));
		long profit = estimate.profit();
		card.add(figure("Profit", (profit < 0 ? "-" : "") + coins(Math.abs(profit)), profit < 0 ? Kit.BAD : Kit.GOOD));
		card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
		card.add(Kit.note("Assumes average harvest yield at 99 Farming."));
		if (estimate.isPricesMissing())
		{
			card.add(Kit.note("Some prices aren't known yet."));
		}
		return card;
	}

	private static JPanel figure(String name, String value, Color colour)
	{
		JPanel row = new JPanel(new BorderLayout(Kit.GAP_SMALL, 0));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.add(Kit.text(name), BorderLayout.WEST);
		JLabel amount = Kit.text(value);
		amount.setForeground(colour);
		row.add(amount, BorderLayout.EAST);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	static String coins(long amount)
	{
		if (amount < 1_000)
		{
			return String.valueOf(amount);
		}
		if (amount < 100_000)
		{
			return String.format(Locale.ROOT, "%.1fk", amount / 1_000.0);
		}
		if (amount < 1_000_000)
		{
			return Math.round(amount / 1_000.0) + "k";
		}
		return String.format(Locale.ROOT, "%.2fM", amount / 1_000_000.0);
	}

	private ListRow stopRow(RunStop stop, int index)
	{
		JButton remove = Kit.removeButton();
		remove.addActionListener(e ->
		{
			run.remove(index);
			changed(true);
		});

		ListRow row = tab.stopRowWithTeleport(stop, remove);
		if (stop.isKnown())
		{
			row.onClick(() -> tab.showTeleportPicker(run.getId(), index));
		}
		return row;
	}

	private void changed(boolean really)
	{
		if (really)
		{
			tab.save();
			rebuildStops();
			ListRow.hoverUnderMouse(stopList);
		}
	}
}

package com.patchpilot.ui;

import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.Teleport;
import com.patchpilot.guide.RunGuide;
import com.patchpilot.plan.LoadoutCheck;
import com.patchpilot.plan.LoadoutItem;
import com.patchpilot.plan.Leg;
import com.patchpilot.plan.StopTasks;
import com.patchpilot.plan.Task;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunProgress;
import com.patchpilot.setup.RunStop;
import com.patchpilot.status.PatchStatus;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.api.gameval.ItemID;

class RunView extends JPanel
{
	private static final Icon TICK = Kit.raised(KitIcons.tick(Kit.GOOD), 1);
	private static final Icon BOX = Kit.raised(KitIcons.box(Kit.TEXT_DIM), 1);

	private final RunsTab tab;
	private final RunGuide guide;
	private final RunProfile run;
	@Nullable
	private JComponent currentCard;

	RunView(RunsTab tab, RunProfile run, RunProgress progress)
	{
		this.tab = tab;
		this.guide = tab.guide();
		this.run = run;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		JButton edit = Kit.iconButton(KitIcons::pencil, "Edit run");
		edit.addActionListener(e -> tab.showEditor(run.getId()));
		add(Kit.viewHeader(tab::showList, run.getName(), edit));
		add(Box.createVerticalStrut(Kit.GAP_SMALL));

		List<RunStop> stops = run.getStops();
		int first = guide.firstStep(run);
		for (int step = first; step < stops.size(); step++)
		{
			if (step == progress.getStop())
			{
				currentCard = currentCard(step, first, stops.size());
				add(currentCard);
			}
			else
			{
				add(stepRow(step));
			}
			add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}

		add(Box.createVerticalStrut(Kit.GAP_SMALL));
		JButton end = Kit.secondaryButton("End run");
		end.setMaximumSize(new Dimension(Integer.MAX_VALUE, Kit.CONTROL_HEIGHT));
		end.addActionListener(e -> guide.end());
		add(end);
	}

	@Nullable
	JComponent currentCard()
	{
		return currentCard;
	}

	private ListRow stepRow(int step)
	{
		boolean done = guide.isStepDone(step);
		ListRow row;
		if (step == RunProgress.START)
		{
			row = Kit.row(startPicture(), "Start", done ? "Done" : "Get your loadout", tickIfDone(done));
		}
		else
		{
			RunStop stop = run.getStops().get(step);
			row = done ? tab.stopRow(stop, tickIfDone(true)) : tab.stopRowWithStatus(stop);
		}
		row.pinActions();
		row.onClick(() -> guide.goTo(step));
		if (done)
		{
			row.setEnabled(false);
		}
		return row;
	}

	private static JComponent tickIfDone(boolean done)
	{
		JLabel tick = new JLabel(done ? KitIcons.tick(Kit.GOOD) : null);
		tick.setBorder(javax.swing.BorderFactory.createEmptyBorder(0, 4, 0, 4));
		return tick;
	}

	private JComponent currentCard(int step, int first, int stopCount)
	{
		RoundedPanel card = (RoundedPanel) Kit.card();
		card.setOutline(Kit.ACCENT);

		PatchLocation patch = step >= 0 ? run.getStops().get(step).patch() : null;
		Leg loadout = patch == null ? guide.loadoutFor(step) : null;
		PatchStatus status = patch == null ? null : tab.statuses().status(patch);

		String name;
		String detail;
		Color detailColour = Kit.TEXT_DIM;
		Icon picture;
		if (step == RunProgress.START)
		{
			name = "Start";
			detail = "Get your loadout";
			picture = startPicture();
		}
		else if (patch != null)
		{
			name = patch.getName();
			String statusText = StatusText.detail(status, StatusText.now());
			detail = statusText != null ? statusText : patch.getType().getDisplayName();
			detailColour = StatusText.colour(status, Kit.TEXT_DIM);
			picture = tab.patchPicture(patch.getType());
		}
		else
		{
			RunStop stop = run.getStops().get(step);
			name = stop.bank() != null ? stop.bank().getName() : "Unknown stop";
			detail = "Bank";
			picture = tab.bankPicture();
		}
		String count = (step + 1) + " of " + stopCount;
		card.add(heading(picture, name, detail, detailColour, step == RunProgress.START ? "" : count));
		card.add(Box.createVerticalStrut(Kit.GAP));

		Teleport teleport = step >= 0 ? run.getStops().get(step).teleport() : null;
		if (teleport != null)
		{
			card.add(Kit.note("Teleport: " + teleport.spokenName()));
			card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}

		if (patch != null)
		{
			addPatchChecklist(card, patch, status);
		}
		else if (loadout != null)
		{
			addLoadoutChecklist(card, step, loadout);
		}

		card.add(Box.createVerticalStrut(Kit.GAP));
		card.add(moveButtons(step, first, stopCount));
		return card;
	}

	private void addPatchChecklist(JPanel card, PatchLocation patch, @Nullable PatchStatus status)
	{
		Set<Task> done = guide.done(patch.getKey());
		if (StopTasks.notReady(status, done))
		{
			JLabel note = Kit.note("Not ready yet");
			note.setForeground(Kit.WARN);
			card.add(note);
			card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}
		for (StopTasks.Line task : StopTasks.lines(patch, tab.crops(), status == null ? null : status.getReading(), done))
		{
			card.add(line(task.isDone() ? TICK : BOX, task.getLabel(), null, task.isDone()));
		}
	}

	private void addLoadoutChecklist(JPanel card, int step, Leg loadout)
	{
		Map<Integer, Integer> held = guide.heldForLoadout();
		card.add(new InventoryGrid(loadout, tab.icons(), held));
		card.add(Box.createVerticalStrut(Kit.GAP));
		List<LoadoutItem> missing = LoadoutCheck.missing(loadout.getLoadout(), held);

		boolean gearHeading = false;
		for (LoadoutItem item : loadout.getLoadout())
		{
			if (item.getPlace() != LoadoutItem.Place.WORN)
			{
				continue;
			}
			if (!gearHeading)
			{
				card.add(small("Wear", Kit.TEXT_DIM));
				gearHeading = true;
			}
			boolean on = LoadoutCheck.held(item, held) >= item.getQuantity();
			card.add(line(on ? TICK : BOX, item.getName(), null, on));
		}

		if (missing.isEmpty())
		{
			if (step >= 0 && guide.isBankOpen())
			{
				if (gearHeading)
				{
					card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
				}
				JLabel note = Kit.note("Close the bank to set off.");
				note.setForeground(Kit.GOOD);
				card.add(note);
			}
			return;
		}
		boolean takeHeading = false;
		for (LoadoutItem item : missing)
		{
			if (item.getPlace() == LoadoutItem.Place.WORN)
			{
				continue;
			}
			if (!takeHeading && gearHeading)
			{
				card.add(Box.createVerticalStrut(Kit.GAP_SMALL));
				card.add(small("Take out", Kit.TEXT_DIM));
			}
			takeHeading = true;
			card.add(line(BOX, InventoryGrid.describe(item), null, false));
		}
	}

	private static JComponent heading(Icon picture, String name, String detail, Color detailColour, String count)
	{
		JPanel top = new JPanel(new BorderLayout(8, 0));
		top.setOpaque(false);
		top.setAlignmentX(LEFT_ALIGNMENT);
		top.add(new JLabel(picture), BorderLayout.WEST);

		JPanel words = new JPanel();
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.setOpaque(false);
		JLabel nameLabel = new JLabel(name);
		nameLabel.setFont(Kit.BODY);
		nameLabel.setForeground(Kit.TEXT_BRIGHT);
		words.add(nameLabel);
		words.add(small(detail, detailColour));
		words.setMinimumSize(new Dimension(0, words.getPreferredSize().height));
		JPanel middle = new JPanel(new GridBagLayout());
		middle.setOpaque(false);
		GridBagConstraints fill = new GridBagConstraints();
		fill.weightx = 1;
		fill.fill = GridBagConstraints.HORIZONTAL;
		middle.add(words, fill);
		top.add(middle, BorderLayout.CENTER);

		JLabel countLabel = small(count, Kit.TEXT_DIM);
		countLabel.setVerticalAlignment(SwingConstants.TOP);
		top.add(countLabel, BorderLayout.EAST);
		top.setMaximumSize(new Dimension(Integer.MAX_VALUE, top.getPreferredSize().height));
		return top;
	}

	private static JComponent line(Icon icon, String text, @Nullable String count, boolean done)
	{
		JPanel line = new JPanel(new BorderLayout(4, 0));
		line.setOpaque(false);
		line.setAlignmentX(LEFT_ALIGNMENT);
		line.setBorder(javax.swing.BorderFactory.createEmptyBorder(2, 0, 2, 0));
		JLabel words = small(text, done ? Kit.TEXT_DIM : Kit.TEXT_BRIGHT);
		words.setIcon(icon);
		words.setIconTextGap(6);
		line.add(words, BorderLayout.CENTER);
		if (count != null)
		{
			line.add(small(count, Kit.TEXT_DIM), BorderLayout.EAST);
		}
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, line.getPreferredSize().height));
		return line;
	}

	private JComponent moveButtons(int step, int first, int stopCount)
	{
		JButton back = Kit.withIcon(Kit.secondaryButton("Back"), KitIcons.back(Kit.TEXT));
		back.setEnabled(step > first);
		back.addActionListener(e -> guide.back());

		boolean last = step + 1 >= stopCount;
		JButton next = Kit.primaryButton(last ? "Finish" : "Next");
		if (!last)
		{
			Kit.withIcon(next, KitIcons.forward(Kit.TEXT_BRIGHT));
			next.setHorizontalTextPosition(SwingConstants.LEADING);
		}
		next.addActionListener(e -> guide.next());

		JPanel row = new JPanel(new GridLayout(1, 2, Kit.GAP_SMALL, 0));
		row.setOpaque(false);
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.add(back);
		row.add(next);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Kit.CONTROL_HEIGHT));
		return row;
	}

	private Icon startPicture()
	{
		return tab.icons().get(ItemID.SPADE, RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT);
	}

	private static JLabel small(String text, Color colour)
	{
		JLabel label = new JLabel(text);
		label.setFont(Kit.SMALL);
		label.setForeground(colour);
		return label;
	}
}

package com.patchpilot.ui;

import com.patchpilot.data.Bank;
import com.patchpilot.data.Crop;
import com.patchpilot.data.CropCatalog;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import com.patchpilot.data.SpellIcons;
import com.patchpilot.data.Teleport;
import com.patchpilot.guide.RunGuide;
import com.patchpilot.plan.LoadoutPlanner;
import com.patchpilot.plan.Leg;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunProgress;
import com.patchpilot.setup.RunStop;
import com.patchpilot.setup.SavedRuns;
import com.patchpilot.status.PatchStatus;
import com.patchpilot.status.StatusSource;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JViewport;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.ItemID;

class RunsTab extends JPanel
{
	private final Supplier<SavedRuns> loadRuns;
	private final Consumer<SavedRuns> saveRuns;
	private final Supplier<CropSetup> loadCrops;
	private final IconSource icons;
	private final RunGuide guide;
	private final StatusSource statuses;
	private SavedRuns runs;
	private Showing showing = Showing.OTHER;
	private int shownStep = Integer.MIN_VALUE;
	@Nullable
	private String shownRunId;
	private static final int PEEK_ABOVE = 30;
	private CropSetup crops;
	@Nullable
	private Supplier<JComponent> current;
	@Nullable
	private String renamingId;

	private enum Showing
	{
		LIST,
		RUN,
		OTHER
	}

	RunsTab(Supplier<SavedRuns> loadRuns, Consumer<SavedRuns> saveRuns, Supplier<CropSetup> loadCrops,
		IconSource icons, RunGuide guide, StatusSource statuses)
	{
		this.loadRuns = loadRuns;
		this.saveRuns = saveRuns;
		this.loadCrops = loadCrops;
		this.icons = icons;
		this.guide = guide;
		this.statuses = statuses;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		guide.onChange(() -> SwingUtilities.invokeLater(this::guideChanged));
		reload();
	}

	void reload()
	{
		runs = loadRuns.get();
		if (guide.progress() != null)
		{
			showRun();
		}
		else
		{
			showList();
		}
	}

	private void guideChanged()
	{
		if (showing == Showing.RUN || showing == Showing.LIST && guide.progress() != null)
		{
			showRun();
		}
		else if (showing == Showing.LIST)
		{
			showList();
		}
	}

	SavedRuns runs()
	{
		return runs;
	}

	void save()
	{
		saveRuns.accept(runs);
		guide.refresh();
	}

	RunGuide guide()
	{
		return guide;
	}

	void refreshView()
	{
		if (showing == Showing.RUN)
		{
			showRun();
		}
		else if (current != null)
		{
			show(showing, current, false);
		}
	}

	void refreshStatus()
	{
		if (showing == Showing.RUN)
		{
			showRun();
		}
	}

	StatusSource statuses()
	{
		return statuses;
	}

	IconSource icons()
	{
		return icons;
	}

	CropSetup crops()
	{
		return crops;
	}

	Icon patchPicture(PatchType type)
	{
		Crop crop = crops.crop(type);
		if (crop == null)
		{
			crop = CropCatalog.crops(type).get(0);
		}
		return icons.get(crop.getProduceItemId(), RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT);
	}

	Icon teleportPicture(Teleport teleport)
	{
		int spell = SpellIcons.of(teleport);
		if (spell >= 0)
		{
			return icons.sprite(spell, RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT);
		}
		int itemId = teleport.isFairyRing() ? ItemID.LEAGUE_TRAILBLAZER_FAIRYS_FLIGHT_TELEPORT
			: teleport.getKind() == Teleport.Kind.NONE ? ItemID.SPIRIT_TREE_DUMMY
			: teleport.pictureItemId();
		return icons.get(itemId, RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT);
	}

	Icon bankPicture()
	{
		return icons.get(ItemID.COINS_10000, RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT);
	}

	void showList()
	{
		renamingId = null;
		show(Showing.LIST, this::listView);
	}

	void showRun()
	{
		RunProgress progress = guide.progress();
		RunProfile run = progress == null ? null : runs.find(progress.getRunId());
		if (run == null || progress.getStop() >= run.getStops().size())
		{
			showList();
			return;
		}
		boolean scroll = showing != Showing.RUN || progress.getStop() != shownStep || !run.getId().equals(shownRunId);
		shownStep = progress.getStop();
		shownRunId = run.getId();
		RunView[] view = new RunView[1];
		show(Showing.RUN, () -> view[0] = new RunView(this, run, progress), false);
		if (scroll)
		{
			SwingUtilities.invokeLater(() -> scrollToCurrent(view[0]));
		}
	}

	private void scrollToCurrent(@Nullable RunView view)
	{
		JComponent card = view == null ? null : view.currentCard();
		JViewport viewport = (JViewport) SwingUtilities.getAncestorOfClass(JViewport.class, this);
		if (card == null || !card.isShowing() || viewport == null)
		{
			return;
		}
		Rectangle area = SwingUtilities.convertRectangle(card.getParent(), card.getBounds(), this);
		area.y = Math.max(0, area.y - PEEK_ABOVE);
		area.height = viewport.getExtentSize().height;
		scrollRectToVisible(area);
	}

	void startRun(RunProfile run)
	{
		if (!guide.isDoing(run.getId()))
		{
			RunProfile other = guide.run();
			if (other != null)
			{
				int answer = JOptionPane.showConfirmDialog(this,
					"End \"" + other.getName() + "\" and start \"" + run.getName() + "\"?",
					"Start run", JOptionPane.OK_CANCEL_OPTION, JOptionPane.QUESTION_MESSAGE);
				if (answer != JOptionPane.OK_OPTION)
				{
					return;
				}
			}
			guide.start(run.getId());
		}
		showRun();
	}

	ListRow stopRow(RunStop stop, JComponent... buttons)
	{
		PatchLocation patch = stop.patch();
		Bank bank = stop.bank();
		if (patch != null)
		{
			return Kit.row(patchPicture(patch.getType()), patch.getName(), patch.getType().getDisplayName(), buttons);
		}
		return otherStopRow(stop, bank, buttons);
	}

	ListRow stopRowWithTeleport(RunStop stop, JComponent... buttons)
	{
		Teleport teleport = stop.teleport();
		PatchLocation patch = stop.patch();
		Bank bank = stop.bank();
		if (patch == null && bank == null)
		{
			return stopRow(stop, buttons);
		}
		String detail = teleport == null ? "Click to set teleport" : teleport.shortName();
		if (patch != null)
		{
			return Kit.row(patchPicture(patch.getType()), patch.getName(), detail, buttons);
		}
		return Kit.row(bankPicture(), bank.getName(), detail, buttons);
	}

	ListRow stopRowWithStatus(RunStop stop)
	{
		PatchLocation patch = stop.patch();
		if (patch == null)
		{
			return stopRow(stop);
		}
		PatchStatus status = statuses.status(patch);
		String detail = StatusText.detail(status, StatusText.now());
		if (detail == null)
		{
			return stopRow(stop);
		}
		ListRow row = Kit.row(patchPicture(patch.getType()), patch.getName(), detail);
		row.setDetailColor(StatusText.colour(status, Kit.TEXT_DIM));
		return row;
	}

	private ListRow otherStopRow(RunStop stop, Bank bank, JComponent... buttons)
	{
		if (bank != null)
		{
			return Kit.row(bankPicture(), bank.getName(), "Bank", buttons);
		}
		return Kit.row(null, "Unknown stop", stop.getKey(), buttons);
	}

	void showEditor(String runId)
	{
		showEditor(runId, false);
	}

	void showEditor(String runId, boolean renaming)
	{
		RunProfile run = runs.find(runId);
		if (run == null)
		{
			showList();
			return;
		}
		show(Showing.OTHER, () -> new RunEditor(this, run, renaming));
	}

	void showAddMenu(String runId)
	{
		RunProfile run = runs.find(runId);
		show(Showing.OTHER, () -> run == null ? listView() : new AddMenu(this, run));
	}

	void showAddPatches(String runId, PatchType type)
	{
		RunProfile run = runs.find(runId);
		show(Showing.OTHER, () -> run == null ? listView() : new AddPatches(this, run, type));
	}

	void showBankPicker(String runId)
	{
		RunProfile run = runs.find(runId);
		show(Showing.OTHER, () -> run == null ? listView() : new BankPicker(this, run));
	}

	void showTeleportPicker(String runId, int stopIndex)
	{
		RunProfile run = runs.find(runId);
		show(Showing.OTHER, () -> run == null ? listView()
			: stopIndex < run.getStops().size() ? new TeleportPicker(this, run, stopIndex)
			: new RunEditor(this, run, false));
	}

	void showLeg(String runId, int legIndex)
	{
		RunProfile run = runs.find(runId);
		show(Showing.OTHER, () ->
		{
			if (run == null)
			{
				return listView();
			}
			List<Leg> legs = LoadoutPlanner.plan(run, crops);
			return legIndex < legs.size() ? new LegLoadout(this, run, legs.get(legIndex)) : new RunEditor(this, run, false);
		});
	}

	void startRename(String runId)
	{
		renamingId = runId;
		show(Showing.LIST, this::listView);
	}

	private void show(Showing kind, Supplier<JComponent> makeView)
	{
		show(kind, makeView, true);
	}

	private void show(Showing kind, Supplier<JComponent> makeView, boolean toTop)
	{
		showing = kind;
		current = makeView;
		crops = loadCrops.get();
		JComponent view = makeView.get();
		removeAll();
		view.setAlignmentX(LEFT_ALIGNMENT);
		add(view);
		revalidate();
		repaint();
		if (toTop)
		{
			SwingUtilities.invokeLater(() -> scrollRectToVisible(new Rectangle(0, 0, 1, 1)));
		}
	}

	private JComponent listView()
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setOpaque(false);

		JButton newRun = Kit.withIcon(Kit.secondaryButton("New run"), KitIcons.plus(Kit.TEXT));
		newRun.setMaximumSize(new Dimension(Integer.MAX_VALUE, Kit.CONTROL_HEIGHT));
		newRun.addActionListener(e ->
		{
			RunProfile run = runs.create("New run");
			save();
			showEditor(run.getId(), true);
		});
		list.add(newRun);
		list.add(Box.createVerticalStrut(Kit.GAP));

		List<RunProfile> all = runs.getRuns();
		if (all.isEmpty())
		{
			list.add(Kit.note("No runs yet."));
		}
		for (RunProfile run : all)
		{
			list.add(run.getId().equals(renamingId) ? renameRow(run) : runRow(run));
			list.add(Box.createVerticalStrut(Kit.GAP_SMALL));
		}
		return list;
	}

	private JComponent runRow(RunProfile run)
	{
		JButton rename = Kit.iconButton(KitIcons::pencil, "Rename");
		rename.addActionListener(e -> startRename(run.getId()));

		JButton duplicate = Kit.iconButton(KitIcons::copy, "Duplicate");
		duplicate.addActionListener(e ->
		{
			runs.duplicate(run);
			save();
			showList();
		});

		JButton delete = Kit.removeButton();
		delete.addActionListener(e -> confirmDelete(run));

		boolean doing = guide.isDoing(run.getId());
		ListRow row = Kit.row(null, run.getName(), doing ? "In progress" : "", rename, duplicate, delete);
		row.setNameFont(Kit.BODY);
		row.onClick(() ->
		{
			if (doing)
			{
				showRun();
			}
			else
			{
				showEditor(run.getId());
			}
		});
		return row;
	}

	private JComponent renameRow(RunProfile run)
	{
		JComponent field = Kit.renameField(run.getName(), "Run name", name ->
		{
			runs.rename(run, name);
			save();
			showList();
		}, this::showList);
		field.setFont(Kit.BODY);
		return field;
	}

	private void confirmDelete(RunProfile run)
	{
		int answer = JOptionPane.showConfirmDialog(this,
			"Delete \"" + run.getName() + "\"? This can't be undone.",
			"Delete run", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
		if (answer == JOptionPane.OK_OPTION)
		{
			runs.delete(run.getId());
			save();
			showList();
		}
	}
}

package com.patchpilot.ui;

import com.patchpilot.data.Crop;
import com.patchpilot.data.CropCatalog;
