import com.patchpilot.data.PatchType;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.status.PatchStatus;
import com.patchpilot.status.StatusSource;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

class StatusTab extends JPanel
{
	private final StatusSource statuses;
	private final Supplier<CropSetup> loadCrops;
	private final IconSource icons;
	private final Supplier<Set<String>> loadClosed;
	private final Consumer<Set<String>> saveClosed;

	StatusTab(StatusSource statuses, Supplier<CropSetup> loadCrops, IconSource icons,
		Supplier<Set<String>> loadClosed, Consumer<Set<String>> saveClosed)
	{
		this.statuses = statuses;
		this.loadCrops = loadCrops;
		this.icons = icons;
		this.loadClosed = loadClosed;
		this.saveClosed = saveClosed;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		refresh();
	}

	void refresh()
	{
		removeAll();
		String problem = statuses.problem();
		if (problem != null)
		{
			add(Kit.note(problem));
			add(Box.createVerticalStrut(Kit.GAP));
		}
		if (statuses.hasCharacter())
		{
			CropSetup crops = loadCrops.get();
			Set<String> closed = loadClosed.get();
			long now = StatusText.now();
			for (PatchType type : PatchType.values())
			{
				boolean open = !closed.contains(type.name());
				int ready = 0;
				JPanel lines = new JPanel();
				lines.setLayout(new BoxLayout(lines, BoxLayout.Y_AXIS));
				lines.setOpaque(false);
				lines.setAlignmentX(LEFT_ALIGNMENT);
				for (PatchLocation patch : PatchCatalog.ofType(type))
				{
					PatchStatus status = statuses.status(patch);
					ready += status.getKind() == PatchStatus.Kind.READY ? 1 : 0;
					lines.add(Box.createVerticalStrut(Kit.GAP_SMALL));
					lines.add(line(patch, status, crops, now));
				}
				JPanel card = Kit.card();
				card.add(cardTop(type, open, ready));
				if (open)
				{
					card.add(lines);
				}
				add(card);
				add(Box.createVerticalStrut(Kit.GAP));
			}
		}
		revalidate();
		repaint();
	}

	private JComponent cardTop(PatchType type, boolean open, int ready)
	{
		JLabel heading = Kit.heading(type.getDisplayName());
		heading.setIcon(open ? KitIcons.down(Kit.TEXT_DIM) : KitIcons.forward(Kit.TEXT_DIM));
		heading.setIconTextGap(Kit.GAP_SMALL + 2);
		JPanel top = new JPanel(new BorderLayout(Kit.GAP_SMALL, 0));
		top.setOpaque(false);
		top.setAlignmentX(LEFT_ALIGNMENT);
		top.add(heading, BorderLayout.WEST);
		if (!open && ready > 0)
		{
			top.add(label(ready + " ready", StatusText.colour(PatchStatus.of(PatchStatus.Kind.READY, null, 0), Kit.TEXT)),
				BorderLayout.EAST);
		}
		top.setMaximumSize(new Dimension(Integer.MAX_VALUE, top.getPreferredSize().height));
		top.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		top.setToolTipText(open ? "Hide these patches" : "Show these patches");
		top.addMouseListener(Kit.click(() ->
		{
			Set<String> closed = new HashSet<>(loadClosed.get());
			if (!closed.remove(type.name()))
			{
				closed.add(type.name());
			}
			saveClosed.accept(closed);
			refresh();
		}));
		return top;
	}

	private JPanel line(PatchLocation patch, PatchStatus status, CropSetup crops, long now)
	{
		Icon picture;
		String plant;
		if (status.getPlant() != null)
		{
			picture = icons.get(StatusText.pictureItemId(patch.getType(), status.getPlant()),
				RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT);
			plant = status.getPlant().getDisplayName();
		}
		else
		{
			Crop crop = crops.crop(patch.getType());
			if (crop == null)
			{
				crop = CropCatalog.crops(patch.getType()).get(0);
			}
			picture = Kit.faded(icons.get(crop.getProduceItemId(), RowRenderer.ICON_WIDTH, RowRenderer.ICON_HEIGHT), 0.35f);
			plant = "";
		}

		JPanel line = new JPanel(new BorderLayout(8, 0));
		line.setOpaque(false);
		line.setAlignmentX(LEFT_ALIGNMENT);
		line.add(new JLabel(picture), BorderLayout.WEST);

		JPanel words = new JPanel();
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.setOpaque(false);
		words.add(label(patch.getName(), Kit.TEXT_BRIGHT));
		if (!plant.isEmpty())
		{
			words.add(label(plant, Kit.TEXT_DIM));
		}
		words.setMinimumSize(new Dimension(0, words.getPreferredSize().height));
		JPanel middle = new JPanel(new GridBagLayout());
		middle.setOpaque(false);
		GridBagConstraints fill = new GridBagConstraints();
		fill.weightx = 1;
		fill.fill = GridBagConstraints.HORIZONTAL;
		middle.add(words, fill);
		line.add(middle, BorderLayout.CENTER);

		line.add(label(status.describe(now), StatusText.colour(status, status.getKind() == PatchStatus.Kind.GROWING
			? Kit.TEXT : Kit.TEXT_DIM)), BorderLayout.EAST);
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, line.getPreferredSize().height));
		return line;
	}

	private static JLabel label(String text, Color colour)
	{
		JLabel label = new JLabel(text);
		label.setFont(Kit.SMALL);
		label.setForeground(colour);
		return label;
	}
}

package com.patchpilot.ui;

import com.patchpilot.data.Crop;
import com.patchpilot.data.CropCatalog;
import com.patchpilot.data.PatchType;
import com.patchpilot.status.PatchStatus;
import com.patchpilot.status.Plant;
import java.awt.Color;
import java.time.Instant;
import java.util.Locale;
import javax.annotation.Nullable;

final class StatusText
{
	private StatusText()
	{
	}

	static long now()
	{
		return Instant.now().getEpochSecond();
	}

	@Nullable
	static String detail(PatchStatus status, long now)
	{
		Plant plant = status.getPlant();
		switch (status.getKind())
		{
			case UNKNOWN:
				return null;
			case GROWING:
				return plant.getDisplayName() + ", ready in " + status.describe(now);
			default:
				String state = status.describe(now);
				return plant == null ? state : plant.getDisplayName() + ", " + state.toLowerCase(Locale.ROOT);
		}
	}

	static Color colour(PatchStatus status, Color usual)
	{
		switch (status.getKind())
		{
			case READY:
				return Kit.GOOD;
			case DISEASED:
				return Kit.WARN;
			case DEAD:
				return Kit.BAD;
			default:
				return usual;
		}
	}

	static int pictureItemId(PatchType type, Plant plant)
	{
		Crop crop = CropCatalog.find(type, plant.getCropKey());
		return crop != null ? crop.getProduceItemId() : plant.getItemId();
	}
}

package com.patchpilot.ui;

import com.patchpilot.data.Teleport;
import com.patchpilot.data.TeleportCatalog;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunStop;
import java.awt.Component;
import java.awt.Graphics;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.api.coords.WorldPoint;

class TeleportPicker extends JPanel
{
	private static final Icon NO_PICTURE = new Icon()
	{
		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
		}

		@Override
		public int getIconWidth()
		{
			return RowRenderer.ICON_WIDTH;
		}

		@Override
		public int getIconHeight()
		{
			return RowRenderer.ICON_HEIGHT;
		}
	};

	private final RunsTab tab;
	private final RunProfile run;
	private final int index;

	TeleportPicker(RunsTab tab, RunProfile run, int index)
	{
		this.tab = tab;
		this.run = run;
		this.index = index;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);

		RunStop stop = run.getStops().get(index);
		String place = stop.patch() != null ? stop.patch().getName()
			: stop.bank() != null ? stop.bank().getName() : "Unknown stop";
		add(Kit.viewHeader(() -> tab.showEditor(run.getId()), place));
		add(Box.createVerticalStrut(Kit.GAP_SMALL));

		WorldPoint location = stop.location();
		if (location == null)
		{
			add(Kit.note("This stop is from a newer version of Patch Pilot."));
			return;
		}
		Teleport current = stop.teleport();
		add(choice(NO_PICTURE, "No teleport", "Walk there", current == null, null));
		for (Teleport teleport : TeleportCatalog.near(location))
		{
			add(Box.createVerticalStrut(Kit.GAP_SMALL));
			add(choice(tab.teleportPicture(teleport), teleport.getName(), detail(teleport, location),
				teleport.equals(current), teleport.getKey()));
		}
	}

	private ListRow choice(Icon picture, String name, String detail, boolean chosen, @Nullable String choice)
	{
		JLabel tick = new JLabel(chosen ? KitIcons.tick(Kit.GOOD) : null);
		tick.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 4));
		ListRow row = Kit.row(picture, name, detail, tick);
		row.pinActions();
		row.onClick(() -> pick(choice));
		return row;
	}

	private void pick(@Nullable String choice)
	{
		run.setTeleport(index, choice);
		tab.save();
		tab.showEditor(run.getId());
	}

	static String detail(Teleport teleport, WorldPoint place)
	{
		int tiles = TeleportCatalog.distance(teleport, place);
		return (tiles == 1 ? "1 tile" : tiles + " tiles") + " away";
	}
}

