	public void everyTeleportHasAUniqueKeyAndWhatItTakes()
	{
		Set<String> keys = new HashSet<>();
		for (Teleport teleport : TeleportCatalog.all())
		{
			assertTrue("duplicate key " + teleport.getKey(), keys.add(teleport.getKey()));
			assertEquals(teleport.getName(), teleport.getKind() == Teleport.Kind.NONE, teleport.getNeeds().isEmpty());
			for (Teleport.Need need : teleport.getNeeds())
			{
				assertTrue(teleport.getName(), need.getItemId() > 0 && need.getQuantity() > 0);
			}
		}
		assertTrue(keys.size() > 200);
	}

	@Test
	public void readsTabletsJewelleryAndSpells()
	{
		Teleport tablet = TeleportCatalog.find("camelot_tablet");
		assertEquals(Teleport.Kind.TABLET, tablet.getKind());
		assertEquals(ItemID.POH_TABLET_CAMELOTTELEPORT, tablet.getNeeds().get(0).getItemId());

		Teleport necklace = TeleportCatalog.find("skills_necklace_farming_guild");
		assertEquals(Teleport.Kind.WORN, necklace.getKind());
		assertEquals("Skills necklace", necklace.getNeeds().get(0).getName());
		assertFalse("other charges count", necklace.getNeeds().get(0).getAlsoCounts().isEmpty());

		Teleport spell = TeleportCatalog.find("camelot_teleport");
		assertEquals(Teleport.Kind.SPELL, spell.getKind());
		Teleport.Need air = spell.getNeeds().get(0);
