		assertEquals(5, air.getQuantity());
		assertTrue(air.getAlsoCounts().contains(ItemID.DUSTRUNE));
		assertTrue(air.getSuppliedBy().contains(ItemID.STAFF_OF_AIR));

		assertNull(TeleportCatalog.find("from_a_newer_version"));
	}

	@Test
	public void everyWornTeleportKnowsWhereItsWorn()
	{
		for (Teleport teleport : TeleportCatalog.all())
		{
			if (teleport.getKind() == Teleport.Kind.WORN)
			{
				assertNotNull(teleport.getName(), teleport.getWornSlot());
			}
			else
			{
				assertNull(teleport.getName(), teleport.getWornSlot());
			}
		}
		assertEquals("neck", TeleportCatalog.find("digsite_pendant_fossil_island").getWornSlot());
		assertEquals("ring", TeleportCatalog.find("ring_of_dueling_castle_wars").getWornSlot());
		assertEquals("cape", TeleportCatalog.find("max_cape_farming_guild").getWornSlot());
		assertEquals("weapon", TeleportCatalog.find("fairy_ring_cir_south_of_mount_karuulm").getWornSlot());

		for (String[] worn : new String[][]{{"Xeric's talisman", "neck"}, {"Book of the dead", "shield"},
			{"Chronicle", "shield"}, {"Drakan's medallion", "neck"}, {"Pharaoh's sceptre", "weapon"},
			{"Rada's blessing", "ammo"}, {"Skull sceptre", "weapon"}, {"Western banner", "weapon"}})
		{
			Teleport teleport = named(worn[0]);
			assertEquals(worn[0], Teleport.Kind.WORN, teleport.getKind());
			assertEquals(worn[0], worn[1], teleport.getWornSlot());
		}
		for (String kept : new String[]{"Ectophial", "Enchanted lyre", "Royal seed pod"})
		{
			assertEquals(kept, Teleport.Kind.ITEM, named(kept).getKind());
		}
	}

	private static Teleport named(String start)
	{
		for (Teleport teleport : TeleportCatalog.all())
		{
			if (teleport.getName().startsWith(start))
			{
				return teleport;
			}
		}
		throw new AssertionError("no teleport named " + start);
	}

	@Test
	public void everySpellHasItsSpellbookIcon()
	{
