package com.patchpilot.guide;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.patchpilot.plan.Task;
import java.util.Collections;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class PendingTasksTest
{
	@Test
	public void neverOnTheTickItsSeen()
	{
		PendingTasks pending = new PendingTasks();
		pending.add("herb_catherby", EnumSet.of(Task.PLANT), 10);

		assertTrue(pending.release(10, false).isEmpty());
		assertEquals(Collections.singletonMap("herb_catherby", EnumSet.of(Task.PLANT)), pending.release(11, false));
		assertTrue("nothing left", pending.release(12, false).isEmpty());
	}

	@Test
	public void heldWhileTheLastHerbsBeingPicked()
	{
		PendingTasks pending = new PendingTasks();
		pending.add("herb_catherby", EnumSet.of(Task.HARVEST), 10);

		assertTrue(pending.release(11, true).isEmpty());
		assertTrue(pending.release(12, true).isEmpty());
		assertEquals("ticked once the animation stops", Collections.singletonMap("herb_catherby",
			EnumSet.of(Task.HARVEST)), pending.release(13, false));
	}

	@Test
	public void neverHeldLongerThanAFewTicks()
	{
		PendingTasks pending = new PendingTasks();
		pending.add("herb_catherby", EnumSet.of(Task.HARVEST), 10);
		for (int tick = 11; tick < 10 + PendingTasks.MAX_TICKS; tick++)
		{
			assertTrue("tick " + tick, pending.release(tick, true).isEmpty());
		}
		assertEquals("straight on to composting: ticked anyway", 1,
			pending.release(10 + PendingTasks.MAX_TICKS, true).size());
	}

	@Test
	public void aChangeThatTicksNothingIsHeldToo()
	{
		PendingTasks pending = new PendingTasks();
		pending.add("herb_catherby", EnumSet.noneOf(Task.class), 10);

		assertTrue(pending.release(11, true).isEmpty());
		assertEquals(Collections.singletonMap("herb_catherby", EnumSet.noneOf(Task.class)), pending.release(12, false));
	}

	@Test
	public void eachChangeWaitsItsOwnTick()
	{
		PendingTasks pending = new PendingTasks();
		pending.add("herb_catherby", EnumSet.of(Task.HARVEST), 10);
		pending.add("flower_catherby", EnumSet.of(Task.HARVEST), 11);

		assertEquals(Collections.singleton("herb_catherby"), pending.release(11, false).keySet());
		assertEquals(Collections.singleton("flower_catherby"), pending.release(12, false).keySet());
	}

	@Test
	public void tasksSeenOnTheSameTickGoTogether()
	{
		PendingTasks pending = new PendingTasks();
		pending.add("herb_catherby", EnumSet.of(Task.HARVEST), 10);
		pending.add("herb_catherby", EnumSet.of(Task.COMPOST), 10);
		pending.add("flower_catherby", EnumSet.of(Task.PLANT), 10);

		Map<String, Set<Task>> released = pending.release(11, false);
		assertEquals(EnumSet.of(Task.HARVEST, Task.COMPOST), released.get("herb_catherby"));
		assertEquals(EnumSet.of(Task.PLANT), released.get("flower_catherby"));
	}
}

package com.patchpilot.guide;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.patchpilot.data.PatchType;
import com.patchpilot.plan.LoadoutItem;
import com.patchpilot.plan.LoadoutPlanner;
import com.patchpilot.plan.Leg;
import com.patchpilot.plan.Task;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunProgress;
import com.patchpilot.setup.RunStop;
import com.patchpilot.setup.SavedRuns;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;

public class RunGuideTest
{
	private SavedRuns runs;
	private RunProfile herbs;
	private CropSetup crops;
	private final List<RunProgress> saved = new ArrayList<>();
	private int changes;
	private RunGuide guide;

	@Before
	public void setUp()
	{
		runs = new SavedRuns();
		herbs = runs.create("Herb run");
		herbs.add(RunStop.patch("herb_catherby"));
		herbs.add(RunStop.bank("seers_village"));
		herbs.add(RunStop.patch("herb_falador"));
		crops = new CropSetup();
		crops.choice(PatchType.HERB).setCrop("ranarr");
		guide = new RunGuide(() -> runs, () -> crops, saved::add);
		guide.onChange(() -> changes++);
	}

	@Test
	public void startsByGettingTheLoadoutWhenTheRunBeginsWithAPatch()
	{
		guide.start(herbs.getId());

		assertTrue(guide.isDoing(herbs.getId()));
		assertEquals(RunProgress.START, guide.progress().getStop());
		assertTrue(guide.progress().getStartedAt() > 0);
		assertNull("nowhere to go yet", guide.target());
		assertEquals(1, saved.size());
	}

	@Test
	public void theLoadoutStepIsDoneOnceEverythingIsHeld()
	{
		guide.start(herbs.getId());
		guide.setHeld(Collections.singletonMap(ItemID.SPADE, 1));
		assertEquals(RunProgress.START, guide.progress().getStop());

		guide.setHeld(loadoutAt(RunProgress.START));
		assertEquals(0, guide.progress().getStop());
		Target target = guide.target();
		assertEquals("Catherby herb", target.getLabel());
		assertEquals("herb_catherby", target.getPatchKey());
		assertEquals(ItemID.RANARR_WEED, target.getPictureItemId());
	}

	@Test
	public void whatsHeldOnlyRedrawsTheRunAtALoadoutStep()
	{
		guide.start(herbs.getId());
		int before = changes;
		guide.setHeld(Collections.singletonMap(ItemID.SPADE, 1));
		assertEquals("the loadout's ticks follow it", before + 1, changes);

		guide.goTo(0);
		before = changes;
		guide.setHeld(Collections.singletonMap(ItemID.UNIDENTIFIED_RANARR, 9));
		assertEquals("at a patch the herbs landing changes nothing shown", before, changes);
	}

	@Test
	public void startingWithTheLoadoutAlreadyHeldGoesStraightToTheFirstPatch()
	{
		guide.setHeld(loadoutAt(RunProgress.START));
		guide.start(herbs.getId());

		assertEquals(0, guide.progress().getStop());
		assertTrue(guide.isStepDone(RunProgress.START));
	}

	@Test
	public void plantingAPatchMovesTheRunOn()
	{
		guide.restore(new RunProgress(herbs.getId(), 0));
		guide.tasksDone("herb_catherby", EnumSet.of(Task.HARVEST));
		assertEquals(0, guide.progress().getStop());
		assertEquals(EnumSet.of(Task.HARVEST), guide.done("herb_catherby"));

		guide.tasksDone("herb_catherby", EnumSet.of(Task.PLANT));
		assertEquals(1, guide.progress().getStop());
		assertTrue(guide.isStepDone(0));
		assertEquals("kept for the character", 1, saved.get(saved.size() - 1).getStop());
		assertTrue(saved.get(saved.size() - 1).done().get("herb_catherby").contains("PLANT"));
	}

	@Test
	public void aBankStopIsDoneWhenTheBankClosesWithTheLoadoutHeld()
	{
		guide.restore(new RunProgress(herbs.getId(), 1));
		Map<Integer, Integer> loadout = loadoutAt(1);
		guide.setHeld(loadout);
		assertEquals("the bank hasn't been visited", 1, guide.progress().getStop());

		guide.setBankOpen(true);
		assertEquals("still open", 1, guide.progress().getStop());
		guide.setBankOpen(false);
		assertEquals(2, guide.progress().getStop());
	}

	@Test
	public void closingTheBankWithoutTheLoadoutStaysPut()
	{
		guide.restore(new RunProgress(herbs.getId(), 1));
		guide.setBankOpen(true);
		guide.setBankOpen(false);
		assertEquals(1, guide.progress().getStop());
	}

	@Test
	public void patchesDoneOutOfOrderAreSkipped()
	{
		RunProfile three = runs.create("Three herbs");
		three.add(RunStop.patch("herb_catherby"));
		three.add(RunStop.patch("herb_falador"));
		three.add(RunStop.patch("herb_ardougne"));
		guide.restore(new RunProgress(three.getId(), 0));

		guide.tasksDone("herb_ardougne", EnumSet.of(Task.PLANT));
		assertEquals("not the current stop", 0, guide.progress().getStop());
		guide.tasksDone("herb_catherby", EnumSet.of(Task.PLANT));
		assertEquals(1, guide.progress().getStop());
		guide.tasksDone("herb_falador", EnumSet.of(Task.PLANT));
		assertNull("Ardougne was already done, so the run is over", guide.progress());
	}

	@Test
	public void movesBackAndForthByHandAndEndsAfterTheLastStop()
	{
		guide.start(herbs.getId());
		guide.next();
		guide.next();
		Target bank = guide.target();
		assertEquals("Seers' Village bank", bank.getLabel());
		assertNull(bank.getPatchType());

		guide.back();
		guide.back();
		guide.back();
		assertEquals("can't go back past the start", RunProgress.START, guide.progress().getStop());

		guide.goTo(2);
		guide.next();
		assertNull("finished", guide.progress());
		assertNull("forgotten", saved.get(saved.size() - 1));
	}

	@Test
	public void restoringDoesntSaveAgain()
	{
		guide.restore(new RunProgress(herbs.getId(), 2));

		assertEquals(2, guide.progress().getStop());
		assertTrue(saved.isEmpty());
	}

	@Test
	public void progressForAMissingRunOrStopIsDroppedOrKeptInRange()
	{
		guide.restore(new RunProgress("no-such-run", 0));
		assertNull(guide.progress());

		guide.restore(new RunProgress(herbs.getId(), 9));
		assertEquals("the last stop", 2, guide.progress().getStop());
	}

	@Test
	public void followsEditsToTheRun()
	{
		guide.restore(new RunProgress(herbs.getId(), 2));

		herbs.remove(2);
		guide.refresh();
		assertEquals("its stop was removed", 1, guide.progress().getStop());
		assertEquals(1, saved.get(saved.size() - 1).getStop());

		runs.delete(herbs.getId());
		guide.refresh();
		assertNull(guide.progress());
		assertFalse(guide.isDoing(herbs.getId()));
	}

	@Test
	public void onlyRealChangesAreAnnounced()
	{
		guide.start(herbs.getId());
		int before = changes;
		guide.refresh();
		guide.back();
		guide.tasksDone("herb_ardougne", EnumSet.of(Task.PLANT));
		assertEquals(before, changes);
	}

	private Map<Integer, Integer> loadoutAt(int step)
	{
		Map<Integer, Integer> held = new HashMap<>();
		for (Leg leg : LoadoutPlanner.plan(herbs, crops))
		{
			if (leg.getStopIndex() == step)
			{
				for (LoadoutItem item : leg.getLoadout())
				{
					held.put(item.getItemId(), item.getQuantity());
				}
			}
		}
		return held;
	}
}

package com.patchpilot.plan;

import static org.junit.Assert.assertEquals;
