import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class LoadoutCheckTest
{
	@Test
	public void countsWhatsHeldTowardsTheLoadout()
	{
		CropSetup setup = new CropSetup();
		setup.choice(PatchType.TREE).setCrop("magic");
		setup.choice(PatchType.CELASTRUS).setCrop("celastrus");
		RunProfile run = new SavedRuns().create("Trees");
		run.add(RunStop.patch("tree_falador"));
		run.add(RunStop.patch("tree_lumbridge"));
		run.add(RunStop.patch("celastrus_farming_guild"));
		List<LoadoutItem> loadout = LoadoutPlanner.plan(run, setup).get(0).getLoadout();

		Map<Integer, Integer> held = new HashMap<>();
		held.put(ItemID.SPADE, 1);
		held.put(ItemID.RAKE, 1);
		held.put(ItemID.DRAGON_AXE, 1);
		held.put(ItemID.PLANTPOT_MAGIC_TREE_SAPLING, 1);
		held.put(ItemID.COCONUT, 30);
		held.put(ItemID.Cert.COCONUT, 20);

		List<LoadoutItem> missing = LoadoutCheck.missing(loadout, held);
		assertEquals(5, missing.size());
		assertEquals("Magic sapling", missing.get(0).getName());
		assertEquals("one more", 1, missing.get(0).getQuantity());
		assertEquals("Celastrus sapling", missing.get(1).getName());
		assertEquals("Ultracompost", missing.get(2).getName());
		assertEquals("Potato cactus", missing.get(3).getName());
		assertEquals("Coins", missing.get(4).getName());
		assertEquals(400, missing.get(4).getQuantity());
		for (LoadoutItem item : loadout)
		{
			held.put(item.getItemId(), item.getQuantity());
		}
		assertTrue(LoadoutCheck.missing(loadout, held).isEmpty());
	}

	@Test
	public void aStaffSuppliesItsRunesAndCombinationRunesCount()
	{
		CropSetup setup = new CropSetup();
		RunProfile run = new SavedRuns().create("Camelot");
		run.add(RunStop.patch("herb_catherby").withTeleport("camelot_teleport"));
		List<LoadoutItem> loadout = LoadoutPlanner.plan(run, setup).get(0).getLoadout();

		Map<Integer, Integer> held = new HashMap<>();
		held.put(ItemID.SPADE, 1);
		held.put(ItemID.RAKE, 1);
		held.put(ItemID.DIBBER, 1);
		held.put(ItemID.LAWRUNE, 1);
		held.put(ItemID.DUSTRUNE, 2);
		assertEquals("3 more air runes", 3, LoadoutCheck.missing(loadout, held).get(0).getQuantity());

		held.put(ItemID.STAFF_OF_AIR, 1);
		assertTrue(LoadoutCheck.missing(loadout, held).isEmpty());
	}
}

