	private static CropSetup crops()
	{
		CropSetup setup = new CropSetup();
		setup.choice(PatchType.HERB).setCrop("ranarr");
		setup.choice(PatchType.TREE).setCrop("magic");
		setup.choice(PatchType.FRUIT_TREE).setCrop("dragonfruit");
		PlayerFacts facts = new PlayerFacts();
		facts.setOwned(new HashSet<>(Collections.singleton(ItemID.BH_RUNE_POUCH)));
		setup.setFacts(facts);
		return setup;
	}

	static void own(CropSetup setup, Gear... gear)
	{
		PlayerFacts facts = setup.facts();
		Set<Integer> owned = new HashSet<>(facts.getOwned());
		for (Gear each : gear)
		{
			for (Gear.Piece piece : each.getPieces())
			{
				owned.add(piece.getItemId());
			}
		}
		facts.setOwned(owned);
		setup.setFacts(facts);
	}

	private static RunProfile run(String... stops)
	{
		RunProfile run = new SavedRuns().create("Test run");
		for (String stop : stops)
		{
			String[] parts = stop.split(" ");
			String key = parts[0];
			RunStop runStop = key.startsWith("bank:") ? RunStop.bank(key.substring(5)) : RunStop.patch(key);
			run.add(parts.length > 1 ? runStop.withTeleport(parts[1]) : runStop);
		}
		return run;
	}

	private static Leg only(RunProfile run, CropSetup setup)
	{
		List<Leg> legs = LoadoutPlanner.plan(run, setup);
		assertEquals(1, legs.size());
		return legs.get(0);
	}

	private static LoadoutItem item(Leg leg, String name)
	{
		for (LoadoutItem item : leg.getLoadout())
		{
			if (item.getName().equals(name))
			{
				return item;
			}
		}
		return null;
	}

	private static List<String> names(Leg leg)
	{
		List<String> names = new ArrayList<>();
		for (LoadoutItem item : leg.getLoadout())
		{
			names.add(item.getName());
		}
		return names;
	}

	private static List<String> names(String... names)
	{
		List<String> list = new ArrayList<>();
		java.util.Collections.addAll(list, names);
		return list;
	}
}

package com.patchpilot.plan;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.patchpilot.data.Compost;
import com.patchpilot.data.Gear;
import com.patchpilot.data.PatchType;
import com.patchpilot.setup.CropSetup;
import com.patchpilot.setup.RunProfile;
import com.patchpilot.setup.RunStop;
import com.patchpilot.setup.SavedRuns;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class RunEstimateTest
{
	private static final Map<Integer, Long> PRICES = new HashMap<>();

	static
	{
		PRICES.put(ItemID.PLANTPOT_MAGIC_TREE_SAPLING, 100_000L);
		PRICES.put(ItemID.COCONUT, 1_000L);
		PRICES.put(ItemID.RANARR_SEED, 40_000L);
		PRICES.put(ItemID.UNIDENTIFIED_RANARR, 7_000L);
		PRICES.put(ItemID.BUCKET_ULTRACOMPOST, 1_500L);
		PRICES.put(ItemID.POH_TABLET_CAMELOTTELEPORT, 600L);
	}

	@Test
	public void aProtectedTreeIsItsPlantingAndCheckXpAndCostsItsSaplingPaymentAndFee()
	{
		RunEstimate estimate = RunEstimate.of(run("tree_falador"), crops(), RunEstimateTest::price);

		assertEquals("planting and the health check", 145.5 + 13768.3, estimate.getXp(), 1e-6);
		assertEquals("sapling, 25 coconuts, 200 coins to remove the old one", 100_000 + 25 * 1_000 + 200,
			estimate.getCost());
		assertEquals("nothing to pick", 0, estimate.getHarvestValue());
		assertFalse(estimate.isPricesMissing());
	}

	@Test
	public void herbsAreAnAverageHarvestAtTheirPrice()
	{
		RunEstimate estimate = RunEstimate.of(run("herb_catherby"), crops(), RunEstimateTest::price);

		double herbs = 6 * 256.0 / 175;
		assertEquals(27 + 30.5 * herbs, estimate.getXp(), 1e-6);
		assertEquals("a seed and a bucket", 40_000 + 1_500, estimate.getCost());
		assertEquals(Math.round(7_000 * herbs), estimate.getHarvestValue());
		assertEquals(estimate.getHarvestValue() - estimate.getCost(), estimate.profit());
	}

	@Test
	public void theFarmersOutfitAddsItsXpAndTabletsCost()
	{
		CropSetup setup = crops();
		LoadoutPlannerTest.own(setup, Gear.FARMERS_OUTFIT);
		RunProfile run = run("tree_falador");
		run.setTeleport(0, "camelot_tablet");
		RunEstimate estimate = RunEstimate.of(run, setup, RunEstimateTest::price);

		assertEquals((145.5 + 13768.3) * 1.025, estimate.getXp(), 1e-6);
		assertEquals(100_000 + 25 * 1_000 + 200 + 600, estimate.getCost());
	}

	@Test
	public void aBottomlessBucketUseIsHalfABucketOfUltracompost()
	{
		CropSetup setup = crops();
		setup.setCompost(Compost.BOTTOMLESS);
		RunEstimate estimate = RunEstimate.of(run("herb_catherby"), setup, RunEstimateTest::price);

		assertEquals(40_000 + 750, estimate.getCost());
	}

	@Test
	public void aMissingPriceIsFlagged()
	{
		CropSetup setup = crops();
		setup.choice(PatchType.FRUIT_TREE).setCrop("dragonfruit");
		RunEstimate estimate = RunEstimate.of(run("fruit_tree_catherby"), setup, RunEstimateTest::price);

		assertTrue(estimate.isPricesMissing());
		assertEquals(1, estimate.getPatches());
	}

	private static long price(int itemId)
	{
		return PRICES.getOrDefault(itemId, 0L);
	}

	private static CropSetup crops()
	{
		CropSetup setup = new CropSetup();
		setup.choice(PatchType.HERB).setCrop("ranarr");
		setup.choice(PatchType.TREE).setCrop("magic");
		return setup;
	}

	private static RunProfile run(String... patchKeys)
	{
		RunProfile run = new SavedRuns().create("Estimate");
		for (String key : patchKeys)
		{
			run.add(RunStop.patch(key));
		}
		return run;
	}
}

