			StopTasks.lines(HERB, setup, HERBS_READY, EnumSet.of(Task.HARVEST))));
		assertEquals(Collections.singleton(ItemID.RANARR_SEED), StopTasks.itemsNext(PatchType.HERB, setup,
			StopTasks.lines(HERB, setup, HERBS_READY, EnumSet.of(Task.HARVEST, Task.COMPOST))));
		assertEquals("all done", Collections.emptySet(), StopTasks.itemsNext(PatchType.HERB, setup,
			StopTasks.lines(HERB, setup, HERBS_PLANTED, EnumSet.of(Task.HARVEST, Task.COMPOST, Task.PLANT))));
		assertEquals(Collections.singleton(ItemID.RAKE),
			StopTasks.itemsNext(PatchType.HERB, setup, StopTasks.lines(HERB, setup, WEEDY, none())));
		assertEquals(Collections.singleton(ItemID.SPADE),
			StopTasks.itemsNext(PatchType.HERB, setup, StopTasks.lines(HERB, setup, HERBS_DEAD, none())));
	}

	@Test
	public void theGardenersPaidWithWhatTheyTake()
	{
		CropSetup setup = crops();
		assertEquals("coins to remove the tree", Collections.singleton(ItemID.COINS), StopTasks.itemsNext(
			PatchType.TREE, setup, StopTasks.lines(TREE, setup, MAGIC_UNCHECKED, EnumSet.of(Task.CHECK))));
		assertEquals("coconuts, noted or not, to protect it",
			new HashSet<>(Arrays.asList(ItemID.COCONUT, ItemID.Cert.COCONUT)), StopTasks.itemsNext(PatchType.TREE,
				setup, StopTasks.lines(TREE, setup, MAGIC_PLANTED, EnumSet.of(Task.CHECK, Task.REMOVE, Task.PLANT))));
	}

	@Test
	public void aDeadPlantIsCleared()
	{
		List<StopTasks.Line> lines = StopTasks.lines(HERB, crops(), HERBS_DEAD, none());
		assertEquals("Clear the dead herbs", lines.get(0).getLabel());
	}

	@Test
	public void anUnseenPatchIsExpectedToBeGrown()
	{
		assertEquals(EnumSet.of(Task.CHECK, Task.HARVEST, Task.REMOVE, Task.PLANT, Task.PROTECT),
			tasks(StopTasks.lines(FRUIT, crops(), null, none())));
		assertEquals("calquats are dug up, not chopped by the gardener", "Dig up the tree",
			StopTasks.lines(CALQUAT, crops(), null, none()).get(2).getLabel());
		for (StopTasks.Line line : StopTasks.lines(PatchCatalog.find("celastrus_farming_guild"), crops(), null, none()))
		{
			if (line.getTask() == Task.REMOVE)
			{
				assertEquals("a celastrus needs the axe first", "Chop the tree down and dig it up", line.getLabel());
			}
		}
	}

	@Test
	public void theGardenerIsPaidOnceTheTreesCheckedAndOnceTheNewOnesPlanted()
	{
		assertEquals("check the tree first", null,
			StopTasks.gardenerNext(PatchType.TREE, StopTasks.lines(TREE, crops(), null, none())));
		assertEquals(Task.REMOVE, StopTasks.gardenerNext(PatchType.TREE,
			StopTasks.lines(TREE, crops(), null, EnumSet.of(Task.CHECK))));
		assertEquals("compost and plant first", null, StopTasks.gardenerNext(PatchType.TREE,
			StopTasks.lines(TREE, crops(), null, EnumSet.of(Task.CHECK, Task.REMOVE))));
		assertEquals("composting or not", Task.PROTECT, StopTasks.gardenerNext(PatchType.TREE,
			StopTasks.lines(TREE, crops(), null, EnumSet.of(Task.CHECK, Task.REMOVE, Task.PLANT))));
		assertEquals("a calquat's dug up, not paid for", null, StopTasks.gardenerNext(PatchType.CALQUAT,
			StopTasks.lines(CALQUAT, crops(), null, EnumSet.of(Task.CHECK, Task.HARVEST))));
	}

	@Test
	public void ticksThatDontBelongToTheKindOfPatchArentShown()
	{
		Set<Task> done = EnumSet.of(Task.CHECK, Task.HARVEST, Task.REMOVE, Task.PLANT);
		List<StopTasks.Line> lines = StopTasks.lines(TREE, crops(), MAGIC_PLANTED, done);

		assertEquals(EnumSet.of(Task.CHECK, Task.REMOVE, Task.PLANT, Task.PROTECT), tasks(lines));
	}

	@Test
	public void doneTasksStayTickedOnceThePatchHasMovedOn()
	{
		Set<Task> done = EnumSet.of(Task.HARVEST, Task.PLANT);
		List<StopTasks.Line> lines = StopTasks.lines(HERB, crops(), HERBS_PLANTED, done);

		assertEquals(EnumSet.of(Task.HARVEST, Task.COMPOST, Task.PLANT), tasks(lines));
		assertTrue(lines.get(0).isDone());
		assertFalse("compost wasn't seen", lines.get(1).isDone());
		assertTrue(lines.get(2).isDone());
	}

	@Test
	public void aStopIsDoneOncePlantedAndPaidFor()
	{
		assertTrue(StopTasks.isDone(HERB, crops(), EnumSet.of(Task.PLANT)));
		assertFalse(StopTasks.isDone(TREE, crops(), EnumSet.of(Task.PLANT)));
		assertTrue(StopTasks.isDone(TREE, crops(), EnumSet.of(Task.PLANT, Task.PROTECT)));
	}

	@Test
	public void somethingStillGrowingIsNotReady()
	{
		PatchStatus growing = new PatchStatus(PatchStatus.Kind.GROWING, Plant.RANARR, 1000, HERBS_GROWING);
		assertTrue(StopTasks.notReady(growing, none()));
		assertFalse("planted this run", StopTasks.notReady(growing, EnumSet.of(Task.PLANT)));
		assertFalse("grown since it was seen",
			StopTasks.notReady(new PatchStatus(PatchStatus.Kind.READY, Plant.YEW, 0, YEW_UNCHECKED), none()));
		assertFalse(StopTasks.notReady(PatchStatus.unknown(), none()));
		assertFalse(StopTasks.notReady(null, none()));
	}

	@Test
	public void changesInThePatchShowWhatWasDone()
	{
		assertEquals(EnumSet.of(Task.HARVEST), StopTasks.doneBetween(PatchType.HERB, crops(), HERBS_READY, RAKED));
		assertEquals(EnumSet.of(Task.CHECK),
			StopTasks.doneBetween(PatchType.TREE, crops(), MAGIC_UNCHECKED, MAGIC_CHECKED));
		assertEquals("no fruit on a magic tree", EnumSet.of(Task.REMOVE),
			StopTasks.doneBetween(PatchType.TREE, crops(), MAGIC_CHECKED, RAKED));
		assertEquals(EnumSet.of(Task.RAKE), StopTasks.doneBetween(PatchType.HERB, crops(), WEEDY, RAKED));
		assertEquals(EnumSet.of(Task.CLEAR), StopTasks.doneBetween(PatchType.HERB, crops(), HERBS_DEAD, RAKED));
		assertEquals(EnumSet.of(Task.HARVEST), StopTasks.doneBetween(PatchType.FRUIT_TREE, crops(),
			new PatchReading(Plant.DRAGONFRUIT, CropState.HARVESTABLE, 6),
			new PatchReading(Plant.DRAGONFRUIT, CropState.HARVESTABLE, 0)));
		assertTrue("growing on its own isn't a task", StopTasks.doneBetween(PatchType.HERB, crops(),
			HERBS_PLANTED, HERBS_GROWING).isEmpty());
		assertTrue(StopTasks.doneBetween(PatchType.HERB, crops(), null, HERBS_PLANTED).isEmpty());
	}

	@Test
	public void plantingTicksOnlyWhatThePatchNeededFirst()
	{
		assertEquals("cleared already: nothing else to tick", EnumSet.of(Task.PLANT),
			StopTasks.doneBetween(PatchType.TREE, crops(), RAKED, MAGIC_PLANTED));
		assertEquals("weeds have to be raked before planting", EnumSet.of(Task.RAKE, Task.PLANT),
			StopTasks.doneBetween(PatchType.HERB, crops(), WEEDY, HERBS_PLANTED));
		assertEquals("the steps between were missed", EnumSet.of(Task.REMOVE, Task.PLANT),
			StopTasks.doneBetween(PatchType.TREE, crops(), MAGIC_CHECKED, MAGIC_PLANTED));
	}

	private static CropSetup crops()
	{
		CropSetup setup = new CropSetup();
		setup.choice(PatchType.HERB).setCrop("ranarr");
		setup.choice(PatchType.TREE).setCrop("magic");
		setup.choice(PatchType.FRUIT_TREE).setCrop("dragonfruit");
		setup.choice(PatchType.CALQUAT).setCrop("calquat");
		setup.choice(PatchType.ALLOTMENT).setCrop("potato");
		setup.choice(PatchType.FLOWER).setCrop("marigold");
		return setup;
	}

	private static Set<Task> none()
	{
		return EnumSet.noneOf(Task.class);
	}

	private static Set<Task> tasks(List<StopTasks.Line> lines)
	{
		Set<Task> tasks = EnumSet.noneOf(Task.class);
		for (StopTasks.Line line : lines)
		{
			tasks.add(line.getTask());
		}
		return tasks;
	}

	private static List<String> labels(List<StopTasks.Line> lines)
	{
		List<String> labels = new ArrayList<>();
		for (StopTasks.Line line : lines)
		{
			labels.add(line.getLabel());
		}
		return labels;
	}
}

package com.patchpilot.setup;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.patchpilot.data.Compost;
import com.patchpilot.data.Gear;
import com.patchpilot.data.PatchType;
import com.patchpilot.data.Tool;
import java.util.Arrays;
import java.util.HashSet;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class CropSetupTest
{
	private final Gson gson = new Gson();

	@Test
	public void protectsOnlyWhenACropWithAPaymentIsChosen()
	{
		CropSetup setup = new CropSetup();
		assertFalse("no crop chosen yet", setup.protects(PatchType.TREE));

		setup.choice(PatchType.TREE).setCrop("magic");
		assertTrue(setup.protects(PatchType.TREE));

		setup.choice(PatchType.TREE).setProtect(false);
		assertFalse(setup.protects(PatchType.TREE));

		setup.choice(PatchType.HERB).setCrop("ranarr");
		assertFalse("herbs can't be protected", setup.protects(PatchType.HERB));
	}

	@Test
	public void harvestFollowsThePatchTypesRule()
	{
		CropSetup setup = new CropSetup();
		assertTrue(setup.harvests(PatchType.HERB));
		assertTrue(setup.harvests(PatchType.CALQUAT));
		assertFalse(setup.harvests(PatchType.TREE));
		assertTrue("optional, on by default", setup.harvests(PatchType.FRUIT_TREE));

		setup.choice(PatchType.FRUIT_TREE).setHarvest(false);
		assertFalse(setup.harvests(PatchType.FRUIT_TREE));
		setup.choice(PatchType.CALQUAT).setHarvest(false);
		assertTrue("calquat fruit is always picked", setup.harvests(PatchType.CALQUAT));
	}

	@Test
	public void survivesASaveAndLoad()
	{
		CropSetup setup = new CropSetup();
		setup.choice(PatchType.HERB).setCrop("snapdragon");
		setup.choice(PatchType.FRUIT_TREE).setCrop("dragonfruit");
		setup.choice(PatchType.FRUIT_TREE).setProtect(false);

		CropSetup loaded = gson.fromJson(gson.toJson(setup), CropSetup.class);
		assertEquals("Snapdragon", loaded.crop(PatchType.HERB).getName());
		assertEquals("Dragonfruit", loaded.crop(PatchType.FRUIT_TREE).getName());
		assertFalse(loaded.protects(PatchType.FRUIT_TREE));
	}

	@Test
	public void oldOrOddSavesStillLoad()
	{
		CropSetup partial = gson.fromJson("{\"choices\":{\"TREE\":{\"crop\":\"yew\"}}}", CropSetup.class);
		assertTrue(partial.protects(PatchType.TREE));

		CropSetup unknown = gson.fromJson(
			"{\"choices\":{\"TREE\":{\"crop\":\"elder\"},\"GONE\":{\"crop\":\"x\"}}}", CropSetup.class);
		assertNull(unknown.crop(PatchType.TREE));

		CropSetup empty = gson.fromJson("{}", CropSetup.class);
		assertNull(empty.crop(PatchType.HERB));
	}

	@Test
	public void compostHasADefaultAndIsSaved()
	{
		CropSetup fresh = new CropSetup();
		assertEquals(Compost.ULTRACOMPOST, fresh.compost());
		fresh.setCompost(Compost.BOTTOMLESS);
		CropSetup loaded = gson.fromJson(gson.toJson(fresh), CropSetup.class);
		assertEquals(Compost.BOTTOMLESS, loaded.compost());

		CropSetup old = gson.fromJson("{\"choices\":{}}", CropSetup.class);
		assertEquals(Compost.ULTRACOMPOST, old.compost());
		CropSetup odd = gson.fromJson("{\"compost\":\"MAGIC_DUST\",\"toolsLeftBehind\":[\"RAKE\"],"
			+ "\"gear\":[\"GRACEFUL\"]}", CropSetup.class);
		assertEquals(Compost.ULTRACOMPOST, odd.compost());
	}

	@Test
	public void toolsAndGearFollowWhatsOwned()
	{
		CropSetup setup = new CropSetup();
		assertTrue("every tool is taken where it's needed", setup.brings(Tool.SPADE));
		assertFalse("no rune pouch till one's seen", setup.brings(Tool.RUNE_POUCH));
		assertFalse(setup.uses(Gear.GRACEFUL));

		PlayerFacts facts = new PlayerFacts();
		facts.setOwned(new HashSet<>(Arrays.asList(ItemID.BH_RUNE_POUCH, ItemID.GRACEFUL_BOOTS)));
		setup.setFacts(facts);
		assertTrue(setup.brings(Tool.RUNE_POUCH));
		assertTrue("one piece is enough", setup.uses(Gear.GRACEFUL));
		assertFalse(setup.uses(Gear.FARMERS_OUTFIT));
		assertTrue("the facts aren't saved with the setup", gson.toJson(setup).indexOf("owned") < 0);
	}

	@Test
	public void compostGoesOnHerbsHarvestedCelastrusAndUnprotectedTrees()
	{
		CropSetup setup = new CropSetup();
		setup.choice(PatchType.TREE).setCrop("magic");
		setup.choice(PatchType.CELASTRUS).setCrop("celastrus");
		assertTrue("herbs can't be protected", setup.composts(PatchType.HERB));
		assertFalse("the gardener protects it", setup.composts(PatchType.TREE));
		assertTrue("protected, but compost means more bark", setup.composts(PatchType.CELASTRUS));

		setup.choice(PatchType.TREE).setProtect(false);
		assertTrue(setup.composts(PatchType.TREE));
		setup.choice(PatchType.CELASTRUS).setHarvest(false);
		assertFalse("protected, and no bark to gain", setup.composts(PatchType.CELASTRUS));
		setup.choice(PatchType.CELASTRUS).setProtect(false);
		assertTrue(setup.composts(PatchType.CELASTRUS));

		setup.setCompost(Compost.NONE);
		assertFalse(setup.composts(PatchType.HERB));
	}
}

package com.patchpilot.setup;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class SavedRunsTest
{
	private final Gson gson = new Gson();

	@Test
	public void newRunsGetFreeNames()
	{
		SavedRuns runs = new SavedRuns();
		assertEquals("New run", runs.create("New run").getName());
		assertEquals("New run 2", runs.create("New run").getName());
		assertEquals("names clash ignoring case, but keep the player's spelling",
			"new run 3", runs.create("new run").getName());
	}

	@Test
	public void renameKeepsNamesDistinctAndIgnoresBlanks()
	{
		SavedRuns runs = new SavedRuns();
		RunProfile herbs = runs.create("Herb run");
		RunProfile trees = runs.create("Tree run");

		runs.rename(trees, "  ");
		assertEquals("blank keeps the old name", "Tree run", trees.getName());

		runs.rename(trees, "Herb run");
		assertEquals("Herb run 2", trees.getName());

		runs.rename(herbs, "HERB RUN");
		assertEquals("its own name doesn't count as taken", "HERB RUN", herbs.getName());
	}

	@Test
	public void duplicateCopiesStopsUnderANewIdNextToTheOriginal()
	{
		SavedRuns runs = new SavedRuns();
		RunProfile herbs = runs.create("Herb run");
		RunProfile other = runs.create("Other");
		herbs.add(RunStop.patch("herb_catherby"));
		herbs.add(RunStop.bank("catherby"));

		RunProfile copy = runs.duplicate(herbs);
		assertEquals("Herb run copy", copy.getName());
		assertNotEquals(herbs.getId(), copy.getId());
		assertEquals(herbs.getStops(), copy.getStops());
		assertEquals(Arrays.asList(herbs, copy, other), runs.getRuns());

		copy.remove(0);
		assertEquals("the original is untouched", 2, herbs.getStops().size());
	}

	@Test
	public void deleteRemovesOnlyThatRun()
	{
		SavedRuns runs = new SavedRuns();
		RunProfile a = runs.create("A");
		RunProfile b = runs.create("B");
		runs.delete(a.getId());
		assertEquals(Arrays.asList(b), runs.getRuns());
		assertNull(runs.find(a.getId()));
	}

	@Test
	public void stopsMoveAndCount()
	{
		RunProfile run = new SavedRuns().create("Run");
		RunStop catherby = RunStop.patch("herb_catherby");
		RunStop falador = RunStop.patch("herb_falador");
		RunStop bank = RunStop.bank("seers_village");
		run.add(catherby);
		run.add(falador);
		run.add(bank);
		assertEquals(2, run.patchCount());
		assertEquals(1, run.bankCount());

		run.move(2, 1);
		assertEquals(Arrays.asList(catherby, bank, falador), run.getStops());
		run.move(0, 2);
		assertEquals(Arrays.asList(bank, falador, catherby), run.getStops());
		assertTrue(run.contains(falador));
		assertTrue(run.contains(RunStop.patch("herb_falador")));
	}

	@Test
	public void removesAStopWhereverItIs()
	{
		RunProfile run = new SavedRuns().create("Run");
		RunStop catherby = RunStop.patch("herb_catherby");
		RunStop falador = RunStop.patch("herb_falador");
		run.add(catherby);
		run.add(falador);
		assertTrue(run.remove(RunStop.patch("herb_catherby")));
		assertEquals(Arrays.asList(falador), run.getStops());
		assertFalse("not in the run", run.remove(catherby));
	}

	@Test
	public void listsThePatchesNotYetInTheRun()
	{
		RunProfile run = new SavedRuns().create("Run");
		assertEquals(3, run.patchesToAdd(PatchType.CALQUAT).size());

		run.add(RunStop.patch("calquat_kastori"));
		List<PatchLocation> left = run.patchesToAdd(PatchType.CALQUAT);
		assertEquals(2, left.size());
		assertEquals("Great Conch", left.get(0).getName());
		assertEquals("Tai Bwo Wannai", left.get(1).getName());

		run.add(RunStop.patch("calquat_great_conch"));
		run.add(RunStop.patch("calquat_tai_bwo_wannai"));
		assertTrue("all in the run", run.patchesToAdd(PatchType.CALQUAT).isEmpty());
		assertEquals("other types unaffected", 1, run.patchesToAdd(PatchType.REDWOOD).size());
	}

	@Test
	public void stopsKnowWhatTheyAre()
	{
		assertEquals("Catherby herb", RunStop.patch("herb_catherby").patch().getLabel());
		assertEquals("Seers' Village", RunStop.bank("seers_village").bank().getName());
		assertNull(RunStop.patch("seers_village").patch());
		assertFalse("a newer version's patch", RunStop.patch("herb_somewhere_new").isKnown());
	}

	@Test
	public void survivesASaveAndLoad()
	{
		SavedRuns runs = new SavedRuns();
		RunProfile run = runs.create("Herb run");
		run.add(RunStop.patch("herb_catherby"));
		run.add(RunStop.bank("seers_village"));

		SavedRuns loaded = gson.fromJson(gson.toJson(runs), SavedRuns.class);
		assertEquals(1, loaded.getVersion());
		RunProfile back = loaded.find(run.getId());
		assertEquals("Herb run", back.getName());
		assertEquals(run.getStops(), back.getStops());
	}

	@Test
	public void oddSavesStillLoad()
	{
		SavedRuns empty = gson.fromJson("{}", SavedRuns.class);
		assertTrue(empty.getRuns().isEmpty());

		SavedRuns noStops = gson.fromJson("{\"runs\":[{\"id\":\"x\",\"name\":\"Old\"}]}", SavedRuns.class);
		List<RunStop> stops = noStops.find("x").getStops();
		assertTrue(stops.isEmpty());
	}
}

package com.patchpilot.status;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import com.patchpilot.data.Crop;
import com.patchpilot.data.CropCatalog;
import com.patchpilot.data.PatchCatalog;
import com.patchpilot.data.PatchLocation;
import com.patchpilot.data.PatchType;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class GrowthTest
{
	private static final long TICK = 1_200_000L;

	private final Map<String, String> states = new HashMap<>();
	private Integer offset;
	private Integer precision;
	private final Growth.Saved saved = new Growth.Saved()
	{
		@Override
		public String patchState(String key)
		{
			return states.get(key);
		}

		@Override
		public Integer tickOffsetMinutes()
		{
			return offset;
		}

		@Override
		public Integer tickOffsetPrecisionMinutes()
		{
			return precision;
		}
	};

	@Test
	public void readsTheValuesRuneLiteDoes()
	{
		assertEquals(new PatchReading(Plant.RANARR, CropState.GROWING, 3), GrowthTable.read(PatchType.HERB, 35));
		assertEquals(new PatchReading(Plant.RANARR, CropState.HARVESTABLE, 2), GrowthTable.read(PatchType.HERB, 36));
		assertEquals(new PatchReading(Plant.WEEDS, CropState.GROWING, 0), GrowthTable.read(PatchType.HERB, 3));
		assertEquals(Plant.MAGIC, GrowthTable.read(PatchType.TREE, 60).getPlant());
		assertEquals("fully grown, waiting for its health check", 12, GrowthTable.read(PatchType.TREE, 60).getStage());
		assertNull("the redwood patch doesn't use it", GrowthTable.read(PatchType.REDWOOD, 39));
	}

	@Test
	public void everyCropCanBeRecognised()
	{
		for (PatchType type : PatchType.values())
		{
			for (Crop crop : CropCatalog.crops(type))
			{
				Plant found = null;
				for (Plant plant : Plant.values())
				{
					if (crop.getKey().equals(plant.getCropKey()))
					{
						found = plant;
					}
				}
				assertNotNull(crop.getName() + " has no plant", found);
			}
		}
	}

	@Test
	public void usesTimeTrackingsKeyForEachPatch()
	{
		PatchLocation catherby = PatchCatalog.find("herb_catherby");
		assertEquals("11062.4774", Growth.key(catherby));
	}

	@Test
	public void aGrowingHerbIsReadyWhenItsLastTickComes()
	{
		PatchLocation patch = PatchCatalog.find("herb_catherby");
		states.put(Growth.key(patch), "32:" + (TICK + 300));

		PatchStatus growing = Growth.status(patch, saved, TICK + 600);
		assertEquals(PatchStatus.Kind.GROWING, growing.getKind());
		assertEquals(Plant.RANARR, growing.getPlant());
		assertEquals(TICK + 4 * 1200, growing.getReadyAt());
		assertEquals("1h 10m", growing.describe(TICK + 600));

		assertEquals(PatchStatus.Kind.READY, Growth.status(patch, saved, TICK + 4 * 1200).getKind());
	}

	@Test
	public void somethingGrownSinceItWasSeenIsReadAsItIsNow()
	{
		PatchLocation tree = PatchCatalog.find("tree_gnome_stronghold");
		states.put(Growth.key(tree), "44:" + TICK);
		PatchStatus yew = Growth.status(tree, saved, TICK + 7 * 24 * 3600);
		assertEquals(PatchStatus.Kind.READY, yew.getKind());
		assertEquals(new PatchReading(Plant.YEW, CropState.GROWING, Plant.YEW.getStages() - 1), yew.getReading());

		PatchLocation herb = PatchCatalog.find("herb_catherby");
		states.put(Growth.key(herb), "32:" + TICK);
		assertEquals("herbs are ready to pick", CropState.HARVESTABLE,
			Growth.status(herb, saved, TICK + 24 * 3600).getReading().getState());
	}

	@Test
	public void anAllotmentGrownSinceItWasSeenIsReadyToHarvest()
	{
		PatchLocation allotment = PatchCatalog.find("allotment_catherby_north");
		assertEquals("11062.4771", Growth.key(allotment));
		states.put(Growth.key(allotment), "6:" + TICK);
		PatchStatus potatoes = Growth.status(allotment, saved, TICK + 24 * 3600);
		assertEquals(PatchStatus.Kind.READY, potatoes.getKind());
		assertEquals(new PatchReading(Plant.POTATO, CropState.HARVESTABLE, 2), potatoes.getReading());
	}

	@Test
	public void aKnownTickOffsetShiftsTheTicks()
	{
		PatchLocation patch = PatchCatalog.find("herb_catherby");
		states.put(Growth.key(patch), "32:" + (TICK + 300));
		offset = 3;
		precision = 20;

		assertEquals(TICK + 4 * 1200 - 180, Growth.status(patch, saved, TICK).getReadyAt());

		precision = 5;
		assertEquals("not trusted yet", TICK + 4 * 1200, Growth.status(patch, saved, TICK).getReadyAt());
	}

	@Test
	public void weedsDiseaseAndDeathAreReported()
	{
		PatchLocation patch = PatchCatalog.find("herb_catherby");
		states.put(Growth.key(patch), "0:" + TICK);
		assertEquals(PatchStatus.Kind.EMPTY, Growth.status(patch, saved, TICK).getKind());
		states.put(Growth.key(patch), "141:" + TICK);
		PatchStatus diseased = Growth.status(patch, saved, TICK);
		assertEquals(PatchStatus.Kind.DISEASED, diseased.getKind());
		assertEquals(Plant.RANARR, diseased.getPlant());
		states.put(Growth.key(patch), "170:" + TICK);
		assertEquals(PatchStatus.Kind.DEAD, Growth.status(patch, saved, TICK).getKind());
	}

	@Test
	public void unseenOrUnreadablePatchesAreUnknown()
	{
		PatchLocation patch = PatchCatalog.find("herb_catherby");
		assertEquals(PatchStatus.Kind.UNKNOWN, Growth.status(patch, saved, TICK).getKind());
		states.put(Growth.key(patch), "rubbish");
		assertEquals(PatchStatus.Kind.UNKNOWN, Growth.status(patch, saved, TICK).getKind());
		states.put(Growth.key(patch), "32:0");
		assertEquals(PatchStatus.Kind.UNKNOWN, Growth.status(patch, saved, TICK).getKind());
	}

	@Test
	public void timeLeftIsShortAndNeverZero()
	{
		assertEquals("1m", PatchStatus.timeLeft(5));
		assertEquals("20m", PatchStatus.timeLeft(20 * 60));
		assertEquals("1h 0m", PatchStatus.timeLeft(3600));
		assertEquals("2d 4h", PatchStatus.timeLeft((2 * 24 + 4) * 3600 + 120));
	}
}

