	private static final StatusSource STATUSES = new StatusSource()
	{
		@Override
		public PatchStatus status(PatchLocation patch)
		{
			long now = Instant.now().getEpochSecond();
			switch (patch.getType())
			{
				case HERB:
					switch (patch.getName().length() % 5)
					{
						case 0:
							return PatchStatus.of(PatchStatus.Kind.READY, Plant.RANARR, 0);
						case 1:
							return PatchStatus.of(PatchStatus.Kind.GROWING, Plant.RANARR, now + 35 * 60);
						case 2:
							return PatchStatus.of(PatchStatus.Kind.DISEASED, Plant.SNAPDRAGON, 0);
						case 3:
							return PatchStatus.of(PatchStatus.Kind.EMPTY, null, 0);
						default:
							return PatchStatus.of(PatchStatus.Kind.GROWING, Plant.TORSTOL, now + 75 * 60 + 30);
					}
				case ALLOTMENT:
					return PatchStatus.of(PatchStatus.Kind.GROWING, Plant.SNAPE_GRASS, now + 50 * 60);
				case FLOWER:
					return PatchStatus.of(PatchStatus.Kind.READY, Plant.WHITE_LILY, 0);
				case TREE:
					return PatchStatus.of(PatchStatus.Kind.GROWING, Plant.MAGIC, now + 6 * 3600 + 20 * 60);
				case FRUIT_TREE:
					return PatchStatus.of(PatchStatus.Kind.READY, Plant.DRAGONFRUIT, 0);
				case HARDWOOD_TREE:
					return PatchStatus.of(PatchStatus.Kind.GROWING, Plant.MAHOGANY, now + 2 * 86400 + 5 * 3600);
				default:
					return PatchStatus.unknown();
			}
		}

		@Override
		public boolean hasCharacter()
		{
			return true;
		}

		@Override
		public String problem()
		{
			return null;
		}
	};

