	private static void hoverRow(Container view, int n)
	{
		List<ListRow> rows = all(view, ListRow.class);
		if (n < rows.size())
		{
			rows.get(n).setHovered(true);
		}
	}

	private static <T> List<T> all(Container view, Class<T> type)
	{
		List<T> found = new java.util.ArrayList<>();
		for (Component child : view.getComponents())
		{
			if (type.isInstance(child))
			{
				found.add(type.cast(child));
			}
			if (child instanceof Container)
			{
				found.addAll(all((Container) child, type));
			}
		}
		return found;
	}

