	private static RowRenderer<Crop> renderer()
	{
		return new RowRenderer<>(PLACEHOLDERS, Crop::getProduceItemId, Crop::getName,
			crop -> "Level " + crop.getLevel(), "Choose a crop…");
	}

	private static void swatch(JPanel card, String name, Color color)
	{
		BufferedImage chip = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = chip.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		g.fillRoundRect(0, 0, 15, 15, 4, 4);
		g.setColor(Kit.OUTLINE_HOVER);
		g.drawRoundRect(0, 0, 15, 15, 4, 4);
		g.dispose();

		JPanel line = new JPanel(new BorderLayout(8, 0));
		line.setOpaque(false);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		line.setBorder(new EmptyBorder(1, 0, 1, 0));
		JLabel label = new JLabel(name, new ImageIcon(chip), JLabel.LEFT);
		label.setIconTextGap(8);
		label.setFont(Kit.SMALL);
		label.setForeground(Kit.TEXT);
		JLabel hex = new JLabel(String.format("#%06X", color.getRGB() & 0xFFFFFF));
		hex.setFont(Kit.SMALL);
		hex.setForeground(Kit.TEXT_DIM);
		line.add(label, BorderLayout.CENTER);
		line.add(hex, BorderLayout.EAST);
		card.add(line);
	}

	private static JPanel column()
	{
		JPanel column = new JPanel();
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		column.setOpaque(false);
		return column;
	}

	private static void add(JPanel page, JComponent card)
	{
		page.add(card);
		page.add(Box.createVerticalStrut(Kit.GAP));
	}

	private static JComponent fullWidth(JComponent component)
	{
		component.setMaximumSize(new java.awt.Dimension(Integer.MAX_VALUE, component.getPreferredSize().height));
		return component;
	}

	private static JPanel sidebar(JComponent content)
	{
		JPanel column = new JPanel(new BorderLayout());
		column.setBackground(Kit.PAGE);
		column.setBorder(new EmptyBorder(PluginPanel.BORDER_OFFSET, PluginPanel.BORDER_OFFSET,
			PluginPanel.BORDER_OFFSET, PluginPanel.BORDER_OFFSET));
		column.add(content, BorderLayout.NORTH);
		return column;
	}

	private static JLabel snapshot(Component component)
	{
		int width = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET - 22;
		component.setSize(width, component.getPreferredSize().height);
		layout(component);
		BufferedImage image = new BufferedImage(width, component.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		((JComponent) component).printAll(g);
		g.dispose();
		JLabel label = new JLabel(new ImageIcon(image));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static void save(JComponent view, File file) throws Exception
	{
		JFrame frame = new JFrame();
		frame.setUndecorated(true);
		frame.getContentPane().add(view);
		frame.pack();
		frame.setSize(PluginPanel.PANEL_WIDTH, view.getPreferredSize().height);
		frame.validate();
		layout(view);

		BufferedImage image = new BufferedImage(view.getWidth(), view.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		view.printAll(g);
		g.dispose();

		BufferedImage big = new BufferedImage(image.getWidth() * SCALE, image.getHeight() * SCALE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D bg = big.createGraphics();
		bg.drawImage(image, 0, 0, big.getWidth(), big.getHeight(), null);
		bg.dispose();
		ImageIO.write(big, "png", file);
		frame.dispose();
	}

	private static void layout(Component component)
	{
		if (component instanceof Container)
		{
			Container container = (Container) component;
			container.doLayout();
			for (Component child : container.getComponents())
			{
				layout(child);
			}
		}
	}

	private static ImageIcon placeholder(int width, int height, Color color)
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(color);
		g.fillOval(width / 8, height / 12, width - width / 4, height - height / 6);
		g.dispose();
		return new ImageIcon(image);
	}
}

package com.patchpilot.ui;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class ReorderListTest
{
	private static final int[] FIVE_ROWS = {40, 40, 40, 40, 40};

	@Test
	public void takesTheNearestSlot()
	{
		assertEquals(0, ReorderList.nearestSlot(FIVE_ROWS, 4, 0));
		assertEquals(1, ReorderList.nearestSlot(FIVE_ROWS, 4, 44));
		assertEquals(3, ReorderList.nearestSlot(FIVE_ROWS, 4, 140));
	}

	@Test
	public void switchesSlotHalfwayBetweenThem()
	{
		assertEquals(0, ReorderList.nearestSlot(FIVE_ROWS, 4, 21));
		assertEquals(1, ReorderList.nearestSlot(FIVE_ROWS, 4, 23));
	}

	@Test
	public void staysWithinTheList()
	{
		assertEquals(0, ReorderList.nearestSlot(FIVE_ROWS, 4, -100));
		assertEquals("after the last of the five", 5, ReorderList.nearestSlot(FIVE_ROWS, 4, 1000));
		assertEquals("a list of one has only one slot", 0, ReorderList.nearestSlot(new int[0], 4, 50));
	}

	@Test
	public void allowsForRowsOfDifferentHeights()
	{
		int[] mixed = {60, 30};
		assertEquals(1, ReorderList.nearestSlot(mixed, 4, 70));
		assertEquals(2, ReorderList.nearestSlot(mixed, 4, 95));
	}
}
